INSERT INTO `wp_options` VALUES (9311,'_site_transient_feed_d117b5738fbd35bd8c0391cda1f2b5d9','a:6:{s:5:\"child\";a:1:{s:0:\"\";a:1:{s:3:\"rss\";a:1:{i:0;a:6:{s:4:\"data\";s:3:\"\n\n\n\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:7:\"version\";s:3:\"2.0\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:1:{s:0:\"\";a:1:{s:7:\"channel\";a:1:{i:0;a:6:{s:4:\"data\";s:112:\"\n	\n	\n	\n	\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:1:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"WordPress Planet\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:28:\"http://planet.wordpress.org/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"language\";a:1:{i:0;a:5:{s:4:\"data\";s:2:\"en\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:47:\"WordPress Planet - http://planet.wordpress.org/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"item\";a:50:{i:0;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:108:\"WPTavern: #242 – Mark Westguard on How WordPress Adapts to Rapid Change: the Dot-Com Bubble to AI Hysteria\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:48:\"https://wptavern.com/?post_type=podcast&p=209930\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:122:\"https://wptavern.com/podcast/242-mark-westguard-on-how-wordpress-adapts-to-rapid-change-the-dot-com-bubble-to-ai-hysteria/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:53031:\"<details>Transcript<div>\n<p class=\"wp-block-paragraph\">[00:00:19] <strong>Nathan Wrigley:</strong> Welcome to the Jukebox Podcast from WP Tavern. My name is Nathan Wrigley.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Jukebox is a podcast which is dedicated to all things WordPress. The people, the events, the plugins, the blocks, the themes, and in this case, how WordPress adapts to rapid change the .com bubble to AI hysteria.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you&#8217;d like to subscribe to the podcast, you can do that by searching for WP Tavern in your podcast player of choice, or by going to wptavern.com/feed/podcast, and you can copy that URL into most podcast players.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you have a topic that you&#8217;d like us to feature on the podcast, I&#8217;m keen to hear from you and hopefully get you, or your idea, featured on the show. Head to wptavern.com/contact/jukebox, and use the form there.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So on the podcast today we have Mark Westguard. Mark has been building websites for over 30 years, starting out in the early days of the web with his agency, Absolute Internet in the UK, before moving to the US and transitioning into product development. He now runs WS Form, a form plugin for WordPress.</p>\n\n\n\n<p class=\"wp-block-paragraph\">During this episode, we get into the evolution of the internet and WordPress through major technological inflexion points. Most recently, the rise of AI. Mark draws comparisons between the AI era and the frenzy of the .com boom, sharing how rapid influxes of investments and hype, can reshape the entire landscape, often faster than the underlying technology can deliver sustainable results.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The conversation focused not just on the opportunities AI brings to developers and end users, such as dramatically lowering the barrier to entry for building websites or plugins, but also the risks and challenges.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We chat about the overwhelming pace of new product creation, and how the real difficulty today isn&#8217;t necessarily building a plugin, but successfully marketing, supporting and sustaining it in a crowded ecosystem.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Towards the end, we talk about the potential saturation of plugin marketplaces and what this means for the future of WordPress businesses, especially as AI continues to accelerate product development.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Mark says that he&#8217;s embracing AI in his own workflow, but has some nostalgia for the days when coding was a hands-on craft.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Several other points were raised, including the ongoing demand for trusted, supported, software among non-developers, the looming spectre of AI driven security vulnerabilities, and whether traditional CMS platforms like WordPress might see a renaissance if AI hype collapses.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you&#8217;re curious about how AI is shaping, and challenging, the future of WordPress development and product businesses, this episode is for you.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you&#8217;re interested in finding out more, you can find all of the links in the show notes by heading to wptavern.com/podcast, where you&#8217;ll find all the other episodes as well.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And so without further delay, I bring you Mark Westguard.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I am joined on the podcast by Mark Westguard. Hello, Mark.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:03:34] <strong>Mark Westguard:</strong> Hello Nathan, how are you?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:03:35] <strong>Nathan Wrigley:</strong> Yeah, good. We&#8217;re going to have a little bit of a chat today about the landscape of WordPress in the era of AI. Let&#8217;s explore and see where we go.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So Mark, before we begin, bio time, basically, would you give us your little bio? Tell us what you do in the WordPress space.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:03:50] <strong>Mark Westguard:</strong> In the WordPress space, currently I&#8217;m running, WS Form, which is an online form plugin for WordPress.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And I&#8217;ve been in the web game far too long. People can&#8217;t see our grey hairs, but I&#8217;ve been building websites for, oh, I want to say about 30 odd years now.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Yeah, I&#8217;ve gone through everything from Netscape Navigator through to where we are now with AI. So, have been building websites for many many companies, for many many years.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So I had a agency in the UK called Absolute Internet back in the day, back in 1996. And then moved to the States in 2005 and carried on with that, and then got into product about, I want to say eight years ago now. And have been enjoying it, but still dabbling in the agency side of things as well.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:04:34] <strong>Nathan Wrigley:</strong> Okay, so you&#8217;ve had a long and storied history. Has there ever been a moment where it&#8217;s felt like so much was in flux, in your past? Because, I think anybody really listening to this would have some intuition that AI is a moment of great inflexion point. Maybe this is par for the course though, over a 30 year period in the internet. Has there been anything which has disrupted things or changed things as rapidly as this?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:04:56] <strong>Mark Westguard:</strong> I think, for me it was strange because the internet was there when I started university, but definitely was a big game changer for how we accessed information and searched for information.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The next big thing for me was really the .com bubble, and that going bang quite tremendously, which pulled my first agency into the ground. I mean, we went from 40 odd staff to four people in a day. So that was certainly a big flux in the internet industry that hit me.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Once that recovered, it&#8217;s been fairly plain sailing, hasn&#8217;t it? There&#8217;s been a lot of gentle progression in the internet game. We&#8217;ve seen CSS 2, CSS 3. We&#8217;ve seen HTML get a little bit better here and there, standards have improved. But nothing like AI. I mean, I remember the first time I typed a question into a bot and got a response back and I was like, okay, this is going to change things.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So yeah, we&#8217;re definitely in a big evolution here and one that I think is way more rapid than internet hitting us as well.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:05:58] <strong>Nathan Wrigley:</strong> I think the bit that makes it so profound is the fact that we&#8217;ve given over so much of ourselves to the internet. So during the .com boom, there were, I don&#8217;t know, how many desktop computers in the UK. I imagine there&#8217;s significantly more than there were then than there are now. You know, you had to go and find a computer, sit at a computer, switch the computer on, use things like dial up modems to get access.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:06:22] <strong>Mark Westguard:</strong> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:06:23] <strong>Nathan Wrigley:</strong> And all of that kind of stuff, many obstacles. And now everything is in your pocket. So we do commerce in our pocket. We communicate from our, the device in our pocket. In other words, everything is wedded to the internet.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So the idea of things changing rapidly because we&#8217;ve become so accustomed to the internet being kind of like a utility. The rapid change is more profound, even if the change itself might not be so rapid.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Can I actually go back to the .com boom and bust bit? Because I bet a significant proportion of the people listening to this won&#8217;t even know what that was. Do you want to describe it, and how it crept up on you and overnight just decimated probably billions of dollars from stock markets?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:07:05] <strong>Mark Westguard:</strong> Yeah, it was around about, I want to say 2000, right when it hit. And when we first started as an agency, I was building websites using university computers. I didn&#8217;t own a computer. This is what you were talking about. Not everybody could have afford that technology back then.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But we were building websites for the most bizarre stuff. We had people coming in saying, I want to sell curry online. And I want to, anything and everything that they could come up with as with an idea, they were getting funding for.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And we were dealing with small one man bands, but we&#8217;re also dealing with big companies that had huge investment, that was pumped into these internet ideas. And it&#8217;s kind of similar to what&#8217;s happening with AI right now.</p>\n\n\n\n<p class=\"wp-block-paragraph\">There&#8217;s an immense amount of money being invested into it. And the internet went from a handful of university websites, to everybody doing all manner of things online. The investment just got over the top. And then at some point somebody went, you know what, these investments have no ROI on them. There&#8217;s huge amounts of money being poured into this. And, basically the stock market crashed as a result of it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And we had companies literally within a week saying, we are no longer going to be continuing our management contracts with you. Or we don&#8217;t want to build this website with you anymore. We were building $2 &#8211; 300,000 websites for the likes of Safeway and Sony and KPMG and all kinds of stuff. And it just stopped overnight. And it caused a lot of agencies to fall over, just completely fail, within a matter of months.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:08:37] <strong>Nathan Wrigley:</strong> I remember seeing an ad, I was on Kensington High Street in London. I used to work on Kensington High Street, and I remember seeing an ad on a bus stop. So it was a prime bit of real estate in the UK, probably one of the more expensive places that you could put an ad. And it was for an internet product. And the product was that they would come to your workplace, take your shirt, iron it, and bring it back to you. And I remember looking at ad and thinking, is that really what they&#8217;re selling? Genuinely? Like, is there a market for that? And obviously, within a month the .com bubble had burst.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But it was on that level, wasn&#8217;t it? It was the most peculiar ideas that people could come up with. And maybe some of them would&#8217;ve swum now. But back then, everything was sort of sinking. But also nobody had a mechanism to pay for it. We didn&#8217;t have the sort of access to credit and credit cards and Stripe and all of those payment gateways and all of that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">It was just, we were falling over ourselves to put ideas out there. Nobody seemed to have the capacity to say, no, look objectively, that&#8217;s a silly idea. That there&#8217;s no business there. It was more, let&#8217;s try it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And then eventually a bit like happened with the Dutch and the tulips way back. Somebody woke up and said, hang on, there&#8217;s no money being generated by these things. Then presumably the bankers all took one look at each other and went, oh, what have we done.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:10:04] <strong>Mark Westguard:</strong> Yeah. And there were a lot of big, big ideas out there that caused a lot of that. I had one guy that came in and I won&#8217;t mention the project name, to save the guy&#8217;s grace. But he had come up with an idea to do an online training platform for children. And this guy we found out afterwards had maxed out his credit cards, had remortgaged his house, had got divorced from his wife, and a tiny part of the reason for the collapse around 2000. But it was that kind of thing that was happening all over the place.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:10:35] <strong>Nathan Wrigley:</strong> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:10:36] <strong>Mark Westguard:</strong> We are seeing a similar thing happening now with AI. There&#8217;s a huge amount of investment going into it. Now I&#8217;m in no way an expert in the financial world and of investment in AI platforms and stuff, but hopefully we don&#8217;t see as big a bang as we did back then.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:10:50] <strong>Nathan Wrigley:</strong> It felt, at the time, it felt really normal until it suddenly didn&#8217;t. Until I saw that ad for that shirt ironing business, I genuinely I just thought, oh, that&#8217;s a good idea. Oh, that&#8217;s interesting. Look what they&#8217;re doing. Look what you can do now. Ads over and over again.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But then as soon as it starts to unravel, you begin to get the intuition. Wow, that really was hysteria. We were all caught up in this hysteria. Whether or not you are a financial expert, it must be obvious to everybody that we are caught up in some kind of AI hysteria at the moment.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Now, it may be that 80% of all of the business ideas based around AI will succeed. Maybe it&#8217;ll be that 80% of them will fail. But have you got any intuitions that point to it being over egged, hysteria? Are there any things that you&#8217;ve seen out in the real world where you&#8217;ve thought, boy, that really does feel like a moment where we ought to be thinking about whether we&#8217;re caught up in mass hysteria here?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:11:48] <strong>Mark Westguard:</strong> I think AI for me is like the next logical progression. We&#8217;re talking about coding here, right? AI is used for lots of different things, but in terms of coding, it&#8217;s like the next logical transition in terms of making coding accessible.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So if I think back to when I was in college and I was writing machine code for chips, literally like bite by bite, that was quite complicated. And then came along programming languages where we could not have to worry about the machine coding. And then we&#8217;ve got things like, for example Basic on a computer, which meant you didn&#8217;t have to worry about some of the more underlying code underneath that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And then came the internet with HTML. And then we had page builders. Now I&#8217;ve got AI where we don&#8217;t even have to think about writing a line of code. You can literally just ask it what you want, and hopefully you&#8217;ll get out of it what you want. At every stage it has made working with a computer, and making a computer do something more accessible to more people.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So now my father can just go online and say, hey, build me this website. I want a green background. I want this font, I want it to say this. Write me a paragraph about such and such, and they can pretty much whip something up in an afternoon. A year ago, two years ago, that was him having to learn how to code to do that, or would have to use a drag and drop page editor to do that. So it really has opened up the ability to develop software and websites to a lot more people.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The thing that I&#8217;m seeing is there&#8217;s an awful lot of ideas being developed. People are coming up with ideas. Some people not actually thinking about, is this a project that&#8217;s got legs? Do people need this? There&#8217;s a lot of repetition going on. There&#8217;s a lot of things being built where really, even if you build a website solution or a piece of software, you&#8217;ve still got to market that. You&#8217;ve still got to support it. You&#8217;ve still got to get it out to the masses.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And AI&#8217;s not quite there with that yet. I can&#8217;t just say, right I&#8217;ve built this product, go and market it for me. It&#8217;s still going to need some feet on the ground to actually go out there and sell a product.</p>\n\n\n\n<p class=\"wp-block-paragraph\">When I got into software and I developed WS Form, building the actual plugin was a lot easier than actually getting out there and getting people interested in it, and telling people about why it&#8217;s a good product. That&#8217;s what took the time.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:13:57] <strong>Nathan Wrigley:</strong> That&#8217;s a curious insight. So we are in a moment now where almost anybody who&#8217;s got the capacity to type on a computer can build anything. And I&#8217;m seeing that over the internet at the moment. You said multiple things.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So there&#8217;s this person that I follow online, I won&#8217;t mention their name. They&#8217;re not in the WordPress space at all. And if you follow their trajectory, about a year ago, they clearly got the intuition that they could build an app. And so they did for the Mac, and it was really great. It was really good little app and it served its purpose. It was quite a small thing.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Now, a year later, I would think it&#8217;s probably fair to say they&#8217;ve probably got about 15 apps. And there was some moment, and I don&#8217;t know when it was, probably about the 10th one in, I suddenly thought, how does this person maintain this? Is this just a case of just, okay, let&#8217;s build another and another and just keep going through that process. Selling, selling more, selling, more selling. But at what point do the people buying that app get the support that they need and the bug fixes that they need? And that I think is maybe a moment that we haven&#8217;t yet faced.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:15:02] <strong>Mark Westguard:</strong> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:15:02] <strong>Nathan Wrigley:</strong> The marketing bit. You&#8217;ve built a plugin with AI for WordPress, but you don&#8217;t have the capacity to market it. So you build another one, and you build another one, and you build another one. But the few people that bought it, they&#8217;re going to expect updates and what have you. What I&#8217;m basically trying to do is agree with what you said. The wider bit is the harder bit. The selling it, not just building it, and then making sure that those people come back for more later.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:15:25] <strong>Mark Westguard:</strong> Yeah, I think that&#8217;s one part that a lot of people are missing. I&#8217;m seeing a lot of people saying, hey, I built this and I&#8217;m making X million per month. I don&#8217;t believe a lot of those posts that you see, with these get rich. If that was the case, everyone would be doing it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But, I love AI. It&#8217;s made my ability to bug test and launch new features so much quicker, and so much more efficient. I just worry that there are so many people jumping into wanting to build businesses with it without thinking about all the other stuff that you&#8217;ve got to do to make that business a success.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And that&#8217;s kind of what I saw back in the two thousands. I saw a lot of people just coming up with ideas, running with it. They were starters but they weren&#8217;t finishers. And the actual marketing of that idea, and getting it supported and everything else was the they fell on.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Yeah, it&#8217;s, an interesting time and it&#8217;s really hard to keep up with it all because it&#8217;s moving so quickly. That&#8217;s the bit that for me is a challenge, is just keeping up with the best thing to do. And there are so many people online, on social media that are trying to tell you the best way of doing it. Everyone&#8217;s got their own, way of doing it. I&#8217;ve had to switch a lot of it off. It&#8217;s overwhelming.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:16:29] <strong>Nathan Wrigley:</strong> Okay, so that&#8217;s a curious insight. And it was where I was going to go next. I genuinely don&#8217;t know what our capacity is to consume this. I don&#8217;t know where all the people are going to come from to buy all these things. In order for us to to buy all these things, we must all be earning to pay for all these things. And in order to earn, we all need to be selling our own things or doing some kind of lucrative work somewhere. You know to shell out for these things.</p>\n\n\n\n<p class=\"wp-block-paragraph\">That&#8217;s the bit that I&#8217;m concerned about. I don&#8217;t see where all of these products are going to get revenue from. In the WordPress space, let&#8217;s cast our minds back three years. Competition was tough already. You know, you&#8217;re in a fairly competitive landscape, WordPress forms, there&#8217;s several solutions for that. So that&#8217;s already competitive.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Now if you flood the zone with 10 more, 15 more, a hundred more, that means it&#8217;s much more difficult for everybody to achieve the sort of the weight that they need to have to make that profitable.</p>\n\n\n\n<p class=\"wp-block-paragraph\">It&#8217;s very hard to encapsulate what I&#8217;m trying to say, but it basically boils down to what is our capacity to attend to all of this stuff. And I was thinking this morning, coincidentally before you and I joined the call, I was thinking before computers came along, I know life wasn&#8217;t as rich and wasn&#8217;t as varied, but it was a heck of a lot less noisy. And we really do allow a lot of noise to get into our lives. And it feels like AI, WordPress, it&#8217;s very noisy at the moment. And I don&#8217;t think we&#8217;ve yet crossed that Rubicon. The noise, it&#8217;s become obvious to us how disruptive that noise was.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:18:07] <strong>Mark Westguard:</strong> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:18:08] <strong>Nathan Wrigley:</strong> I think we&#8217;re still, in many cases, plugin vendors and theme vendors and things are still relying on previous year&#8217;s subscription to renew, but it&#8217;s the next year that I worry about and the year after that. And I don&#8217;t know if you&#8217;ve got any wisdom there.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:18:23] <strong>Mark Westguard:</strong> It&#8217;s an interesting time. I think there&#8217;s a lot of experimenting going on that is being portrayed as the way to do things. There&#8217;s a lot of people, I guess there&#8217;s a lot of people panicking. There&#8217;s even a lot of people in the WordPress world that have gone from WordPress to now saying, I&#8217;m not doing WordPress anymore, and they&#8217;re now a hundred percent AI. And, are they actually producing things that are making them a living? Other than maybe, some of these online content producers. Are there solid products that are coming out of AI?</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you just look at the plugin repo, the number of plugin submissions has gone through the roof because so many people can now just produce utility plugins so quickly and easily. There are still only a handful of people out there actually producing proper products, that are selling as plugins for WordPress, sizable plugins that are really expensive to build with AI. I&#8217;m fortunate that I didn&#8217;t have a suite of small utility plugins. I had quite a large form engine that I intentionally built to be quite complicated, and that&#8217;s kept me afloat.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:19:23] <strong>Nathan Wrigley:</strong> Oh, I see. You&#8217;ve got like a walled garden around your product a bit because of its complexity, but also it&#8217;s not a utility in the sense that you toggle something on and then something happens on your website. I don&#8217;t know, SMTP plugin or something like that. It just this one thing and it does it, and that&#8217;s all it does.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Yours is much more broad, deep, there&#8217;s a learning curve, but also it performs an essential function on the website. If that was to go away, your forms disappear from your website, that&#8217;s catastrophic potentially. So you&#8217;ve created a bit of a moat around yourself because of that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:19:57] <strong>Mark Westguard:</strong> Yeah, I don&#8217;t think I created it. I just think that happened. Almost the marketing of the product has changed. I used to be pushing, hey, no code forms just drag and drop. Some people don&#8217;t even use the UI anymore. They literally are just using AI to talk to it, because it has the MCP server on it. So it has become more of an engine than a user interface for building a form.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And, we were going to talk briefly about block themes and stuff, on this call and I had recently transitioned my theme on my website from a classic theme to a block theme. And the amount of work that went into that was a lot more than I thought it was going to be with AI. And that&#8217;s because I think AI still is filling in the holes a lot.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So, the more vague your prompt is, the more AI&#8217;s got to do to fit in the gap. So if I just say to it, build me a website, it&#8217;ll build you a website, but you are going to have, umpteen different things that it has assumed that you want along the way.</p>\n\n\n\n<p class=\"wp-block-paragraph\">When I was building my block theme, using AI, there was a lot of prompting I had to do to get it to look the way I wanted it to look. And it took a lot more, I forget how many prompts it was now. It was several hundred prompts in the end to get it where I wanted it to be.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Glad I did it. And I did it a lot quicker than I would&#8217;ve done had I hand coded it for sure. And it did things that I am not very good at doing, like writing a block from scratch, that&#8217;s still something that I struggle with, and it was really helpful to be able to do that with AI.</p>\n\n\n\n<p class=\"wp-block-paragraph\">You see this in social media, people saying, oh, that guy&#8217;s built a website and it looks like it was built from AI. And that&#8217;s basically AI fitting in the gaps with what it&#8217;s been taught that people want. Certain fonts, certain things like that. So you can definitely use it to, I&#8217;ve completely digressed here but, you can definitely build it to build things quicker, but it still takes time to prompt it properly.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And also with someone with programming knowledge, I&#8217;m still steering it in certain directions to make it work the way I want, and to make it work efficiently. I&#8217;ll still look at code that AI generates and be like, what are you doing?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:21:51] <strong>Nathan Wrigley:</strong> I was just going to interrupt there and say, I guess the curious bit about this is that in in every epoch until now, the frailty of the human being, our capacity to forget things, the fact that we can only allocate a certain amount of our brain to a given task. We require sleep and all of these kind of ordinary things. And we get unwell, we&#8217;re not always as efficient one day as we are the next, because we went out the night before, and those kind of things.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I suppose that is also a part of the jigsaw puzzle, which has me concerned, is that the state of AI. Let&#8217;s assume a trajectory which is the same as the last five years. Let&#8217;s assume that in the next five years the trajectory&#8217;s going to be the same. Of course it may not turn out that way, but let&#8217;s assume that it does. The worst is now. The worst that an AI can do is today, and tomorrow it will be better, and the day after that, it will be better. And it will never be worse.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And so those little wrinkles that you described, you have to prompt it 200 times to get yourself a website. You&#8217;ve got to assume that the combined kind of Borg-like, that&#8217;s a Star Trek analogy, kind of Borg-like nature of AI, is that in a year&#8217;s time, it&#8217;ll be a hundred prompts. The year after that, or six months after that, it&#8217;ll be down to 50, and then 20, and then 10. And you get what I&#8217;m saying.</p>\n\n\n\n<p class=\"wp-block-paragraph\">You know, it just get&#8217;s exponentially better. It never gets worse. That, I think, is the bit that me the most. Is that because it&#8217;s beguiling and because as technologists we love shiny stuff, that we don&#8217;t see this giant problem building behind our backs. That if we&#8217;re constantly beguiled by the shiny, and we give everything over to the AI, maybe there&#8217;ll come a point where we look and we suddenly realise, oh, it&#8217;s now superior than I am in every single regard in terms of website building. So who&#8217;s going to use my services anymore?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:23:42] <strong>Mark Westguard:</strong> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:23:43] <strong>Nathan Wrigley:</strong> And I find this a curious thing in the WordPress space, because a lot of people seem to be hyping AI to the exclusion of their future selves.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:23:54] <strong>Mark Westguard:</strong> Yeah. Yep.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:23:55] <strong>Nathan Wrigley:</strong> But they can&#8217;t, it&#8217;s irresistible. You have to do it, because if you don&#8217;t, your competitor will. And so you know, the arms race argument comes out and on we go. And it&#8217;s a curious thing that we&#8217;re in this moment.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:24:08] <strong>Mark Westguard:</strong> It&#8217;s a funny time for sure. It&#8217;s the buzzword. It&#8217;s what everybody&#8217;s focusing on right now. I&#8217;m doing it. I am using it as much as I can. It&#8217;ll be silly for me not to do that. I embrace it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">You know, I was working with James LePage and his team at Automattic when they were developing all of the different AI building blocks. And he very kindly kept me ahead of what was going on there.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And I&#8217;m very thankful for that because it&#8217;s one of the things that&#8217;s made my product ahead of some of the competition. And I&#8217;ve got people now recommending WS Form because of the AI capabilities that it has.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But it&#8217;s a completely different way of thinking and working from what I was used to. For me to add a new feature meant adding a new UI interface for it, and writing all of that from scratch. And we were talking before this call that I would probably spend a day or two implementing a new feature and working it out. And I used to love that. That used to be good for my brain.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And I was thinking the other day, I am getting to the point where I&#8217;m not thinking anymore. Because I, it just, it&#8217;s doing the thinking part of it for me. But my experience in building just that block theme from my website taught me that, much like going to an agency and telling it what logo you have and what colours you have and how you want things to look and how you want things spaced out. All of that initial discovery period still needs to be done with AI in order to get it to do what you want.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Now, like you say, it&#8217;s going to be able to do that more and more efficiently. You see that with like Claude design where you can set up a, I forget what they call it now, but you kind of build like a design set.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:25:39] <strong>Nathan Wrigley:</strong> Yeah, like a brand kit kind of thing?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:25:40] <strong>Mark Westguard:</strong> Yeah. Where you give it your logo and your styling and everything else. And you can give it, even the current web address of your site and it&#8217;ll feed that in. And then it can then use that to build new elements.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So, there&#8217;s still a lot of prompted stuff that goes on. I think there&#8217;s a little bit of a myth that you can literally one prompt AI for a lot of things, and get some output from it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">One of the interesting things for me is I went to an AI event once, and I met a guy who was, I think he was ex OpenAI. And he said to me and this may or may not be true, but the fundamental software powering everything in AI, the concept behind it has kind of hit a threshold. And what we are now doing is tweaking that and making that work better. We&#8217;re tuning it, fine tuning it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And that&#8217;s where we see an improvement in AI and obviously in processor speed and everything else that&#8217;s going on. So it&#8217;s interesting that kind of the fundamentals of AI are really at a maximum, in terms of what it can do. But it&#8217;s really human tweaking it and training it that&#8217;s making it work an awful lot better. And I think that&#8217;s where a lot of the improvements are going to come from.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:26:38] <strong>Nathan Wrigley:</strong> You mentioned a little bit ago that you&#8217;ve really not required to write code anymore in order to improve your plugin. You can get AI in the loop there and tweak it and iterate on it that way. Do you miss that though?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:26:51] <strong>Mark Westguard:</strong> Yeah, I really do.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:26:53] <strong>Nathan Wrigley:</strong> Is there a bit of you that you could close the box on AI and just rewind the clock and go back to the way it was? Because presumably it wasn&#8217;t all roses and unicorns over there. It was hard work and probably kept you awake at night and you&#8217;re banging your head against the desks, or how do I do this? Is there some kind of halcyon days thinking there, you know, ah it was better before AI. Would you parcel it up and send AI packing if you could, or are you more happy with it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:27:18] <strong>Mark Westguard:</strong> It&#8217;s a love hate relationship for sure. Love hate relationship. I think, much like a carpenter loves doing woodwork. I used to love coding, call me a nerd. But that was my trade. That&#8217;s what I did. And I used to love working things out. And that working out is what kept my brain ticking over.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Now if I have something I need to do, I can get AI to build it. Now, I will absolutely, and that&#8217;s hopefully where the quality of my product comes is, I&#8217;ll go and check what it&#8217;s written. I won&#8217;t just implement it and launch it. I will always check what it&#8217;s done, and nine times outta 10 I&#8217;ll find better ways of doing it. Just because of the way that it&#8217;s implemented it. It may not understand that I&#8217;ve got a method in my code somewhere that already does that. So I don&#8217;t want it to recode it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But the more and more I use it, the more it seems to understand my code base, and the way it works. And it&#8217;s getting better and better. It is like having an assistant in the office that can just deal with the coding for me now. But I do miss it. I really do. Sometimes I&#8217;ll just get my hands dirty and do a bit of coding for the old days, but I sit there thinking I could have just prompted AI and it would&#8217;ve done it in five seconds. So it&#8217;s yeah, it&#8217;s weird.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:28:22] <strong>Nathan Wrigley:</strong> It&#8217;s almost like a hobby. You take time off and pursue a hobby of coding as opposed to the business of coding, which is kind of curious.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:28:28] <strong>Mark Westguard:</strong> Yeah. And I do miss that. Yeah. And it was a hobby. You would get questioned sometimes, what&#8217;s your hobby? And I&#8217;d think, oh, is it? What do I? Do I write swimming or, or eating at a restaurant? I&#8217;m like, no, I actually, yeah, I used to love coding. My hobby was my job, and I was very lucky in that regard that I was doing what I enjoy doing as a career. So that, yeah, part of that&#8217;s missing now. And I do miss it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But at the same time, I love technology and I love seeing new things come to fruition. And I&#8217;ve loved learning about and taking advantage of AI. And there&#8217;s been things in my product that people probably aren&#8217;t even aware that are little bugs that have just been niggling at me that I&#8217;ve never got round to fixing.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:29:08] <strong>Nathan Wrigley:</strong> And now you can.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:29:08] <strong>Mark Westguard:</strong> I just spend a day and I&#8217;m just like, you know what? Fix that little pixel that&#8217;s out that&#8217;s been bugging me all these years, and it&#8217;ll work it out for me.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:29:16] <strong>Nathan Wrigley:</strong> I am so torn on this subject because I, like anybody that enjoys technology, I really love when I see a new thing. Whether that&#8217;s a piece of hardware or software or the capacity of somebody to do something new, raising the standard of people to do a thing. So on that side of it, it&#8217;s all, like I said, unicorns and rainbows. It&#8217;s brilliant.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But there is a bit of me, which I think growing in size, which is very concerned. And there are so many underpinnings to that. The people growing up now presumably will not be able to go through the process of learning that you went through. Because what would be the point in spending all those hours learning to do all of the things that you had to do and bang your head against the desk. And so that worries me.</p>\n\n\n\n<p class=\"wp-block-paragraph\">It worries me that if we flood the landscape, our capacity to engage with that is going to go away. Like, how many Mac apps can we have and how many WordPress plugins can we have? At what point does that marketplace become so saturated that nobody can make a living from that anymore? I don&#8217;t know if that&#8217;ll turn out to be the case. But there&#8217;s just this niggling thing that there&#8217;s maybe going to be some correction.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And I think the bit, which seems to be raising its head at the moment is AI&#8217;s capacity to go out and cause mischief in terms of security vulnerabilities and hacking and things like that. And I do wonder if that will be the thing which enables governments, for example, or regulatory authorities and things like that, to say, wait, the brakes need to go on now.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:30:54] <strong>Mark Westguard:</strong> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:30:55] <strong>Nathan Wrigley:</strong> We need to figure out how was this allowed to happen? How is it that our banking systems collapsed? Or how is it that the fridges all got switched up to 50 degrees centigrade?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:31:04] <strong>Mark Westguard:</strong> Which they did.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:31:04] <strong>Nathan Wrigley:</strong> Which they did. How did we allow this to happen? But at the moment, we&#8217;re in that kind of free market phase of let it all go wild. But I&#8217;m not sure that&#8217;s going to be possible forever.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:31:16] <strong>Mark Westguard:</strong> I think it&#8217;s going wild on the software side. It&#8217;s also going wild just on the infrastructure side right now. The amount of money that&#8217;s being pumped into building these server farms and everything else, it&#8217;s just off the charts crazy.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Who knows how much this stuff actually costs to run. I feel like we&#8217;re in an age where we&#8217;re getting quite a good deal on this stuff at the moment. Because we&#8217;re in the initial Google phase where Google didn&#8217;t have Google ads. It was literally just a search engine and losing huge amounts of money.</p>\n\n\n\n<p class=\"wp-block-paragraph\">It was only when they monetized it that they started to make some kind of profit, and even that took them a long long time. And we are there with these AI farms. They&#8217;re huge buildings, massive amounts of investment. And we are paying $20 a month to utilise, effectively, we&#8217;ve each got a super computer from a decade or so ago on our desk now.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:32:02] <strong>Nathan Wrigley:</strong> Yeah you&#8217;ve got God-like capabilities for a few dollars a month.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:32:05] <strong>Mark Westguard:</strong> I know. Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:32:06] <strong>Nathan Wrigley:</strong> It&#8217;s genuinely insane. Okay. So that&#8217;s an interesting point as well. I wonder, so two things here.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The first one is, I wonder if a potential course correction there. The economic model turns out to be unsustainable. And it either collapses or it slowly sort of changes and the fees go up and the capacity to use it goes down. So there&#8217;s that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But also, I wonder if more local AI systems where you download something onto your computer and utilise it there. As opposed to needing the big thing out in the, server farm, the data centre, nobody wants them near their backyard. It certainly seems like that in the UK and it sounds like North America is the same.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The follow on from that is then I wonder if there will be some kind of resurgence for older technology like WordPress. Okay, that was all a bit of fun. We all had a great time playing with the AI, but now that it&#8217;s gone in the way that we got familiar with, let&#8217;s just revive all the things that we knew used to work. Like our old trusty CMS, WordPress.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I think that&#8217;s that&#8217;s a possibility, right? The curiosity will dwindle in AI and it will return. Certainly that seems to be the kind of pivot that a lot of people in the WordPress space are hoping for. You know, that AI won&#8217;t be able to update your website in the way that clients wish. Use a trusty CMS. AI is going to collapse. Don&#8217;t worry, you&#8217;ve got the old technology like WordPress, that CMS in your back pocket.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I don&#8217;t know if any of those will turn out to be the truth, but certainly an interesting piece to put on the chessboard.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:33:37] <strong>Mark Westguard:</strong> Yeah. And I talk to a lot of plugin developers. Obviously, I&#8217;ve got a big community of friends that build plugins and we&#8217;re all seeing a decline in new customers. And I think part of that is economy. I think part of that is AI. I think that when I think about it and I look at who I&#8217;m looking at like on social media, a lot of those people are very good developers. They&#8217;re people that are pretty high up on the WordPress ladder, and developed tools and have developed software themselves.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But there&#8217;s still a massive user base in WordPress of people that just want to buy a piece of software that&#8217;s tried and tested and works. And don&#8217;t want to have to work out how to do that with AI. And go through that because, you could, get AI and say, okay, build me a plugin. And then they&#8217;re like, okay well, how do I deploy that? How do I test it? How do I do the security on it? Anyway, there&#8217;s a lot that goes into it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And building stuff from scratch, sometimes, isn&#8217;t the best way of doing things. For a lot of people that are developers and know how it all works, it&#8217;s great. I can build utility plugins day in, day out now. I don&#8217;t even build custom field stuff. I don&#8217;t even use a custom field plugin now because I can do that with AI for my own theme. I don&#8217;t need it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If I build a site for a customer, then a lot of the custom stuff I am just writing myself because it&#8217;s a few lines of code and AI can do that for me. But there&#8217;s still people that aren&#8217;t developers. They&#8217;re not coders and they just want to be able to buy a bit of software for 50 bucks or whatever, install it, and then it does its job.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:35:00] <strong>Nathan Wrigley:</strong> So that&#8217;s a curious thing. And I would fit into that camp. If you took me into any industry apart from web development, WordPress, and you asked me to be confident with, okay, you&#8217;ve got the AI thing over here, or you&#8217;ve got the $50 thing over there, which somebody else is going to maintain, and you can kind of phone them up if the products itself wouldn&#8217;t work.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Genuinely I&#8217;m going to pay for the $50 thing, or the a hundred dollars thing. I would never rely on AI. And think about WordPress websites. The amount of clients that I had over the years, who wouldn&#8217;t even dare to click the save button, because they were terrified that what they were about to do might in some way just destroy the website, you know, and and they would constantly seek reassurance. Are you sure that I can click save? Yeah. Yeah. click save. It&#8217;s absolutely fine. Those people are not going away anywhere.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Although we may become slightly more forgiving of AI, and slightly more trustworthy of it. I think most people in the world, most people in the world, let&#8217;s say this sentence again, have never touched an AI.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:35:57] <strong>Mark Westguard:</strong> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:35:58] <strong>Nathan Wrigley:</strong> They don&#8217;t even know how to interact with it. They wouldn&#8217;t know what to do with it if you put it in front of them.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We&#8217;re that tiny cabal of people who because we&#8217;re on the computers already every day AI and code kind of fit hand in glove, we assume that the rest of the world is happy with this stuff and honestly they&#8217;re probably not.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:36:16] <strong>Mark Westguard:</strong> Yeah, and the WordPress world is not a hundred percent developers using it. It&#8217;s, there&#8217;s a lot of just regular end users that want to build a website, or have in the past maybe installed a classic theme or a block theme, or gone to a developer to build themselves the site. But they&#8217;re still using blocks of software to this day.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I mean, every customer that I&#8217;ve got is built on WordPress. They&#8217;re happy with it, they&#8217;re still using it. I work with some very large companies and they&#8217;re still using WordPress as the foundation. And we take advantage of AI to be able to roll things out quicker, which is great.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But if I wanted to, if there&#8217;s a piece of software that&#8217;s quite complicated and that the website relies on it, I won&#8217;t necessarily build that with AI. I&#8217;ll use an off, piece of off the shelf software that is tried and tested and works, and has the support there for it. I do a lot of stuff with Salesforce, for example, and that could be quite complicated. And, it would take a while to get some of the stuff that we&#8217;ve built still done with AI. And there&#8217;s pieces of software that we are running that we just pay, 50 bucks a month for and it works, it does the job.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:37:14] <strong>Nathan Wrigley:</strong> I think it&#8217;ll be a really interesting moment in the next couple of years seeing where we get with this. Not only whether AI can financially support itself, but whether or not there are outcomes which AI presents to the world that are not aligned to our best interests. Hacking scandals, those kind of things. Whether or not we turn our backs on it and say, put it back. We did enough with AI, we had an experiment with it, and it went slightly pear shaped.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:37:37] <strong>Mark Westguard:</strong> It was great for cat videos.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:37:38] <strong>Nathan Wrigley:</strong> It was brilliant for making videos of yourself, or your politician of choice, doing something that they actually didn&#8217;t do. Those kind of things. It was a lot of fun. I mean it&#8217;s so beguiling, but who knows where we&#8217;ll get to in the year 2027, 2028.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:37:55] <strong>Mark Westguard:</strong> It&#8217;s an interesting time.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:37:57] <strong>Nathan Wrigley:</strong> Let&#8217;s hope we&#8217;re all here to. Yeah, that&#8217;s right. We hope we&#8217;re all here to experience it. Let&#8217;s knock it on the head there. Mark Westguard. Where can we find you online?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:38:04] <strong>Mark Westguard:</strong> wsform.com. Just go on there. You can find information about the product. You can find me on, I&#8217;m on Twitter, Facebook all over the place. If you search for Mark Westguard, I&#8217;m going to come up. There aren&#8217;t many Mark Westguards in the world, so.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:38:17] <strong>Nathan Wrigley:</strong> Perfect. Alright, thank you for chatting to me today. I hope that we both get through to 2027. Take care Mark.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:38:23] <strong>Mark Westguard:</strong> Take care. Bye.</p>\n</div></details>\n\n\n\n<p class=\"wp-block-paragraph\">On the podcast today we have <a href=\"https://www.linkedin.com/in/westguard/\">Mark Westguard</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Mark has been building websites for over 30 years, starting out in the early days of the web with his agency Absolute Internet in the UK, before moving to the US and transitioning into product development. He now runs WS Form, a form plugin for WordPress.</p>\n\n\n\n<p class=\"wp-block-paragraph\">During this episode we get into the evolution of the internet and WordPress through major technological inflection points, most recently, the rise of AI. Mark draws comparisons between the AI era and the frenzy of the dot-com boom, sharing how rapid influxes of investment and hype can reshape the entire landscape, often faster than the underlying technology can deliver sustainable results.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The conversation focused not just on the opportunities AI brings to developers and end-users, such as dramatically lowering the barrier to entry for building websites or plugins, but also the risks and challenges. We chat about the overwhelming pace of new product creation, and how the real difficulty today isn’t necessarily building a plugin, but successfully marketing, supporting, and sustaining it in a crowded ecosystem.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Towards the end we talk about the potential saturation of plugin marketplaces and what this means for the future of WordPress businesses, especially as AI continues to accelerate product development. Mark says that he&#8217;s embracing AI in his own workflow, but has some nostalgia for the days when coding was a hands-on craft.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Several other points were raised, including the ongoing demand for trusted, supported software among non-developers, the looming spectre of AI-driven security vulnerabilities, and whether traditional CMS platforms like WordPress might see a renaissance if AI hype collapses.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you’re curious about how AI is shaping, and challenging, the future of WordPress development and product businesses, this episode is for you.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Useful links</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://wsform.com\">WS Form</a></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 18 Nov 2026 13:00:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:14:\"Nathan Wrigley\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:1;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:14:\"Matt: New TLDs\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:23:\"https://ma.tt/?p=155526\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"https://ma.tt/2026/11/new-tlds/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:1513:\"<p class=\"wp-block-paragraph\">For the first time since 2012, there&#8217;s a new round of TLDs being created by ICANN, and we just had <a href=\"https://www.icann.org/en/announcements/details/icann-confirms-2026-round-applications-input-and-objections-period-begins-updated-17-11-2026-en\">string confirmation day</a>!</p>\n\n\n\n<p class=\"wp-block-paragraph\">I&#8217;m happy to share that Automattic is uncontested for .jazz, .php, .soul, .wordpress, .tumblr, .woo, and I personally got .matt.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We have really enjoyed <a href=\"https://my.blog/\">shepherding .blog</a> which has turned into a nice option with a pretty clean namespace (that&#8217;s why we have premium prices on renewal, not just registration) and it&#8217;s had some high profile adoption, for example <a href=\"https://github.blog/\">github.blog</a>, <a href=\"https://stackoverflow.blog/\">stackoverflow.blog</a>, <a href=\"https://seths.blog/\">seths.blog</a> (Seth Godin), <a href=\"https://tim.blog/\">tim.blog</a> (Tim Ferriss), <a href=\"https://www.noahpinion.blog/\">noahpinion.blog</a> (Noah Smith), <a href=\"https://steve.blog/\">steve.blog</a> (Steve Jurvetson), and <a href=\"https://mgs.blog/\">mgs.blog</a> (M.G. Siegler) and ~ 395,000 more. <img alt=\"🤠\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f920.png\" style=\"height: 1em;\" /></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://newgtldprogram-aps.icann.org/applications\">You can see all the still contested TLDs here</a>.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 18 Nov 2026 10:53:54 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"Matt\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:2;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:64:\"Open Channels FM: Finding Your Edge as the Web Ecosystem Evolves\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2567467\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:71:\"https://openchannels.fm/finding-your-edge-as-the-web-ecosystem-evolves/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:128:\"Remkus de Vries shares how agencies and professionals can adapt to industry changes and take charge of their business direction.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 18 Nov 2026 10:22:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:3;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:20:\"Matt: Who Wrote What\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:23:\"https://ma.tt/?p=155520\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:37:\"https://ma.tt/2026/11/who-wrote-what/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:921:\"<p class=\"wp-block-paragraph\">The debates and fire around authorship are playing out faster in literature and other languages than you may be aware of. The best summation of this so far is <a href=\"https://thepointmag.com/examined-life/the-part-about-the-machines/\">Brunella Tipismana Urbano&#8217;s translated from Spanish essay The Part About the Machines</a>.</p>\n\n\n\n<blockquote class=\"wp-block-quote is-layout-flow wp-block-quote-is-layout-flow\">\n<p class=\"wp-block-paragraph\">The role of intellectuals is to shed light on these crossroads, to, as George Scialabba <a href=\"https://www.jstor.org/stable/25007119?seq=1\">once wrote</a>, understand their contemporary moral and political significance for the present with singular originality and force. And yet, confronted with a <em>genuinely new phenomenon</em>, our intellectuals have chosen to close their eyes. They have happily chosen ignorance.</p>\n</blockquote>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 18 Nov 2026 01:20:15 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"Matt\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:4;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:53:\"WordPress.org blog: WordPress 7.2 Release Candidate 1\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://wordpress.org/news/?p=22019\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:69:\"https://wordpress.org/news/2026/11/wordpress-7-2-release-candidate-1/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:10148:\"<p class=\"wp-block-paragraph\">The first Release Candidate (“RC1”) for WordPress 7.2 is ready for download and testing!</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>This version of the WordPress software is still under development</strong>. Please do not install, run, or test this version of WordPress on production or mission-critical websites. Instead, it’s recommended to evaluate RC1 on a test server and site.</p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 RC1 can be tested using any of the following methods:</p>\n\n\n\n<figure class=\"wp-block-table\"><table class=\"has-fixed-layout\"><tbody><tr><td><strong>Plugin</strong></td><td>Install and activate the <a href=\"https://wordpress.org/plugins/wordpress-beta-tester/\" rel=\"noopener\" target=\"_blank\">WordPress Beta Tester</a> plugin on a WordPress install. (Select the “Bleeding edge” channel and “Beta/RC Only” stream.)</td></tr><tr><td><strong>Direct Download</strong></td><td>Download the <a href=\"https://wordpress.org/wordpress-7.2-RC1.zip\">RC1 version (zip)</a> and install it on a WordPress website.</td></tr><tr><td><strong>Command Line</strong></td><td>Use this <a href=\"https://make.wordpress.org/cli/\">WP-CLI</a> command: <br /><code>wp core update --version=7.2-RC1</code></td></tr><tr><td><strong>WordPress Playground</strong></td><td>Use the <a href=\"http://playground.wordpress.net/release\" rel=\"noopener\" target=\"_blank\">WordPress Playground instance</a> to test the software directly in your browser.  No setup required – just click and go!</td></tr></tbody></table></figure>\n\n\n\n<p class=\"wp-block-paragraph\">The scheduled final release date for WordPress 7.2 is <strong>December 8, 2026</strong>. The full <a href=\"https://make.wordpress.org/core/2026/10/06/wordpress-7-2-release-party-schedule/\" rel=\"noopener\" target=\"_blank\">release schedule can be found here</a>. Your help testing Beta and RC versions is vital to making this release as stable and powerful as possible. Thank you to everyone who contributes by testing!</p>\n\n\n\n<p class=\"wp-block-paragraph\">Please continue checking the <a href=\"https://make.wordpress.org/core/\" rel=\"noopener\" target=\"_blank\">Make WordPress Core blog</a> for <a href=\"https://make.wordpress.org/core/tag/7-2\" rel=\"noopener\" target=\"_blank\">7.2-related posts</a> in the coming weeks for more information.</p>\n\n\n\n<h3 class=\"wp-block-heading\">Core Changes Since Beta 5</h3>\n\n\n\n<p class=\"wp-block-paragraph\">Check out the <a href=\"https://wordpress.org/news/2026/10/wordpress-7-2-beta-1-is-ready-for-download-and-testing/\">Beta 1 announcement</a> for details on WordPress 7.2.</p>\n\n\n\n<p class=\"wp-block-paragraph\">You can browse the technical details for all issues addressed since Beta 5 using these links:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li><a href=\"https://core.trac.wordpress.org/query?changetime=11%2F10%2F2026..11%2F17%2F2026&amp;milestone=7.2&amp;status=closed&amp;group=component&amp;order=id&amp;col=id&amp;col=milestone&amp;col=owner&amp;col=type&amp;col=priority\">Closed 7.2 WordPress Core Trac tickets</a> since November 10, 2026</li>\n\n\n\n<li><a href=\"https://github.com/WordPress/gutenberg/commits/wp/7.2?since=2026-11-10&amp;until=2026-11-17\">7.2 Gutenberg commits</a> since November 10, 2026</li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 Release Candidate 1 brings additional bug fixes, accessibility improvements, and compatibility updates as the release moves closer to its December 8 launch.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Recent refinements include fixes to client-side media uploads, improvements to the new random-content redirect feature, and better keyboard navigation through a skip link in the WordPress admin bar. Additional updates improve plugin dependency messaging, script module translations, and the reliability of the HTML and Interactivity APIs.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Developers will also benefit from continued Abilities API refinements and updates to bundled libraries, including PHPMailer, Requests, getID3, and sodium_compat.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://core.trac.wordpress.org/ticket/66490\">Trac #66490</a>, <a href=\"https://core.trac.wordpress.org/ticket/66681\">Trac #66681</a>, <a href=\"https://core.trac.wordpress.org/ticket/66625\">Trac #66625</a>, <a href=\"https://core.trac.wordpress.org/ticket/66331\">Trac #66331</a>, <a href=\"https://core.trac.wordpress.org/ticket/66591\">Trac #66591</a>, <a href=\"https://core.trac.wordpress.org/ticket/65984\">Trac #65984</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">Additional Block Editor Improvements</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 RC1 includes further refinements to the block editor, addressing issues with duplicated block content, keyboard interactions on iOS, and revision previews. Improvements to the Interactivity API prevent outdated navigation responses from replacing newer content, while additional fixes improve plugin installation workflows, featured image compatibility, and link suggestions. The transition to modern SVG icons also continues throughout WordPress administration.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://github.com/WordPress/gutenberg/pull/86839\">GitHub #86839</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/86703\">GitHub #86703</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/86608\">GitHub #86608</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/78367\">GitHub #78367</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/86854\">GitHub #86854</a></p>\n\n\n\n<p class=\"wp-block-paragraph\">Want to know more about this release? Here are some highlights:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>New Ipsum default theme</li>\n\n\n\n<li>Expanded responsive design and Gallery controls</li>\n\n\n\n<li>Improved Global Styles and typography tools</li>\n\n\n\n<li>Enhanced Canvas Notes and collaboration</li>\n\n\n\n<li>New DataForm block settings inspector</li>\n\n\n\n<li>Faster media uploads and image processing</li>\n\n\n\n<li>Modernized WordPress admin with SVG icons</li>\n\n\n\n<li>Faster admin navigation and asset loading</li>\n\n\n\n<li>New “On This Day” widget and random post discovery</li>\n\n\n\n<li>Improved translation update management</li>\n\n\n\n<li>Accessibility, security, and PHP 8.6 compatibility improvements</li>\n</ul>\n\n\n\n<h3 class=\"wp-block-heading\">How you can contribute</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress is open source software made possible by a passionate community of people collaborating on and contributing to its development. The resources below outline various ways you can help the world’s most popular open source web platform, regardless of your technical expertise.</p>\n\n\n\n<h3 class=\"wp-block-heading\">Get involved in testing</h3>\n\n\n\n<p class=\"wp-block-paragraph\">Testing for issues is crucial to the development of any software. It’s also a meaningful way for anyone to contribute. </p>\n\n\n\n<p class=\"wp-block-paragraph\">Your help testing the WordPress 7.2 RC1 version is key to ensuring that the final release is the best it can be. While testing the upgrade process is essential, trying out new features is equally important. This <a href=\"https://make.wordpress.org/test/2026/10/20/help-test-wordpress-7-2/\" rel=\"noopener\" target=\"_blank\">detailed guide</a> will walk you through testing features in WordPress 7.2.</p>\n\n\n\n<h3 class=\"wp-block-heading\">Update your theme or plugin</h3>\n\n\n\n<p class=\"wp-block-paragraph\">For plugin and theme authors, your products play an integral role in extending the functionality and value of WordPress for all users.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Thanks for continuing to test your themes and plugins with the WordPress 7.2 beta releases. With RC1, you’ll want to conclude your testing and update the <em>“Tested up to”</em> version in your <a href=\"https://developer.wordpress.org/plugins/wordpress-org/how-your-readme-txt-works/\" rel=\"noopener\" target=\"_blank\">plugin’s readme file</a> to 7.2.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you find compatibility issues, please post detailed information to the <a href=\"https://wordpress.org/support/forum/alphabeta/\" rel=\"noopener\" target=\"_blank\">support forum</a>.</p>\n\n\n\n<h3 class=\"wp-block-heading\">Test on your hosting platforms</h3>\n\n\n\n<p class=\"wp-block-paragraph\">Web hosts provide vital infrastructure for supporting WordPress and its users. Testing on hosting systems helps inform the development process while ensuring that WordPress and hosting platforms are fully compatible, free of errors, optimized for the best possible user experience, and that updates roll out to customer sites without issue.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Want to test WordPress on your hosting system? <a href=\"https://make.wordpress.org/hosting/test-results-getting-started/\" rel=\"noopener\" target=\"_blank\">Get started with configuring distributed hosting tests here</a>. Thank you to all <a href=\"https://make.wordpress.org/hosting/test-results/\" rel=\"noopener\" target=\"_blank\">web hosts who help test WordPress</a>!</p>\n\n\n\n<p class=\"wp-block-paragraph\">Curious about testing releases in general? Follow along with the <a href=\"https://make.wordpress.org/test/\" rel=\"noopener\" target=\"_blank\">testing initiatives in Make Core</a> and join the <a href=\"https://wordpress.slack.com/messages/core-test/\" rel=\"noopener\" target=\"_blank\">#core-test channel</a> on <a href=\"https://wordpress.slack.com/\" rel=\"noopener\" target=\"_blank\">Making WordPress Slack</a>.</p>\n\n\n\n<h3 class=\"wp-block-heading\">An RC1 haiku</h3>\n\n\n\n<p class=\"wp-block-paragraph\"><em>The final bugs fall</em><br /><em>Release candidate takes flight</em><br /><em>Launch day draws nearer</em></p>\n\n\n\n<p class=\"has-text-align-right wp-block-paragraph\"><em>Props to <a class=\"mention\" href=\"https://profiles.wordpress.org/audrasjb/\"><span class=\"mentions-prefix\">@</span>audrasjb</a>, <a class=\"mention\" href=\"https://profiles.wordpress.org/r1k0/\"><span class=\"mentions-prefix\">@</span>r1k0</a>, and <a class=\"mention\" href=\"https://profiles.wordpress.org/courane01/\"><span class=\"mentions-prefix\">@</span>courane01</a> for collaboration and review.</em></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 17 Nov 2026 16:04:13 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:14:\"David Baumwald\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:5;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:72:\"Open Channels FM: What to Expect from the Open Web Conversations Podcast\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2566576\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:75:\"https://openchannels.fm/what-to-expect-from-open-web-conversations-podcast/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:73:\"Conversations about the state of the open web and what shapes its future.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 17 Nov 2026 11:39:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:6;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:21:\"Matt: Triple Rainbow!\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:23:\"https://ma.tt/?p=155493\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:37:\"https://ma.tt/2026/11/triple-rainbow/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:1072:\"<figure class=\"wp-block-image size-full\"><img alt=\"\" class=\"wp-image-155502\" height=\"284\" src=\"https://i0.wp.com/ma.tt/files/2026/11/Screenshot-2026-11-16-at-5.49.44-PM.png?resize=604%2C284&#038;quality=80&#038;ssl=1\" width=\"604\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">While driving between meetings at the<a href=\"https://www.semafor.com/hub/semafor-silicon-valley-and-the-world-2026\"> Semafor World Conference</a> and San Francisco, I snapped a quick photo of a double rainbow but it turned into a triple rainbow with the iconic <a href=\"https://www.nytimes.com/2019/03/18/us/flintstone-house.html\">Flintstone House</a>.</p>\n\n\n\n<figure class=\"wp-block-image size-full\"><img alt=\"\" class=\"wp-image-155503\" height=\"299\" src=\"https://i0.wp.com/ma.tt/files/2026/11/image-1.png?resize=604%2C299&#038;quality=80&#038;ssl=1\" width=\"604\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">It&#8217;s been a strange few weeks, but driving through the rain and sun and seeing three rainbows reminded me that the storm and the light usually arrive together. Staying optimistic.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 17 Nov 2026 02:02:50 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"Matt\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:7;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:86:\"Open Channels FM: The Personal Transition: From Human Code Reviews to AI Collaboration\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2566436\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:92:\"https://openchannels.fm/the-personal-transition-from-human-code-reviews-to-ai-collaboration/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:207:\"Adopting AI in software development requires a shift in approach, emphasizing trust, automated processes, and robust guidelines to foster creativity while reducing micromanagement and enhancing productivity.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 16 Nov 2026 16:22:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"Open Channels FM\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:8;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:59:\"Open Channels FM: What Is Open Channels FM Podcast Network?\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2566565\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:65:\"https://openchannels.fm/what-is-open-channels-fm-podcast-network/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:92:\"Meet our four shows dedicated to signal, news, and insight for open source and the open web.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 16 Nov 2026 11:16:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:9;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"bbPress: bbPress 2.6.22 is out!\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:29:\"https://bbpress.org/?p=250525\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:55:\"https://bbpress.org/blog/2026/11/bbpress-2-6-22-is-out/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:1888:\"<p class=\"wp-block-paragraph\">bbPress 2.6.22 was released on November 15, 2026. It is a security and maintenance release. Everyone running bbPress should update. <img alt=\"🔒\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f512.png\" style=\"height: 1em;\" /></p>\n\n\n\n<p class=\"wp-block-paragraph\">This release strengthens access checks for forums, topics, replies, attachments, REST media changes, BuddyPress group moderation, and public discovery. Protected bbPress content is kept out of sitemaps, attachment comment feeds, embedded content, and listings without the required access.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Maintenance fixes improve topic and forum trash, restore, spam, unspam, and deletion performance, preserve interrupted restore lists, and report failed database queries in the forum reset tool. Block theme rendering, importers, WordPress navigation, BuddyPress compatibility, daylight-saving time handling, and PHP compatibility also improve.</p>\n\n\n\n<p class=\"wp-block-paragraph\">bbPress 2.6.22 still requires WordPress 6.0 or newer and PHP 7.2 or newer, and is tested through WordPress 7.1. The database version remains 264, so no database upgrade is required. Imported Vanilla users with 32-character hexadecimal plaintext passwords may need a reset. The <a href=\"https://codex.bbpress.org/releases/bbpress-2-6-22/\">2.6.22 upgrade notes</a> cover compatibility details.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The 2.7 development branch remains 2.7.0-alpha-4. Thanks to joaquinferrero, zonduu, and konnektiv for contributions included in this release, and to everyone who helped report, review, and test the changes.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://downloads.wordpress.org/plugin/bbpress.2.6.22.zip\">Download bbPress 2.6.22</a> from WordPress.org, or update from your WordPress dashboard when the update is available.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 16 Nov 2026 05:16:08 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:17:\"John James Jacoby\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:10;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:23:\"Matt: Eric’s Memorial\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:23:\"https://ma.tt/?p=155474\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:37:\"https://ma.tt/2026/11/erics-memorial/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:1439:\"<p class=\"wp-block-paragraph\"> Eric&#8217;s memorial is today in Wichita Falls, <a href=\"https://friendsofericbinnion.wordpress.com/celebration-of-life/\">there will be a Zoom for people to attend remotely</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://james.blog/2026/11/10/remembering-eric-binnion/\">James Grierson has a great post remembering Eric</a>. <a href=\"https://ma.tt/2026/10/rip-eric/\">More links and my own writing on Eric is here</a>. I can&#8217;t believe it&#8217;s been a month already&#8230; I find myself returning to <a href=\"https://eric.blog/\">his blog</a> or <a href=\"https://friendsofericbinnion.wordpress.com/\">tribute site</a> frequently when going through something tough at work. </p>\n\n\n\n<p class=\"wp-block-paragraph\">In the service pamphlet Eric&#8217;s wife Sara wrote something beautiful, &#8220;Be the things you loved most about him.&#8221; And this quote from Eric himself:</p>\n\n\n\n<blockquote class=\"wp-block-quote is-layout-flow wp-block-quote-is-layout-flow\">\n<p class=\"wp-block-paragraph\">“Build a life with enough margin to help others when they need it, and enough humility to accept their help when it’s your turn.”<br />— Eric Binnion, <a href=\"https://eric.blog/2026/07/18/no-one-is-coming/\">July 18, 2026</a></p>\n</blockquote>\n\n\n\n<p class=\"wp-block-paragraph\">Rest in peace, brother. We miss you dearly. Your life and legacy continues to be an inspiration to me and others.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Sat, 14 Nov 2026 18:48:16 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"Matt\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:11;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:85:\"Dave Smith: What if WordPress was built for Users not Developers – Create not Learn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://aheadcreative.co.uk/?p=1382\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:107:\"https://aheadcreative.co.uk/articles/what-if-wordpress-was-built-for-users-not-developers-create-not-learn/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:541:\"<p>What if the WordPress site editor was designed around what you want to do, not how WordPress is built? In this video I walk through Create Not Learn, an experimental plugin that explores one possible answer. It uses everyday words, starts from tasks rather than menus, and keeps the complex tools out of the way until you need them. We’re using it to test ideas with real people…</p>\n<p><a href=\"https://aheadcreative.co.uk/articles/what-if-wordpress-was-built-for-users-not-developers-create-not-learn/\" rel=\"nofollow\">Source</a></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 13 Nov 2026 14:55:52 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:10:\"Dave Smith\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:12;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:68:\"Open Channels FM: AI and the Changing Landscape of Game Preservation\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2564536\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:75:\"https://openchannels.fm/ai-and-the-changing-landscape-of-game-preservation/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:384:\"Artificial intelligence is reshaping the way classic video games are preserved and enjoyed. As AI-assisted tools become more accessible, developers can reverse engineer, emulate, and port games to hardware and operating systems they were never originally designed for. This trend is lowering the technical barriers that once kept old games locked away on obsolete platforms. [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 13 Nov 2026 14:06:35 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"Open Channels FM\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:13;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:57:\"WordPress.org blog: Copy Your WordPress Site with Reprint\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://wordpress.org/news/?p=22001\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:53:\"https://wordpress.org/news/2026/11/reprint-your-site/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:4378:\"<p class=\"wp-block-paragraph\">Reprint is a free, open-source, PHP-based tool that copies a WordPress site’s files and database. The plugin is available in the <a href=\"https://wordpress.org/plugins/reprint/\">WordPress.org Plugin Directory</a>, along with the command-line client used to copy the site.</p>\n\n\n<figure class=\"wp-block-post-featured-image\"><img alt=\"\" class=\"attachment-post-thumbnail size-post-thumbnail wp-post-image\" height=\"1440\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/11/reprint-hero-scaled.png?resize=2560%2C1440&#038;ssl=1\" width=\"2560\" /></figure>\n\n\n<p class=\"wp-block-paragraph\">WordPress has long let you <a href=\"https://wordpress.org/documentation/article/tools-export-screen/\">export your posts and pages</a>. Moving the site itself means bringing along its theme, plugins, uploads, and settings, too. Making that easier has been part of <a href=\"https://make.wordpress.org/core/2024/06/21/data-liberation-and-wordpress-migrations/\">WordPress’s Data Liberation work</a> since 2024.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Example use cases</h2>\n\n\n\n<p class=\"wp-block-paragraph\">You can use Reprint to copy your site to a new host, or to create a local copy meant for testing.</p>\n\n\n\n<p class=\"wp-block-paragraph\">While moving your site to a new host, visitors can keep using the original. Use Reprint to copy the site, and then open the copy to check that your pages load, your images appear, and your forms work before you send visitors there. When you’re ready to switch, pause changes on the original site, make one last copy, and point your domain to the new host. The <a href=\"https://developer.wordpress.org/reprint/guides/move-to-another-host/\">step-by-step guide to moving your site</a> walks you through the move.</p>\n\n\n\n<p class=\"wp-block-paragraph\">You can also use Reprint to create a site copy meant for testing, a place to try changes without affecting the site your visitors use. <a href=\"https://developer.wordpress.org/reprint/getting-started/copy-a-site/\">Copy your site to your computer</a> or try the <a href=\"https://playground.wordpress.net/?clone-site=https%3A%2F%2Freprint-demo.wordpress.net\">experimental, browser-based option in WordPress Playground</a>. Use the copy to try a new layout with your existing pages, see how a plugin fits into your site, or check that everything still works after a WordPress update.</p>\n\n\n\n<h2 class=\"wp-block-heading\">How Reprint copies a site</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Reprint sends your files and database directly to the computer or server you choose, one piece at a time, without needing to connect to an external service. The transfer can begin without your old host having to make room for an archive of the whole site.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If the connection drops during the copy, you can resume from the last saved point. If you give Reprint a new site address, it can update links that point to the old one. It builds on the <a href=\"https://make.wordpress.org/core/2025/11/27/wordpress-importer-can-now-migrate-urls-in-your-content/\">WordPress Importer’s approach to rewriting links</a> and applies it to the copied database, including links stored in site settings, blocks, shortcodes, and complex data structures like serialized data or custom fields safely without corrupting tables.</p>\n\n\n\n		<figure class=\"wp-block-jetpack-videopress jetpack-videopress-player\">\n			<div class=\"jetpack-videopress-player__wrapper\"> </div>\n			\n			\n		</figure>\n		\n\n\n<p class=\"wp-block-paragraph\">When copying a site repeatedly, Reprint figures out what changed since the last time and copies only the files it needs.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Try Reprint</h2>\n\n\n\n<p class=\"wp-block-paragraph\">You don’t need to connect your own site to see how Reprint works. Try the <a href=\"https://playground.wordpress.net/?clone-site=https%3A%2F%2Freprint-demo.wordpress.net\">experimental, browser-based option in WordPress Playground</a>. You can copy a sample site right in your browser, with nothing to install.</p>\n\n\n\n<p class=\"wp-block-paragraph\">When you’re ready to work with your own pages and settings, start with a test site you manage. The <a href=\"https://developer.wordpress.org/reprint/getting-started/copy-a-site/\">guide to making your first copy</a> takes you from installing the plugin to opening the copied site on your computer.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 13 Nov 2026 12:00:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:15:\"Adam Zieliński\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:14;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:75:\"Open Channels FM: After the Announcement, Open Channels News Week in Review\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2566831\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:81:\"https://openchannels.fm/after-the-announcement-open-channels-news-week-in-review/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:192:\"This week’s news looked at AI, open-source licensing, security automation, regulatory software, enterprise spending, SaaS alternatives, maintenance challenges, patents, and credential risks.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 13 Nov 2026 10:13:55 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"Open Channels FM\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:15;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:86:\"WordCamp Central: WordPress Campus Connect 2026 at Compact Polytechnic Institute, Feni\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:40:\"https://central.wordcamp.org/?p=16786906\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:97:\"https://central.wordcamp.org/news/2026/11/wordpress-campus-connect-compact-polytechnic-institute/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:16569:\"<div class=\"wp-block-group\"><div class=\"wp-block-group__inner-container is-layout-constrained wp-block-group-is-layout-constrained\">\n<div class=\"wp-block-group is-vertical is-layout-flex wp-container-core-group-is-layout-4fc3f8e1 wp-block-group-is-layout-flex\">\n<h3 class=\"wp-block-heading has-black-color has-text-color has-link-color wp-elements-2\">Campus Connect event</h3>\n\n\n\n<p class=\"wp-block-paragraph\">On November 12, 2026, WordPress Campus Connect took place at Compact Polytechnic Institute, Feni, Bangladesh, bringing together students, WordPress enthusiasts, speakers, and community members for a day of learning, knowledge sharing, and exploring opportunities within the global WordPress ecosystem.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The event was designed to introduce students to WordPress, modern website development, open-source contributions, plugin development, artificial intelligence, and career opportunities in the WordPress ecosystem.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Throughout the event, participants had the opportunity to learn from experienced speakers, explore different areas of WordPress, and discover how they can become active members of the global WordPress community.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Event Sessions and Speakers</h2>\n\n\n\n<p class=\"wp-block-paragraph\">The event featured five sessions covering different aspects of WordPress, from modern website development to community contributions and career opportunities.</p>\n\n\n\n<h3 class=\"wp-block-heading\">1. Building Modern Websites with Blocks &amp; Full Site Editing</h3>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Speaker:</strong> <a href=\"https://events.wordpress.org/campusconnect/2026/compact-polytechnic-institute-feni/speaker/muhibul-haque/\">Muhibul Haque</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Time:</strong> 10:15 AM (+06)</p>\n\n\n\n<p class=\"wp-block-paragraph\">This session focused on the modern WordPress editing experience and how the Block Editor (Gutenberg) and Full Site Editing (FSE) are transforming website development.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Participants explored different types of WordPress blocks, learned how to combine blocks and patterns to create engaging page layouts, and discovered how block themes work.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The session also covered customizing essential website elements, including headers, footers, templates, and navigation, directly through the WordPress Site Editor.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Key topics included:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Introduction to the WordPress Block Editor (Gutenberg).</li>\n\n\n\n<li>Exploring different block types and their practical uses.</li>\n\n\n\n<li>Creating page layouts using blocks and patterns.</li>\n\n\n\n<li>Understanding Full Site Editing (FSE).</li>\n\n\n\n<li>Working with block themes.</li>\n\n\n\n<li>Customizing headers, footers, templates, and navigation.</li>\n</ul>\n\n\n\n<h3 class=\"wp-block-heading\">2. Building the WordPress Ecosystem Through Plugin Development</h3>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Speaker:</strong> <a href=\"https://events.wordpress.org/campusconnect/2026/compact-polytechnic-institute-feni/speaker/foysal-imran/\">Foysal Imran</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Time:</strong> 11:00 AM (+06)</p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress is not just a website-building platform; it is a growing open-source ecosystem powered by developers and contributors worldwide.</p>\n\n\n\n<p class=\"wp-block-paragraph\">This session introduced participants to the role of plugin development in extending WordPress functionality and solving real-world problems.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The discussion covered the fundamentals of WordPress plugin development, plugin architecture, and how developers can build custom solutions to meet different website requirements.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Participants also learned about contributing plugins to the official WordPress.org Plugin Directory and how open-source development can help them improve their technical skills, build portfolios, and explore career opportunities.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Key topics included:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Introduction to the WordPress ecosystem.</li>\n\n\n\n<li>Understanding WordPress plugin architecture.</li>\n\n\n\n<li>Fundamentals of plugin development.</li>\n\n\n\n<li>Building solutions through custom plugins.</li>\n\n\n\n<li>Contributing to the WordPress.org Plugin Directory.</li>\n\n\n\n<li>Career opportunities through open-source development.</li>\n</ul>\n\n\n\n<h3 class=\"wp-block-heading\">3. Getting Started with WordPress Contributions: Learn, Practice &amp; Contribute</h3>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Speaker:</strong> <a href=\"https://events.wordpress.org/campusconnect/2026/compact-polytechnic-institute-feni/speaker/atikur-rahman/\">Atikur Rahman</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>WordPress.org Profile:</strong> <a href=\"https://profiles.wordpress.org/atik0130961/\">Atikur Rahman (@atik0130961)</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Time:</strong> 11:30 AM (+06)</p>\n\n\n\n<p class=\"wp-block-paragraph\">I had the opportunity to lead this session and introduce students to the WordPress open-source community and the different ways they can contribute to the project.</p>\n\n\n\n<p class=\"wp-block-paragraph\">One of the most important messages I wanted to share was that contributing to WordPress is not limited to developers or people with advanced coding knowledge. Anyone interested in learning, sharing knowledge, and helping others can become part of this global community.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We explored the different WordPress contribution teams and discussed how people with different skills and interests can contribute to the project.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I also introduced participants to WordPress.org and demonstrated some practical ways to get started with contributing.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The session covered three practical contribution opportunities:</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Creating a WordPress.org Account</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">Participants learned about creating their WordPress.org accounts, setting up their profiles, and becoming part of the WordPress community.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Contributing to the Polyglots Team</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">I introduced the WordPress Polyglots team, which works to make WordPress accessible to people around the world through translation.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We explored how contributors can participate in translating WordPress, plugins, and themes into Bangla and help make WordPress more accessible to Bangla-speaking users.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Contributing to the Photo Directory</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">Participants also learned about the WordPress Photo Directory and how they can contribute photographs to this open-source resource.</p>\n\n\n\n<p class=\"wp-block-paragraph\">This demonstrated that contributing to WordPress does not always require programming skills. People with different interests and abilities can make meaningful contributions.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Key topics included:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Introduction to the WordPress open-source community.</li>\n\n\n\n<li>Understanding why WordPress contributions matter.</li>\n\n\n\n<li>Exploring different WordPress contribution teams.</li>\n\n\n\n<li>Ways to contribute beyond coding.</li>\n\n\n\n<li>Getting started with WordPress.org.</li>\n\n\n\n<li>Creating a WordPress.org account and setting up a profile.</li>\n\n\n\n<li>Understanding the Polyglots team and Bangla translation.</li>\n\n\n\n<li>Exploring the WordPress Photo Directory.</li>\n\n\n\n<li>Practical demonstrations of contribution opportunities.</li>\n\n\n\n<li>Building skills through open-source collaboration.</li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\">My goal was to help students understand that they do not need to wait until they become professional developers to start contributing. They can begin their contribution journey while learning.</p>\n\n\n\n<h3 class=\"wp-block-heading\">4. WordPress &amp; AI: Exploring Smarter Tools and Practical Applications</h3>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Speaker:</strong> <a href=\"https://events.wordpress.org/campusconnect/2026/compact-polytechnic-institute-feni/speaker/sayeeduzzaman-noor/\">Sayeeduzzaman Noor</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Time:</strong> 12:00 PM (+06)</p>\n\n\n\n<p class=\"wp-block-paragraph\">Artificial Intelligence is changing how websites are developed, content is created, and digital experiences are managed.</p>\n\n\n\n<p class=\"wp-block-paragraph\">This session explored how AI tools can be integrated into everyday WordPress workflows to improve productivity, save time, and make website development more efficient.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Participants discovered how AI-powered tools and plugins can support website creation, content generation, SEO, coding, debugging, and design-related tasks.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The session also included practical examples of using AI in real-world WordPress projects.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Key topics included:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Introduction to AI in the WordPress ecosystem.</li>\n\n\n\n<li>Exploring AI-powered WordPress tools and plugins.</li>\n\n\n\n<li>Using AI for content creation.</li>\n\n\n\n<li>Generating website copy and digital content.</li>\n\n\n\n<li>AI-assisted website development and debugging.</li>\n\n\n\n<li>Improving productivity through AI tools.</li>\n\n\n\n<li>Understanding the opportunities and limitations of AI.</li>\n</ul>\n\n\n\n<h3 class=\"wp-block-heading\">5. Opportunities for Students in WordPress</h3>\n\n\n\n<p class=\"wp-block-paragraph\">This session focused on the opportunities available to students who want to build a future in the WordPress ecosystem.</p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress offers opportunities beyond website development, including freelancing, entrepreneurship, open-source contributions, community participation, and professional collaboration.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Participants explored different career paths and learned why developing practical skills, building a portfolio, and participating in the community can help them grow professionally.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Key topics included:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Introduction to the WordPress ecosystem.</li>\n\n\n\n<li>WordPress career opportunities.</li>\n\n\n\n<li>Freelancing and earning opportunities.</li>\n\n\n\n<li>Open-source contributions.</li>\n\n\n\n<li>Portfolio building and skill development.</li>\n\n\n\n<li>Learning roadmaps and career growth.</li>\n</ul>\n\n\n\n<h2 class=\"wp-block-heading\">My WordPress Journey: From Student to Mentor to Community Speaker</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Being part of this event as a speaker was a meaningful experience for me.</p>\n\n\n\n<p class=\"wp-block-paragraph\">My journey with WordPress started as a student who wanted to learn how websites are built and understand the opportunities available in the WordPress ecosystem.</p>\n\n\n\n<p class=\"wp-block-paragraph\">As I continued learning, I discovered something even more valuable: WordPress is not only about building websites. It is also about learning together, sharing knowledge, helping others, and contributing to an open-source project used by people around the world.</p>\n\n\n\n<p class=\"wp-block-paragraph\">After becoming involved in the community, I started contributing to different areas of WordPress and supporting other learners in their journeys.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I completed the WordPress Credits course, became involved in community activities, and later took the opportunity to support students as a mentor.</p>\n\n\n\n<p class=\"wp-block-paragraph\">My involvement in the community gradually grew from being a learner to becoming a mentor and now having the opportunity to share my experience as a community speaker.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Standing in front of students at Compact Polytechnic Institute and sharing what I have learned throughout this journey was a special milestone for me.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I wanted students to understand that they do not need to know everything before getting involved. They can start with small steps, learn from the community, contribute according to their abilities, and gradually grow.</p>\n\n\n\n<h2 class=\"wp-block-heading\">A Learning Experience Beyond the Sessions</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Campus Connect is more than a series of presentations. It is an opportunity to introduce students to the possibilities of open-source collaboration and help them see how they can become part of a global technology community.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Through the different sessions, students were introduced to modern WordPress website development, plugin development, open-source contributions, AI-powered workflows, and professional opportunities.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Each session highlighted a different part of the WordPress ecosystem and showed how students can explore their interests, develop practical skills, and build their future.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I strongly believe that introducing students to open-source communities at an early stage can create valuable opportunities for both individual growth and the wider WordPress community.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Thank You</h2>\n\n\n\n<p class=\"wp-block-paragraph\">A special thanks to the organizers, speakers, teachers, and students of Compact Polytechnic Institute for making this Campus Connect event possible.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I am grateful for the opportunity to share my journey, discuss WordPress contributions, and encourage students to explore the global WordPress community.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I also appreciate the enthusiasm and participation of the students throughout the event.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I hope this event inspires more students to start learning WordPress, explore open-source contributions, and become active members of the community.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Looking forward to more opportunities to learn, contribute, mentor, and grow together.</p>\n</div>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-1 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><a href=\"https://central.wordcamp.org/files/2026/11/photo1.jpg\"><img alt=\"\" class=\"wp-image-16786909\" height=\"768\" src=\"https://central.wordcamp.org/files/2026/11/photo1-1024x768.jpg\" width=\"1024\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://central.wordcamp.org/files/2026/11/IMG_4631-scaled.jpg\"><img alt=\"\" class=\"wp-image-16786913\" height=\"768\" src=\"https://central.wordcamp.org/files/2026/11/IMG_4631-1024x768.jpg\" width=\"1024\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://central.wordcamp.org/files/2026/11/IMG_4570-scaled.jpg\"><img alt=\"\" class=\"wp-image-16809632\" height=\"1024\" src=\"https://central.wordcamp.org/files/2026/11/IMG_4570-768x1024-1.jpg\" width=\"768\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://central.wordcamp.org/files/2026/11/IMG_4655-scaled.jpg\"><img alt=\"\" class=\"wp-image-16786912\" height=\"1024\" src=\"https://central.wordcamp.org/files/2026/11/IMG_4655-768x1024.jpg\" width=\"768\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://central.wordcamp.org/files/2026/11/IMG_4454-scaled.jpg\"><img alt=\"\" class=\"wp-image-16809633\" height=\"1024\" src=\"https://central.wordcamp.org/files/2026/11/IMG_4454-768x1024-1.jpg\" width=\"768\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-full\"><a href=\"https://central.wordcamp.org/files/2026/11/3f7c72f6-db23-4792-bbdc-81718cf694f0.jpg\"><img alt=\"\" class=\"wp-image-16809635\" height=\"1280\" src=\"https://central.wordcamp.org/files/2026/11/3f7c72f6-db23-4792-bbdc-81718cf694f0.jpg\" width=\"960\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-full\"><a href=\"https://central.wordcamp.org/files/2026/11/1d4ec165-ff3d-4461-921e-ae185a7684fb.jpg\"><img alt=\"\" class=\"wp-image-16809636\" height=\"960\" src=\"https://central.wordcamp.org/files/2026/11/1d4ec165-ff3d-4461-921e-ae185a7684fb.jpg\" width=\"1280\" /></a></figure>\n</figure>\n</div></div>\n\n\n\n<p class=\"wp-block-paragraph\"></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 13 Nov 2026 09:21:42 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:13:\"ATIKUR RAHMAN\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:16;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:75:\"Open Channels FM: Reclaiming Digital Control: Why User Choice Still Matters\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2565724\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:81:\"https://openchannels.fm/reclaiming-digital-control-why-user-choice-still-matters/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:280:\"The digital landscape is shifting towards u