1.5h2a.5.5 0 0 0 .5-.5V8H12v2a2 2 0 0 1-2 2H8Zm2-12a2 2 0 0 1 2 2v2h-1.5V2a.5.5 0 0 0-.5-.5H8V0h2Z\" fill=\"#fff\">\n			</svg>\n		</button></figure>\n\n\n\n<figure class=\"wp-block-image size-large has-custom-border wp-lightbox-container\"><img alt=\"\" class=\"wp-image-18545\" height=\"683\" src=\"https://i0.wp.com/wordpress.org/news/files/2025/02/20250221-250221_12-35-12_N7A00461_NExT.jpg?resize=1024%2C683&#038;ssl=1\" style=\"border-radius: 2px;\" width=\"1024\" /><button class=\"lightbox-trigger\" type=\"button\">\n			<svg fill=\"none\" height=\"12\" viewBox=\"0 0 12 12\" width=\"12\" xmlns=\"http://www.w3.org/2000/svg\">\n				<path d=\"M2 0a2 2 0 0 0-2 2v2h1.5V2a.5.5 0 0 1 .5-.5h2V0H2Zm2 10.5H2a.5.5 0 0 1-.5-.5V8H0v2a2 2 0 0 0 2 2h2v-1.5ZM8 12v-1.5h2a.5.5 0 0 0 .5-.5V8H12v2a2 2 0 0 1-2 2H8Zm2-12a2 2 0 0 1 2 2v2h-1.5V2a.5.5 0 0 0-.5-.5H8V0h2Z\" fill=\"#fff\">\n			</svg>\n		</button></figure>\n\n\n\n<figure class=\"wp-block-image size-large wp-lightbox-container\"><img alt=\"\" class=\"wp-image-20389\" height=\"536\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/04/FamilyPhoto-Framed.png?resize=1024%2C536&#038;ssl=1\" width=\"1024\" /><button class=\"lightbox-trigger\" type=\"button\">\n			<svg fill=\"none\" height=\"12\" viewBox=\"0 0 12 12\" width=\"12\" xmlns=\"http://www.w3.org/2000/svg\">\n				<path d=\"M2 0a2 2 0 0 0-2 2v2h1.5V2a.5.5 0 0 1 .5-.5h2V0H2Zm2 10.5H2a.5.5 0 0 1-.5-.5V8H0v2a2 2 0 0 0 2 2h2v-1.5ZM8 12v-1.5h2a.5.5 0 0 0 .5-.5V8H12v2a2 2 0 0 1-2 2H8Zm2-12a2 2 0 0 1 2 2v2h-1.5V2a.5.5 0 0 0-.5-.5H8V0h2Z\" fill=\"#fff\">\n			</svg>\n		</button></figure>\n\n\n\n<figure class=\"wp-block-image size-large wp-lightbox-container\"><img alt=\"\" class=\"wp-image-18616\" height=\"683\" src=\"https://i0.wp.com/wordpress.org/news/files/2025/02/WORDCAMPASIA2025_PH_PICC_DAY01_CONTRIBUTORSDAY_JOHN_CARLO_PATTAGUAN-474.jpg?resize=1024%2C683&#038;ssl=1\" width=\"1024\" /><button class=\"lightbox-trigger\" type=\"button\">\n			<svg fill=\"none\" height=\"12\" viewBox=\"0 0 12 12\" width=\"12\" xmlns=\"http://www.w3.org/2000/svg\">\n				<path d=\"M2 0a2 2 0 0 0-2 2v2h1.5V2a.5.5 0 0 1 .5-.5h2V0H2Zm2 10.5H2a.5.5 0 0 1-.5-.5V8H0v2a2 2 0 0 0 2 2h2v-1.5ZM8 12v-1.5h2a.5.5 0 0 0 .5-.5V8H12v2a2 2 0 0 1-2 2H8Zm2-12a2 2 0 0 1 2 2v2h-1.5V2a.5.5 0 0 0-.5-.5H8V0h2Z\" fill=\"#fff\">\n			</svg>\n		</button></figure>\n\n\n\n<figure class=\"wp-block-image size-large wp-lightbox-container\"><img alt=\"\" class=\"wp-image-20395\" height=\"576\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/04/DSC04422.jpg?resize=1024%2C576&#038;ssl=1\" width=\"1024\" /><button class=\"lightbox-trigger\" type=\"button\">\n			<svg fill=\"none\" height=\"12\" viewBox=\"0 0 12 12\" width=\"12\" xmlns=\"http://www.w3.org/2000/svg\">\n				<path d=\"M2 0a2 2 0 0 0-2 2v2h1.5V2a.5.5 0 0 1 .5-.5h2V0H2Zm2 10.5H2a.5.5 0 0 1-.5-.5V8H0v2a2 2 0 0 0 2 2h2v-1.5ZM8 12v-1.5h2a.5.5 0 0 0 .5-.5V8H12v2a2 2 0 0 1-2 2H8Zm2-12a2 2 0 0 1 2 2v2h-1.5V2a.5.5 0 0 0-.5-.5H8V0h2Z\" fill=\"#fff\">\n			</svg>\n		</button></figure>\n\n\n\n<figure class=\"wp-block-image size-large wp-lightbox-container\"><img alt=\"\" class=\"wp-image-20394\" height=\"575\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/04/IMG_0106.jpg?resize=1024%2C575&#038;ssl=1\" width=\"1024\" /><button class=\"lightbox-trigger\" type=\"button\">\n			<svg fill=\"none\" height=\"12\" viewBox=\"0 0 12 12\" width=\"12\" xmlns=\"http://www.w3.org/2000/svg\">\n				<path d=\"M2 0a2 2 0 0 0-2 2v2h1.5V2a.5.5 0 0 1 .5-.5h2V0H2Zm2 10.5H2a.5.5 0 0 1-.5-.5V8H0v2a2 2 0 0 0 2 2h2v-1.5ZM8 12v-1.5h2a.5.5 0 0 0 .5-.5V8H12v2a2 2 0 0 1-2 2H8Zm2-12a2 2 0 0 1 2 2v2h-1.5V2a.5.5 0 0 0-.5-.5H8V0h2Z\" fill=\"#fff\">\n			</svg>\n		</button></figure>\n\n\n\n<figure class=\"wp-block-image size-large has-custom-border wp-lightbox-container\"><img alt=\"\" class=\"wp-image-18543\" height=\"683\" src=\"https://i0.wp.com/wordpress.org/news/files/2025/02/20250221-DSC_2549.jpg?resize=1024%2C683&#038;ssl=1\" style=\"border-radius: 2px;\" width=\"1024\" /><button class=\"lightbox-trigger\" type=\"button\">\n			<svg fill=\"none\" height=\"12\" viewBox=\"0 0 12 12\" width=\"12\" xmlns=\"http://www.w3.org/2000/svg\">\n				<path d=\"M2 0a2 2 0 0 0-2 2v2h1.5V2a.5.5 0 0 1 .5-.5h2V0H2Zm2 10.5H2a.5.5 0 0 1-.5-.5V8H0v2a2 2 0 0 0 2 2h2v-1.5ZM8 12v-1.5h2a.5.5 0 0 0 .5-.5V8H12v2a2 2 0 0 1-2 2H8Zm2-12a2 2 0 0 1 2 2v2h-1.5V2a.5.5 0 0 0-.5-.5H8V0h2Z\" fill=\"#fff\">\n			</svg>\n		</button></figure>\n</figure>\n\n\n\n<p class=\"wp-block-paragraph\">However you choose to take part, your presence matters. Buy a ticket, bring a colleague, sponsor the event, or share this post with someone who should be there. Each of those choices strengthens WordPress and the people behind it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">See you in Penang.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 11 Nov 2026 14:00:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:17:\"Nicholas Garofalo\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:23;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:100:\"WPTavern: #241 – Tiffany Farriss on Drupal Funding, Community, and a Shared Journey With WordPress\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:48:\"https://wptavern.com/?post_type=podcast&p=209750\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:113:\"https://wptavern.com/podcast/241-tiffany-farriss-on-drupal-funding-community-and-a-shared-journey-with-wordpress/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:64521:\"<details>Transcript<div>\n<p class=\"wp-block-paragraph\">[00:00:19] <strong>Nathan Wrigley:</strong> Welcome to the Jukebox Podcast from WP Tavern. My name is Nathan Wrigley.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Jukebox is a podcast which is dedicated to all things WordPress. The people, the events, the plugins, the blocks, the themes, and in this case, Drupal funding, community, and a shared journey with WordPress.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you&#8217;d like to subscribe to the podcast, you can do that by searching for WP Tavern in your podcast player of choice, or by going to wptavern.com/feed/podcast, and you can copy that URL into most podcast players.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you have a topic that you&#8217;d like us to feature on the podcast, I&#8217;m keen to hear from you and hopefully get you, or your idea, featured on the show. Head to wptavern.com/contact/jukebox, and use the form there.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So on the podcast today we have Tiffany Farriss. Tiffany has spent the last 30 years working in web design, development, and creation, and she&#8217;s been deeply embedded in the Drupal community for the past two decades. She&#8217;s currently the interim CEO of the Drupal Association and is the organization&#8217;s longest serving board member after Drupal&#8217;s founder Dries Buytaert.</p>\n\n\n\n<p class=\"wp-block-paragraph\">This episode is a bit of a departure as we usually focus squarely on WordPress, but Tiffany brings a wealth of experience from the broader PHP family, and this conversation explores the similarities and differences between the WordPress and Drupal ecosystems, particularly when it comes to infrastructure and the sustainability of open source projects.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Tiffany explains the maker-taker problem, and the challenges of sustaining free software platforms that end up in millions of sites across the web. She shares her insights on the real costs behind open source stewardship, drawing from both data and experience, and discusses how tiny groups have shouldered the burden for everyone, and why that might no longer be viable.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The discussion explores the Drupal Certified Partner Program, the push towards quantifying contributions, and how the open source community can improve transparency and sustainability.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Tiffany also touches on the role of public sector procurement in shaping the future of open source, the impact of new regulations, and how community driven recognition could incentivize more organisations to buy their round of beers for the ecosystem.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you&#8217;re interested in the sustainability of open source, the evolution of governance models, and how WordPress professionals can learn from the broader PHP landscape, this episode is for you.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you&#8217;re interested in finding out more, you can find all of the links in the show notes by heading to wptavern.com/podcast, where you&#8217;ll find all the other episodes as well.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And so without further delay, I bring you Tiffany Farriss.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I am joined on the podcast by Tiffany Farriss. Hello, Tiffany.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:03:19] <strong>Tiffany Farriss:</strong> Hi Nathan.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:03:20] <strong>Nathan Wrigley:</strong> Thank you for joining us. So this is a little bit of a departure. Usually we talk about WordPress. It&#8217;s WordPress on the menu every single day of the week. And that is going to be the case, I suspect a little bit today. But there&#8217;s also going to be a foray into Drupal because Tiffany is very much connected with the Drupal community.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So Tiffany, really just to get this podcast started, can I just offer you a chance to give us your little bio, tell us who you are and what you do over on the Drupal side, lo these many years. It&#8217;s been multiple decades that you&#8217;ve been involved in various different ways I think.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:03:52] <strong>Tiffany Farriss:</strong> It has been. Yeah. Thank you Nathan. I&#8217;m really glad to be here. I do consider all of us part of the PHP family, whether we&#8217;re Drupal or WordPress or Joomla or TYPO3, like I think we all have so much in common.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But I am Tiffany Farriss. I&#8217;m currently the interim CEO over at the Drupal Association. I have been involved in web design, development, creation for the last 30 years. And I&#8217;ve been heavily involved in the Drupal community for the last 20.</p>\n\n\n\n<p class=\"wp-block-paragraph\">In particular in its governance. I&#8217;m the longest tenured board member of the Drupal Association, the 501 (c) (3) that is responsible for the governance. Other than Dries Buytaert, who is the founder of the Drupal Project.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So I&#8217;ve been around a long time and I&#8217;m currently on leave from my own company, palantir.net to take a year to help Drupal kind of navigate this time of kind of intense disruption, I think it is for all of us. Pretty safe to say, that we are all experiencing the same disruptions from AI. And then just economic pressure in general.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:04:50] <strong>Nathan Wrigley:</strong> So Drupal, I suppose, it would be a good thing to say at this point, Drupal is very similar in its project, in its status, in its goals, in its aims, in its infrastructure and technology to the CMS that most people listening to this are familiar with. It&#8217;s a PHP based CMS used by millions of websites all over the world. So broadly it&#8217;s the same.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Now you mentioned the foundation. Would you just be able to dig into that a little bit more because that may be confusing for people on this side. There may be some significant differences there. What does the foundation get itself involved with? I know that you described that a little bit there, but if you could go into a bit more depth, that would be great.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:05:26] <strong>Tiffany Farriss:</strong> I do think our governance is one of the places where WordPress and Drupal are a little bit different. In Drupal, we have the Drupal Association, which is an independent 501 (c) (3), which is a US-based not-for-profit. And we have specifically an educational and scientific mission that we&#8217;re authorised to do.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We run Drupal.org. We run all of the infrastructure. We support all the security coordination. And we are responsible for Drupal Cons around the world. We do have a founder as well, right, Dries, and he is currently the Executive Chairman of Acquia. But Acquia doesn&#8217;t have the same single privileged actor role, that say Automattic does in the WordPress community.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Dries serves on the board, but he doesn&#8217;t control the board and he doesn&#8217;t control any of the technical steering committees, although he is still the founder and the lead of the project.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:06:17] <strong>Nathan Wrigley:</strong> Okay. So there is a significant difference there, isn&#8217;t there? That&#8217;s kind of interesting.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:06:20] <strong>Tiffany Farriss:</strong> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:06:20] <strong>Nathan Wrigley:</strong> Okay, we&#8217;ll dig into that in a moment. However, in the preparation for this podcast episode, Tiffany was very kind to send me three things.</p>\n\n\n\n<p class=\"wp-block-paragraph\">One of them was a YouTube video. It runs to about 20 minutes and sort of summarises what we&#8217;re going to talk about, I think, fairly well.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Another one was a blog post that you wrote in June of this year. It&#8217;s called Freedom is Not Free, A model for Open Source Sustainability. Again, very much aligned to what we&#8217;re going to talk about. That&#8217;s on palantir.net, which I&#8217;m at pains to point out is not the palantir that you are probably thinking about when you say the word palantir. And there&#8217;s another one which again, tackles the same subject, written broadly the same time. It was July this year, written by Dries, the founder of Drupal.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And what we&#8217;re trying to deal with here is, what I think Dries has summed up in the past is this maker, taker problem. And it&#8217;s very difficult to summarise. I must confess, I genuinely cannot articulate this problem. No matter how many times I&#8217;ve tried to articulate it to friends, to colleagues, to relations. At some point I get lost. At some point, the dynamics of it and the argument of it kind of boils boils down to it&#8217;s a moral thing.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So I&#8217;m just wondering, could you paint the picture of what you were trying to say in that YouTube video and in your blog post. What is the open source sustainability problem that you think, amongst many others, we have at the moment?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:07:47] <strong>Tiffany Farriss:</strong> We like to talk in open source about free and the four freedoms, especially for projects that are based in the GPL, right? But one of those freedoms, I think it comes down to the idea of the word free, right? There&#8217;s free is in speech. Where I am free to say what I want and when I want, and accept the consequences of that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But then there&#8217;s also this idea of free as in beer. And the reality is that the beer was never free. And the problem we have in open source is that for the last 25 years of Drupal, a really small group has been buying the rounds of beer for an entire ecosystem. And what I&#8217;m saying is that, beer has never been free. You just haven&#8217;t been taking your turn at buying the round, right?</p>\n\n\n\n<p class=\"wp-block-paragraph\">So as we deal with kind of the pressures of the current economic situation, the uncertainty and opportunities created by AI, the number of people who are still buying those rounds is dwindling. But there&#8217;s still a lot of people who want to drink that free beer. There&#8217;s still a tonne of people who use WordPress, a tonne of people who use Drupal and get a lot of value out of it, right? They&#8217;re enjoying that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But what the problem is, is that we have this open source licence, and the licence is what conveys the freedom, right? It makes the code available. And in open source the more people who use the code, the cost of that code goes to zero. And no one&#8217;s use of the code is diminished by someone else also using that code.</p>\n\n\n\n<p class=\"wp-block-paragraph\">However, there&#8217;s more to being an open source project than just the code. And this is where the concept of stewardship comes in. Stewardship is what makes it dependable. It&#8217;s what has made it so that millions of people around the world can feel confident in downloading the software, using the software, hiring someone to create a WordPress or a Drupal implementation for you.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And that stewardship includes things like code hosting, or packaging. Testing frameworks. The security coordination. All of those things, which as more people use it become more expensive, not less.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So, there are these tensions around people who are getting value from open source software, but who currently don&#8217;t help pay for the cost that they impose on the project, largely because it&#8217;s invisible, right? So I think the first step is that we need to make those costs much more visible. So that&#8217;s something I&#8217;ve been working on in Drupal for a while. And so I want to expose it, right?</p>\n\n\n\n<p class=\"wp-block-paragraph\">We have 2,800 organisations in the last year who contributed into Drupal, but under 5% of them did two thirds of it, right? There are, I think as in WordPress, you know who really is driving and doing the work. And we do too, right? Obviously in Drupal we know who that is. And because we know who they are, and we know that they&#8217;re invested, and that they are passionate about open source and our project. They&#8217;re the ones who are easy to ask for financial contributions, or sponsorship to Drupal Con.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So you keep going back to the same pool. And in Drupal&#8217;s case, that means that 94% of our financial contribution comes from this tiny group of 5%. So they&#8217;re buying the rounds of beer for everyone. And that&#8217;s not a sustainable proposition.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:11:00] <strong>Nathan Wrigley:</strong> Do you think, I&#8217;m going to rewind the clock a little bit. So, I regard the internet as an ongoing experiment. Where we are now is definitely not where it&#8217;s going to end up. And where we were 10 years ago, I don&#8217;t know that anybody would&#8217;ve predicted that we&#8217;d end up where we are today. You know, the internet came around and it evolved in the way that it did.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Do you see in the last, let&#8217;s say 25 years that many people have had access to the internet. Can you see moments where, and I&#8217;m doing air quotes, mistakes were made, which led to this problem? Or was it just happenstance and serendipity? We just got to this point? There&#8217;s no real pointing of a finger. There&#8217;s nobody to blame. There&#8217;s nobody to say, okay, you made dreadful mistakes. It&#8217;s just the way it evolved. There&#8217;s no question there, but do you understand what I&#8217;m saying?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:11:49] <strong>Tiffany Farriss:</strong> I do.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:11:50] <strong>Nathan Wrigley:</strong> With the benefit of hindsight, can you look back and point the finger, or is it more a case of okay, let&#8217;s just deal with the reality of where we&#8217;re at now.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:11:56] <strong>Tiffany Farriss:</strong> I can point to that moment. I was on the board at the time when Drupal moved over to Composer, right, and to modern packaging. And what I can tell you is that the board was never, wasn&#8217;t a big deal, right? They came to the board and I don&#8217;t even think we were really notified that this was happening or what it would mean.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And nobody modelled that packaging costs scaled to infinity, the more people who use it, right? There was no financial model put around it. We became a utility as opposed to just a repository. And I think that&#8217;s the moment for us that really changed things. You can continue to run events, Drupal Cons and Drupal Camps and all of that stuff. Those have pretty known economic models, and you can continue to run a website that promotes things. And you probably could even continue to be a collaboration platform.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But once you start to become a packaging utility, then you become part of everyone&#8217;s infrastructure. And if you start to provide that for free, and people will expect it to continue to be free. And so I&#8217;m, really it&#8217;s only in the last couple of years that I&#8217;ve started to look into those costs. And for Drupal, we provide the Drupal Association itself provides $10 in services to every site, every year, every modern Drupal site every year.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:13:16] <strong>Nathan Wrigley:</strong> Oh, that&#8217;s an interesting stat.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:13:17] <strong>Tiffany Farriss:</strong> It is.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:13:18] <strong>Nathan Wrigley:</strong> You&#8217;ve figured that out, you&#8217;ve done the maths and it costs $10 for every Drupal site that exists, whether or not they pay anything? That&#8217;s such an interesting number.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:13:26] <strong>Tiffany Farriss:</strong> Isn&#8217;t But I actually only take in $7.50. So I&#8217;ve been pushing forward in technical debt things for years. And that&#8217;s a risk, right? That&#8217;s a risk for me. And it&#8217;s also just unpleasant. I think that if we all start to become a little clearer around what the costs are as a utility, it&#8217;s actually not a lot.</p>\n\n\n\n<p class=\"wp-block-paragraph\">When it goes unpaid, it does have a cost, a compounding cost. And in Drupal&#8217;s history, what we used to say was if you want to support the project, support the conference. We all learned, obviously, during the pandemic that having an economic model based around a conference wasn&#8217;t the best choice.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I still think our ability to get together in person as a community is incredibly valuable, but I don&#8217;t see it as the way that we make the money to support the infrastructure. I really don&#8217;t like this idea that our revenues, and our expenses are so decoupled like that. And I think that&#8217;s really charity thinking.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And part of what I&#8217;m working to do is to evolve it into utility thinking? For a couple of reasons, right? One, it&#8217;s, not a charity. We are providing a service that people build businesses on, and they expect it to be there. But then also, especially in the case of Drupal, we have such a huge footprint in public sector work, and very large enterprise level government sites. And institutional sites, things that people need to have enterprise level expectations of. And they do, they hit our infrastructure every 15 minutes, right?</p>\n\n\n\n<p class=\"wp-block-paragraph\">Procurement has no way to pay either a community or a charity. However, they can pay for their costs if you can explain it to them in a cost recovery model that this is your share. And I want to be clear, as I talk about what the Drupal Association provides, that leaves aside the volunteer labor for what I like to consider the operational roles that also exist as a part of stewarded open source. Which are the release management, the security team, all of that work that we&#8217;re all so very hyper aware of after last week, that also has a cost.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So beyond the $10 that the Drupal Association is providing, there&#8217;s $30 provided just by the community as a keep the lights on sort of level. If we had to boil it down to its essence. Beyond what it takes to scratch your own itch, right?</p>\n\n\n\n<p class=\"wp-block-paragraph\">We all know that open source succeeds because I needed to write a module for this, I want to extend that. There are operational roles that aren&#8217;t actually in someone&#8217;s self-interest to perform, or to underwrite, if you&#8217;re an organisation. And so quantifying it has been something I&#8217;ve been working on for the last couple of months. And so we&#8217;re working now with this $40 a year figure around the services that are provided in addition to the code, that we don&#8217;t have to, right? The licence says it&#8217;s used as is, but nobody actually does that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:16:08] <strong>Nathan Wrigley:</strong> No. Okay. That&#8217;s an interesting thought. I&#8217;m just going to pivot ever so slightly and just talk about the community that you&#8217;ve got. I imagine it maps broadly to the community that we&#8217;ve got. Do you find having these conversations is challenging? Let&#8217;s go with that word. Because over on the WordPress side, is a reluctance for many people in the community to bring money into the conversation at all. You know, it is just almost a taboo in many senses.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And obviously you are pioneering this, the word dollar comes out a lot. You know, you&#8217;re actually putting specific numbers out there quite a lot. What&#8217;s the pushback like over there? Are there two camps? It&#8217;s like the &#8220;we&#8217;re never going to do this, is crazy,&#8221; and the acceptance? Or is there some sort of homogenous bit in the middle where people are starting to realise, okay, Tiffany&#8217;s making sense, this adds up. This is what we need to do in 2027, 2028.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Basically, how&#8217;s it going? How much pushback are you getting from your community?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:17:02] <strong>Tiffany Farriss:</strong> I think Drupal is a little bit different than WordPress because we don&#8217;t have a paid plugin economy. All modules are GPL&#8217;d and they&#8217;re free. So anyone who is working on Drupal has no direct way to monetize it. And I think that has made this conversation, this recognition a little bit clearer, right?</p>\n\n\n\n<p class=\"wp-block-paragraph\">Our entire economic base of support has been from a lot of the agencies. That&#8217;s the segment of our entire ecosystem that&#8217;s under the most pressure right now, and so if I say to them, I think we need to stop asking so much of you and we need to start asking more of the others in the ecosystem. It&#8217;s been a little bit of a recognition, like yeah, maybe that&#8217;s true.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Our ecosystem, our agency ecosystem, they give well beyond what they take from Drupal. And so I think for me, quantifying what just the general site takes from Drupal, has made it really sharp and clear that this isn&#8217;t a huge ask. And maybe the labor costs, maybe the infrastructure costs. It is time for us to be able to mature, and to recognise that more people need to be involved in supporting that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:18:09] <strong>Nathan Wrigley:</strong> I know that you are not involved in the WordPress space in the same way that you are with Drupal, but I&#8217;m just wondering if, from what you&#8217;ve just said, it sounds a little bit like you have more of a bat-phone into the people who need to be on side. In the WordPress space, I feel like there may be more people who, I don&#8217;t know, they own a plugin business, and they make money in that way, but they might contribute nothing back to the community.</p>\n\n\n\n<p class=\"wp-block-paragraph\">There&#8217;s people who turn up to events, there&#8217;s people who own hosting companies. They&#8217;re all spread out in different ways, and earning money in different ways. And so when messaging about, I guess our equivalent would be called Five For The Future, it&#8217;s very hard to know where to put that messaging, because you can&#8217;t really sum up where these people all are. They&#8217;re all over the place and there&#8217;s no one place where they gather.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But it sounds a little bit like, and I said bat phone, I hope you knew what I meant by that. It sounds like you have a line of communication which is much more easy to tap perhaps than we do on the WordPress side. If I&#8217;ve misunderstood that, please say.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:19:10] <strong>Tiffany Farriss:</strong> I think I do feel like we have a lot of engagement from a lot of the organisations. One of the major changes that Dries put in place back in 2014, was our contribution system. And so we know, it&#8217;s public, who is contributing to Drupal, and that&#8217;s not unique to us.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But I think the innovation is that every commit has the opportunity for an organisation as well as a sponsor. So when work is done in Drupal, we do have a lot of telemetry around who&#8217;s doing that work. So I think that&#8217;s given us insight into where some pieces of the value have been experienced over the last 25 years.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And so we&#8217;re able to recognise that. But I do think we over index on those agencies who are involved. And so have a lot of, currently we have a Drupal Certified Partner Program, where a lot of those agencies participate. And they know that they&#8217;re supporting and underwriting the infrastructure and they take a lot of pride in that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I think the difficulty is that one, we&#8217;re not a 501 (c) (6), we&#8217;re not a trade association. So I can&#8217;t deliver benefits specifically back to that group. You know, I can&#8217;t go out and say to procurement agents, &#8220;hey, you really should drive business to these folks. These are the ones who are actually supporting and working on Drupal,&#8221; because it feels like a pay to play. And in our case, there is some payment there, but it&#8217;s really you can&#8217;t become a Drupal Certified Partner without having made the maker contributions, you know?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:20:32] <strong>Nathan Wrigley:</strong> Oh, so there is a sort of quid pro quo there. If you contribute, I don&#8217;t know what the specifics are there, but if you manage to get over whatever the hurdle is, you can then access something. What is the something there that you can access? Sorry, I interrupted.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:20:48] <strong>Tiffany Farriss:</strong> Nothing. There&#8217;s nothing you can access, right? I mean, we recognise our makers on our website as Drupal Certified Partners.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But I do think that because it&#8217;s just a wall of logos, and it isn&#8217;t actually an attestation, it&#8217;s a lot of marketing copy, right? It becomes hard for procurement to put any credibility in it. And so this is actually the big innovation that I&#8217;m working on involving the Drupal Certified Partner Program, which is largely built around those agencies into a Drupal Certification Program that encompasses our entire ecosystem and essentially sets the standard.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:21:21] <strong>Nathan Wrigley:</strong> Tell us a little bit more about the things that you are doing there then. Because that sounds really intriguing.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:21:25] <strong>Tiffany Farriss:</strong> Yeah, I think that what I recognised is that as a 501 (c) (3), one of the things I can do is I can recognise those who are being good citizens. Now we have to come up with what that standard is. And I think in open source, it&#8217;s something that you know, but maybe hasn&#8217;t been articulated.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And part of that process has been to recognise that there are three pillars of contribution that are all essential for Drupal to be successful.</p>\n\n\n\n<p class=\"wp-block-paragraph\">First is making, those who are actually contributing code, or code adjacent activities to Drupal.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Patronage, right? Those who are actually funding the infrastructure. Funding the core release managers, the core maintainers, the security maintainers.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And then there&#8217;s also advocacy. Helping the world to understand what Drupal is and what it does, and to create the documentation, and to go out to events, and to help others learn to use it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So those are the three pillars of success. And so what we&#8217;re doing is we&#8217;re taking that idea of the contribution credit that we&#8217;ve had for a long time, which has always recognised more than just code contributions, and explicitly breaking it into these three areas.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And then our Drupal Certified Partner Program has been about agencies. So the eligibility requirements for who we recognise were based around what agencies already were doing. And what we&#8217;re evolving that into is different kinds of certification for all the parts of our ecosystem.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So we have platforms that are specifically Drupal tuned. Our platforms as a service partners. We have shared hosts. There are cloud hosts. There are infrastructure CDNs. There are end users. There are individuals. And so that entire spectrum of who&#8217;s participating, and getting value and benefit from Drupal, I want to create the opportunity for them to become Drupal certified.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And what that means is that Drupal certification is a badge of recognition of those who are engaging with Drupal in a net neutral, or net positive way. That they&#8217;re giving back at least what they are taking from the community, or more.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I think we start to move from something that is more like a sponsored badge wall, into a public trust register, which I think is, very helpful. And I, currently on Drupal.org, you can look up any individual, or any organisation, and you can see how they contribute. But unless you&#8217;re super in the weeds, it doesn&#8217;t mean much to you.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So I think that the lever here is around procurement, and around making this a trust ledger, something that can&#8217;t be bought. But something that is understandable to a procurement officer to say, who is contributing to Drupal? What are they contributing to Drupal, so that they can make decisions. Especially if they have two different potential vendors. One who contributes and one who doesn&#8217;t.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I think this is all a conversation we can now have because of the way that Europe is leading the way with their open source strategy. You know, that they want there to be more open source used in the services that they provide. From a digital sovereignty perspective, it&#8217;s essential for them.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:24:18] <strong>Nathan Wrigley:</strong> Let me see if I&#8217;ve understood that correctly. So on one level, I&#8217;m just going to use the word Brussels. I hope that everybody understands what I mean when I say Brussels.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:24:25] <strong>Tiffany Farriss:</strong> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:24:26] <strong>Nathan Wrigley:</strong> So, Brussels encapsulates the EU, the governance of the EU. Because of the posture that Brussels takes. It could, coerce is the wrong word, but let&#8217;s go with that. It could apply a certain degree of pressure to big procurement initiatives to say, look, I don&#8217;t know, we need a new website for the French Health Service or whatever. And Drupal is right in there, and we&#8217;re looking for organisations that can help us to build that Drupal infrastructure.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Given that&#8217;s the case, we are now going to go to this extra layer of what do these agencies that are competing for this contract, what is their position vis-a-vis Drupal? And if it looks good, in that you&#8217;ve contributed in the past and you have all the accreditation and what have you, you will more likely have a favourable outcome in that procurement procedure. Did I sum that up right or have I completely misunderstood?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:25:22] <strong>Tiffany Farriss:</strong> No, I think that&#8217;s a part of it, right? I think that Brussels has already recognised that it&#8217;s in their interests to use open source products, right, open source solutions, and has for a while. But I think procurement&#8217;s the real lever where we start to enshrine or encourage bad behaviour, right? What we were calling extractive use of open source.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So if you think of open source as just lumber that you can take and use however you want, right? If nobody is replanting the trees, cutting it down, sawing the boards, then it doesn&#8217;t exist anymore, right?</p>\n\n\n\n<p class=\"wp-block-paragraph\">And also on the government side, when we talk about public money, public code. It&#8217;s important that you actually get the benefits of it. So it wasn&#8217;t just a starter kit that you take and then you own, right? We know that good use of open source, whether it is WordPress or Drupal or TYPO3, right? You want to minimise the amount of code that you own. That&#8217;s the advantage. That&#8217;s how we all experience the network effects.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So you need to have some behaviours, and I think that procurement officers don&#8217;t care, don&#8217;t need to know, about what open source is or our specific projects. But what they need to know is that when they are procuring any project, or any solution, that has open source as a component of it. That open source isn&#8217;t going to end up being code that they own down the road. They have the right to use it, extend it forever, and they know that somebody can&#8217;t turn it off on them, which is I think a very important.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:26:48] <strong>Nathan Wrigley:</strong> Oh, big thing at the minute.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:26:49] <strong>Tiffany Farriss:</strong> Big thing right now, especially in light of the 2018 USA Cloud Act, right? So that&#8217;s really been the driving impetus around digital sovereignty. But when we think about good open source use, responsible open source use, there are some behaviours that regardless of project we know are true.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And it is that when you write a new plugin or module, you release it, right? So others can use it so that you&#8217;re sharing the maintenance burden moving forward. If you don&#8217;t, then you own that and you&#8217;re going to maintain those lines of code yourself.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Two, if you patch something, you want to release that patch upstream because otherwise you may have ended up inadvertently forking it. Or in some cases the government pays for the same patch over and over and over again, right? If there are economic benefit to using open source, you need to know that whatever vendor you&#8217;re using is contributing the patches back upstream so that you continue to stay, anything that&#8217;s non-confidential, obviously, but so that you can stay current and up to date, right? Woe for those who were not current and up to date last week with PHP, right? It made that problem all the more difficult.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So when I think about making it open source use at the government level very sustainable, there&#8217;s really three policies I think that they need to implement to help really get the benefits of open source, right?</p>\n\n\n\n<p class=\"wp-block-paragraph\">One is that the patches are contributed upstream if they&#8217;re non-confidential within 30 days.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Two, I think that they need to understand that there is a cost to their use. And so creating whether it&#8217;s 2% or 5%, creating a line item in every project that uses open source of any flavour, for the delivery of the project, that there is a standard percentage that is contributed back upstream to that open source project, to offset that use. Because right now, the agencies and the companies that are responsible open source users, they bear their contributions and their participation in open source as a tax. So it becomes baked into their hourly rates. Which then as economic conditions get constrained, it becomes a disadvantage to do the right thing for open source.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So I&#8217;m very worried about that. But if it is instead a flat line item that all who are responding to a tender have to meet, then the virtuous behaviour that continues the virtuous cycle of open source isn&#8217;t a burden on any one firm.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And then the third piece is you want to know, are they a contributor to that open source project? And so this speaks right to Dries&#8217; maker taker dilemma, which I&#8217;ve extended to the maker taker faker dilemma. Which is obviously, I think makers and takers are pretty clear, right? You either are someone who&#8217;s making and contributing into your open source project. And takers being the ones who are like, thanks for the wood little elves who magically made it in the woods. Great. This is all good. Good luck with that forest.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I think that the fakers are, in some ways, much more dangerous, because they have this, it&#8217;s like open source washing. The fakers are the ones who maybe sponsored a coffee one time at an event, but they&#8217;re not really giving things back. So they&#8217;ve got a badge. Procurement, they can say, oh look, I&#8217;m a sponsor.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I appreciate anyone who sponsors at any level. But I think that when you&#8217;re talking about competing on a public procurement, there is a very important difference between someone who maintains modules, contributes to the security team, and someone who sponsors a coffee. And I think that it&#8217;s on us as open source projects to make that clearer.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So the Drupal certification is our attempt to really become a very trusted public ledger about who&#8217;s contributing what, and why it matters to folks who aren&#8217;t in our community. I think today, where we stand and where we&#8217;re starting, it is a very transparent ledger. But there&#8217;s a difference between transparency and clarity. And I think if we want Brussels, and other governments and procurement, officers to be able to differentiate and give a preference to those who are good open source citizens, if you will, those who are actually involved in the projects that they&#8217;re using and implementing, for these very important public projects, I think it&#8217;s on us to make that easier. So that&#8217;s something I&#8217;ll be focused on next year.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:31:02] <strong>Nathan Wrigley:</strong> It sounds to me like you could kind of sum this up in the word clarity. Everybody needs clarity. Those people who are procuring things need to be clear on what they&#8217;re going to get. Those people who are delivering things need to be clear on what they&#8217;re going to do. And the notoriety, for want of a better word that they&#8217;re going to get from that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">It also seems like you are in a very interesting role, where you are like this go-between between all the people doing the work on Drupal, and the people who are procuring, and I&#8217;m sure that&#8217;s really fascinating work. Like what is the proclivity of, let&#8217;s say for example, USA or Canada. What are the requirements that they have around, I don&#8217;t know, 20% of all public software needs to be open source or something like that. That must be utterly fascinating work. You&#8217;re right at the chalk face of all this. Wow, that&#8217;s so interesting.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:31:52] <strong>Tiffany Farriss:</strong> It&#8217;s absolute candy to my brain. Like I just, I can&#8217;t tell you how much I really am enjoying being part of those conversations. And I never would&#8217;ve thought that I would&#8217;ve been invited to speak at a plenary at the United Nations, and yet I was. And that blog post that you mentioned, that&#8217;s on palantir.net, actually those are remarks I gave to the German Consulate, in New York, right?</p>\n\n\n\n<p class=\"wp-block-paragraph\">It all comes from this conversation we&#8217;re all just starting to have about what does it mean to sustainably and responsibly use open source as we look ahead to the next 25 years, next a hundred years.</p>\n\n\n\n<p class=\"wp-block-paragraph\">There was a board member I had served with in Drupal a long time ago, Donna Benjamin, and this was, I don&#8217;t know, maybe almost 20 years ago now. And she always used to say, what&#8217;s our a hundred year plan? And at the time, I was taken back. I&#8217;m like, uh, I can&#8217;t even with that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And now as we fast forward to where we are today, I actually can start to see that. And it&#8217;s about understanding that nobody intends and sets out to be a taker, right? You can&#8217;t pay for things that you don&#8217;t know are there, or things you don&#8217;t know are already happening. And you can&#8217;t meet expectations that aren&#8217;t communicated.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So this is the opportunity for open source projects to say, this is what it takes for us today. This is what it takes for us where we want to go. And here&#8217;s your share of it. How do we make it easy, and expected that everyone does a little, so we&#8217;re not resting on a few who have to do a lot?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:33:22] <strong>Nathan Wrigley:</strong> This is going to sound like a really poor summation of it, but it feels like open source, up until this point, you know, the analogy, carrot and stick, you know.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:33:30] <strong>Tiffany Farriss:</strong> Yes.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:33:30] <strong>Nathan Wrigley:</strong> So the carrot is, we hope that you&#8217;ll come along and, you know, follow the lead and do all of the right things. Where a stick is more, if you don&#8217;t do the right thing, there&#8217;ll be a punishment for that. It feels like open source for the last 20, 25 years, there&#8217;s been more carrot than stick. And although it&#8217;s incorrect to summarise this as stick, is there a little bit of stick here? Are we trying to cast a, let&#8217;s say, a glowing light on those that do everything well, who are the makers? You know, we want to raise your profile, shout from the rooftops that you did things well.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Conversely, is there a bit of okay, those that don&#8217;t, we are going to shame. Or is it more a case of we just leave you alone? You just don&#8217;t get a mention. You don&#8217;t get to be part of the community in quite the same way.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:34:15] <strong>Tiffany Farriss:</strong> Coming back to that frame as open source stewardship as a utility. Nobody considers it a donation to their electric company. They pay the bill because the lights matter. And I think it&#8217;s about resetting this frame. We&#8217;ve never sent utility bills to people. We&#8217;ve never even exposed what that looks like, or maybe we don&#8217;t know ourselves. Based on projects, Drupal certainly didn&#8217;t until I started this work.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So I think that there&#8217;s this expectation that we&#8217;re going to continue as we always have on this balance of goodwill and volunteerism. But as last week showed, PHP Foundation, which WordPress is very involved in, Drupal as well, has one full-time employee. And 70% of the web runs on it. So it&#8217;s something that we have taken for granted for too long. And I think that this moment is brokered by the blessing and the curse that is AI.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:35:07] <strong>Nathan Wrigley:</strong> I wonder if the wider issue at stake really is notifying the general public. Letting all of humanity know that when you are picking up your phone and using that app, and it&#8217;s connecting with that service over here to enable you to, I don&#8217;t know, book a restaurant or get a taxi. There&#8217;s probably some layer of free software around there.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And would you do anything for free? Is that, I&#8217;m not asking you that question by the way. I&#8217;m just saying, you know, dear app user, would you do things for free in the same way that you&#8217;re expecting this software to be free?</p>\n\n\n\n<p class=\"wp-block-paragraph\">And I think that argument&#8217;s fairly persuasive, but it&#8217;s not something that has leaked out into the public. You know, the coverage of the PHP thing, nobody knew. The guy that came on the BBC, who was the BBC correspondent, he&#8217;d never heard of PHP. And he&#8217;s the cybersecurity correspondent for the BBC had never heard of PHP.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And so getting it out into the vernacular, getting it out into the mainstream, that all of this stuff that you&#8217;ve taken for granted, we all need to pay a little bit. I wonder if that&#8217;s an interesting. It&#8217;s like the stick that I was talking about earlier. If the public are more aware whether they will be able to pressure things a little bit more. I don&#8217;t know. I&#8217;m not sure there&#8217;s any mileage in that, in all honesty, but it&#8217;d be an interesting experiment to run.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:36:20] <strong>Tiffany Farriss:</strong> I think we&#8217;re about to see that experiment, right? So the Cyber Resilience Act in Europe is requiring SBOMs, which are Service Bill Of Materials to be disclosed. And I think that once SBOMs are readily available, it may become clearer, at least to decision makers, exactly how much open source software is in the solutions that you&#8217;re providing. And I really am curious to see how it evolves when you do have these manufacturers or organisations, whether they&#8217;re service organisations or actual manufacturers, starting to become liable for the risks in your security chain.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:36:56] <strong>Nathan Wrigley:</strong> Right.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:36:56] <strong>Tiffany Farriss:</strong> As I look at this, I look at it as a supply chain issue. And so we&#8217;ve now exposed that there are weaknesses in our supply chain. So the argument isn&#8217;t, it&#8217;s really less of a shaming. It&#8217;s saying hey, this is a risk management approach. And I was looking at it as a design flaw. That open source was an idea around writing software. It wasn&#8217;t actually envisioned at any time that this was going to run the world. It was just, this is a good idea to do good way to do things. Let&#8217;s try it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But now that we understand that open source does run everything, we need to come back and treat this as a design problem and say, how do we align the incentives? What needs to be true?</p>\n\n\n\n<p class=\"wp-block-paragraph\">I appreciate the work that&#8217;s going on in Europe right now, and I think that becomes a bit of the stick. It&#8217;s not coming from us. It&#8217;s saying, actually if you sell a product that&#8217;s based on open source, and that open source has a security issue, you are liable. You&#8217;re the manufacturer. See, as an open source steward, the Drupal Association does not have liability. We have responsibilities to disclose, which we have done, all the way back through 2007.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Drupal is a CNA, right? We&#8217;re a numbering authority for CVEs. We&#8217;ve had a very mature security practise for many years, and we will continue to do so, and meet our CRA disclosure requirements. But those who have blindly been using open source in products or in services for others, they&#8217;re now manufacturers. And come December of next year, they&#8217;re really going to start to understand how liable they&#8217;ve become for any issues in the supply chain.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:38:34] <strong>Nathan Wrigley:</strong> There&#8217;s something quite virtuous about that. In that it&#8217;s allowing the open source posture to carry on in the same way that it always has. Shifting the responsibility over to the governments in a way. You know, that they&#8217;ll create the legislation, which means that if you fall foul of this, that and the other thing, you will now be responsible. And if you are responsible, it&#8217;s it&#8217;s the same reason we have car insurance and buildings insurance. You need to know what your position is going to be in the event of a fire or a crash. You just have to know it. Because if your business were to go under because you weren&#8217;t thinking about those things, that would just be negligence. And so that&#8217;s such an interesting way of framing it. I like that a lot.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I also like your definition there. You described the internet over, you know, the last 20 years and how nobody knew that it was going to work this way, and now here we are. And, I guess it would be a bit like, I don&#8217;t know, going to a lemonade stand or something like that and getting a really cheap lemonade from a child who&#8217;d done it because it was a nice thing to do for the community. Let&#8217;s sell cheap lemonade.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But then turning up with 12,000 people and saying, we would like 12,000 cheap lemonades, please. Immediately. No, that&#8217;s not available. That&#8217;s not the way it was designed. And that feels to have certain overlaps here.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Nobody knew that open source was going to take over the world. Now it has. It&#8217;s chronically underfunded. There will be a collapse at some point if companies and businesses are allowed to just have a taker mentality. So you are putting things in place to make sure that is checked. And I think that&#8217;s really interesting.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:40:06] <strong>Tiffany Farriss:</strong> It goes from this idea that we passively consume whatever we get. Whether it&#8217;s a website or a phone. To this idea of having some sort of active upstream strategy. And again, I don&#8217;t think that many of us had the opportunity to understand what software was running on our phone. You didn&#8217;t know, right? You can&#8217;t mitigate a risk that you don&#8217;t know is there. I do think it is unreasonable to think that we don&#8217;t know the risk is there now, especially after last week.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:40:33] <strong>Nathan Wrigley:</strong> There&#8217;s just no bit of me which would walk into a store and pick things up and just wander out and say. There it is. I&#8217;m going to have it because it&#8217;s there for me to take. And yet, broadly speaking, I think it&#8217;s fair to say that the vast majority of the people in the world consuming things on the internet have exactly that position.</p>\n\n\n\n<p class=\"wp-block-paragraph\">You switch on the device, the device itself is probably working on, in many cases, open source software. And then I&#8217;m just going to consume all the things that are there, you know, it&#8217;s all free. You know, it might not be free, it might be sponsored by advertising or what have you know, we all have opinions on that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But we have got ourselves into this position where we completely pick up the devices and think, all free, from top to bottom, free. And we need to change that mentality. So, going back to what I said earlier, getting the message out to the population at large, I don&#8217;t know how you do that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:41:25] <strong>Tiffany Farriss:</strong> I&#8217;m a big believer in what Buckminster Fuller called the trim tabs, right? I don&#8217;t set out to turn the ship. I turn the little piece, the trim tab that turns the rudder, and that turns the ship. And I think that whether we&#8217;re talking about compliance, or we&#8217;re talking about OSBOs, and helping compliance within organisations, I think that&#8217;s how we turn the ship, right?</p>\n\n\n\n<p class=\"wp-block-paragraph\">We need to create an economic model that really does protect the supply chain. This is a consumer problem. It is a consumer risk. And I think that&#8217;s exactly what many governments were set up to deal with.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And so I think they do have the opportunity that the governments, whether it&#8217;s the EU or the US or the Canadian government, they spend so much money. And if they change the way that they spend money, and they change the way that they look at open source and how they understand it. And to be a responsible open source consumer, who&#8217;s asking for, are we giving back? Are we minimising our footprint? Are we restoring services that we use? Are we treating it like the utility that it is? That alone makes such a huge difference, such a huge difference.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And helps us to move away from this idea of licence only open source economics. Which is essentially that idea that I&#8217;m just going to take it because the cost of code go to zero over time, right? That&#8217;s not it alone, right?</p>\n\n\n\n<p class=\"wp-block-paragraph\">We expect that when someone finds an issue, especially an issue that can cause remote execution, right? That they&#8217;re going to tell us about it. That they&#8217;re going to fix it. And that we&#8217;re going to be able to have access to that fix. And that&#8217;s where we move beyond this idea that the licence itself is free, and it will be free forever.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Those services that is about the human capital, and the human technology that make those things possible. And they are not free, they have never been free. You just haven&#8217;t known who was picking up the bill on your behalf.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:43:17] <strong>Nathan Wrigley:</strong> What kind of timeframe? This is going to be my last question by the way. What kind of timeframe do you put on this. How far into the future are you gazing? I&#8217;m guessing the answer is it&#8217;ll never be complete, this work. But how far into the future are you hoping to get so that you can look in the rear view mirror and say, yeah, we&#8217;ve achieved most of what we wanted to do there.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:43:37] <strong>Tiffany Farriss:</strong> Because we&#8217;re kind of on forefront here in having these conversations, and we&#8217;re certainly not alone. Every one of the open source foundations is having some version of this conversation, or some approach that they&#8217;re trying, to make sure that they have the base of support that is commensurate to the folks that they serve, right?</p>\n\n\n\n<p class=\"wp-block-paragraph\">I really am approaching this as a pilot for the next six months, and seeing can we, as we broaden and understand different segments of our ecosystem, and the ways in which they can contribute that align with their interests, right? I&#8217;m always looking for the triple win. The win for Drupal. The win for the end agency. And the win for the public, right? Because I am a public facing charity, right? I want all of those things to be true.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And I&#8217;ll be experimenting and having conversations with infrastructure providers, with our shared hosting platforms, with cloud providers to say, okay, what does it make sense for you to contribute? What does it mean for you to be a good Drupal citizen, and to give back in a way that feels appropriate to the amount of value that you&#8217;re generating from this?</p>\n\n\n\n<p class=\"wp-block-paragraph\">I don&#8217;t think that any system can be designed where it requires a hundred percent good behaviour, or a hundred percent participation. It&#8217;s going to be a process of iteration and learning as fast as I can. Making sure that we&#8217;re being transparent about it, and approaching it from this cost expensing perspective. I&#8217;m not looking to maximise profit or other things. I&#8217;m a not-for-profit, and I care about resources, and money, and attention going to Drupal. If it comes to the DA, through the DA or directly into the Drupal community, all of those states are a win.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So it creates a great table for conversations with different kinds of players and providers who haven&#8217;t engaged. But at least now I can go to them and say, hey, this is what you&#8217;re already consuming from our ecosystem. And here&#8217;s a pretty good back a napkin for what I think you&#8217;re making from it. If we didn&#8217;t exist, what would you do? How would you do the security pieces? How would you do the packaging pieces?</p>\n\n\n\n<p class=\"wp-block-paragraph\">And it&#8217;s okay if one of the answers in those conversations is, oh, wow, I didn&#8217;t realise we were using so much. We can dial that back. That&#8217;s perfectly valid. I want to make sure that open source and that Drupal is there for whoever wants it in as secure and as innovative a way as possible.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And so whether you reduce how often you ping my packaging server or you are like, yes, I need this, this is part of my critical infrastructure, and you fund it as if it is a utility part of your infrastructure. Both of those are valid answers to me.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:46:03] <strong>Nathan Wrigley:</strong> There&#8217;s so many people in the WordPress space who will resonate with everything that you are doing here. I said I was going to ask no more questions. I have one more. Do you have lines of communication open with, for example, WordPress and maybe PHP? Are you doing this very much in isolation, even though there may be overlaps? Do you have that? Would you welcome that? Would you like to have introductions to people? And if so how can people communicate that to you?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:46:29] <strong>Tiffany Farriss:</strong> I&#8217;m always happy to talk to everyone. I will say Drupal and Joomla, WordPress and TYPO3, we have the Open Web Alliance, and so we do talk every month. And we&#8217;ve just invited PHP to be a part of that obviously. I have Slack access to all of those folks and we do talk regularly.</p>\n\n\n\n<p class=\"wp-block-paragraph\">In addition, there&#8217;s just a broader open source community of leaders. There was the Open Source Congress, that happened in September. I really appreciate being able to talk to my colleagues whether it&#8217;s RubyCon for the Apache Foundation, which actually put on this year&#8217;s Open Source Congress and did a fantastic job. All of us being able to talk together.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I can say to the CEO of Python, I can say, oh you know, hey what lawyer are you using right now? Or what software did you use for your community elections? I&#8217;m looking for some new ones, right? And they have tonnes of ideas and then I&#8217;m able to say, oh, here&#8217;s how we are doing this, or here&#8217;s how we&#8217;re doing that. And I just think that level of collaboration and conversation, has been incredible. Right. Rust Foundation, UN Open Source Week and the EU Open Source Week, and Open Source Congress. Those conversations among colleagues have been fantastic.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Any new colleagues I&#8217;m happy to talk to as well. You can reach me on many different Slacks, whether it&#8217;s the Open Source Congress Slack, or the Alpha Omega Project for Drupal. I&#8217;m in Drupal Slack. You can reach me in all of those places, is @Farriss. That&#8217;s FARRISS.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:47:51] <strong>Nathan Wrigley:</strong> Nice. Thank you so much. It really is fascinating work. I would really be genuinely curious to watch what you are doing over the the next six months. Where you end up. How the project is received at both ends.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:48:04] <strong>Tiffany Farriss:</strong> Me too.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:48:04] <strong>Nathan Wrigley:</strong> To see what the pushback is like. I would really love to keep a track of what&#8217;s going on. But for now, best of luck. I hope that it all pans out in the way you&#8217;re anticipating. So, Tiffany Farriss, thank you so much for making the time to chat to me today.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:48:16] <strong>Tiffany Farriss:</strong> Nathan, thank you for having me.</p>\n</div></details>\n\n\n\n<p class=\"wp-block-paragraph\">On the podcast today we have <a href=\"https://www.drupal.org/u/farriss\">Tiffany Farriss</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Tiffany has spent the last 30 years working in web design, development, and creation, and she’s been deeply embedded in the Drupal community for the past two decades. She’s currently the interim CEO of the Drupal Association, and is the organisation’s longest-serving board member after Drupal’s founder, Dries Buytaert.</p>\n\n\n\n<p class=\"wp-block-paragraph\">This episode is a bit of a departure, as we usually focus squarely on WordPress. But Tiffany brings a wealth of experience from the broader PHP family, and this conversation explores the similarities and differences between the WordPress and Drupal ecosystems, particularly when it comes to infrastructure, and the sustainability of open source projects.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Tiffany explains the ‘maker-taker’ problem and the challenges of sustaining free software platforms that underpin millions of sites across the web. She shares her insights on the real costs behind open source stewardship, drawing from both data and experience, and discusses how tiny groups have shouldered the burden for everyone, and why that might no longer be viable.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The discussion explores the Drupal Certified Partner program, the push towards quantifying contributions, and how the open source community can improve transparency and sustainability. Tiffany also touches on the role of public sector procurement in shaping the future of open source, the impact of new regulations, and how community-driven recognition could incentivise more organisations to ‘buy their round of beers’ for the ecosystem.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you’re interested in the sustainability of open source, the evolution of governance models, and how WordPress professionals can learn from the broader PHP landscape, this episode is for you.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Useful links</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://www.drupal.org/u/farriss\">Tiffany on Drupal.org</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://www.drupal.org/association\">Drupal Association</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://dri.es/about\"> Dries Buytaert</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://www.palantir.net\">Palantir.net</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://new.drupal.org\">Drupal.org</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://www.drupal.org/drupalcon\">DrupalCon</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://www.drupal.org/community/events\">Drupal Events</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://www.acquia.com\">Acquia</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://wordpress.org/five-for-the-future/\">Five for the Future</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://new.drupal.org/association/become-a-drupal-certified-partner\">Drupal Certified Partner Program</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://en.wikipedia.org/wiki/CLOUD_Act\">2018 USA Cloud Act</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://digital-strategy.ec.europa.eu/en/policies/cyber-resilience-act\"> Cyber Resilience Act</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://www.joomla.org\">Joomla</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://typo3.org\">TYPO3</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://openwebsitealliance.org\">Open Web Alliance</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://opensourcecongress.org\">Open Source Congress</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://www.apache.org\">Apache Foundation</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://www.unopensource.org\">UN Open Source Week</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://opensourceweek.eu\">EU Open Source Week</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://www.drupal.org/association/blog/drupal-association-secures-alpha-omega-grant-to-future-proof-open-source-security-for-the-ai-era\"> Alpha Omega Project for Drupal</a></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 11 Nov 2026 13:00:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:14:\"Nathan Wrigley\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:24;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:63:\"Open Channels FM: The Hidden Costs of Burnout for Women in Tech\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2566497\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:70:\"https://openchannels.fm/the-hidden-costs-of-burnout-for-women-in-tech/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:339:\"The tech industry is often celebrated for innovation and progress, yet behind the buzz, many women are weighing whether to limit their hours, step back from leadership, or leave the field entirely. Burnout is at the heart of this crossroads, and its impact goes far beyond individual exhaustion. In the most recent Gender in Tech [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 11 Nov 2026 11:08:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"Open Channels FM\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:25;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:65:\"Open Channels FM: Debating AI’s Role in Open Source Communities\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2565345\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:69:\"https://openchannels.fm/debating-ais-role-in-open-source-communities/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:231:\"Open source communities are debating the role of artificial intelligence, questioning whether AI-generated software aligns with traditional values of collaboration and transparency, reshaping definitions of openness in the process.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 10 Nov 2026 18:27:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"Open Channels FM\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:26;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:40:\"WordPress.org blog: WordPress 7.2 Beta 5\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://wordpress.org/news/?p=21967\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:56:\"https://wordpress.org/news/2026/11/wordpress-7-2-beta-5/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:7818:\"<p class=\"wp-block-paragraph\">WordPress 7.2 Beta 5 is ready for download and testing!</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>This beta release is intended for testing and development</strong> only. Please do not install, run, or test this version of WordPress on production or mission-critical websites. Instead, use a test environment or local site to explore the new features.</p>\n\n\n\n<h2 class=\"wp-block-heading\">How to Test WordPress 7.2 Beta 5</h2>\n\n\n\n<p class=\"wp-block-paragraph\">You can test WordPress 7.2 Beta 5 in any of the following ways:</p>\n\n\n\n<figure class=\"wp-block-table\"><table class=\"has-fixed-layout\"><tbody><tr><td><strong>WordPress Beta Tester Plugin</strong></td><td>Install and activate the <a href=\"https://wordpress.org/plugins/wordpress-beta-tester/\" rel=\"noreferrer noopener\" target=\"_blank\">WordPress Beta Tester</a> plugin on a WordPress install. Select the “Bleeding edge” channel and “Beta/RC Only” stream.</td></tr><tr><td><strong>Direct Download</strong></td><td>Download the <a href=\"https://wordpress.org/wordpress-7.2-beta5.zip\">Beta 5 version (zip)</a> and install it on a WordPress website.</td></tr><tr><td><strong>Command Line (WP-CLI)</strong></td><td>Use this <a href=\"https://make.wordpress.org/cli/\" rel=\"noreferrer noopener\" target=\"_blank\">WP-CLI</a> command: <br /><code>wp core update --version=7.2-beta5</code></td></tr><tr><td><strong>WordPress Playground</strong></td><td>Use a <a href=\"https://playground.wordpress.net/release\" rel=\"noopener\" target=\"_blank\">7.2 Beta 5 WordPress Playground instance</a> to test the software directly in your browser. No setup required-just click and go!</td></tr></tbody></table></figure>\n\n\n\n<p class=\"wp-block-paragraph\">The scheduled final release date for WordPress 7.2 is <strong><strong>December 8, 2026</strong></strong>. The full <a href=\"https://make.wordpress.org/core/2026/10/06/wordpress-7-2-release-party-schedule/\">release schedule can be found here</a>. Your help testing Beta and RC versions is vital to making this release as stable and powerful as possible. Thank you to everyone who contributes by testing!</p>\n\n\n\n<h2 class=\"wp-block-heading\">What&#8217;s in WordPress 7.2 Beta 5?</h2>\n\n\n\n<p class=\"wp-block-paragraph\">For technical details on the issues addressed since Beta 4, see the following links:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li><a href=\"https://core.trac.wordpress.org/query?status=closed&amp;changetime=11%2F03%2F2026..11%2F10%2F2026&amp;milestone=7.2&amp;group=component&amp;col=id&amp;col=milestone&amp;col=owner&amp;col=type&amp;col=priority&amp;order=id\">Closed 7.2 WordPress Core Trac tickets</a> since November 3, 2026</li>\n\n\n\n<li><a href=\"https://github.com/WordPress/gutenberg/commits/wp/7.2?since=2026-11-03&amp;until=2026-11-10\">7.2 Gutenberg commits</a> since November 3, 2026</li>\n</ul>\n\n\n\n<h3 class=\"wp-block-heading\">Continued Improvements to WordPress 7.2</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 Beta 5 continues refining the upcoming release with additional security, accessibility, and compatibility improvements.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Recent changes include email notifications when application passwords are created, improved keyboard navigation in the WordPress admin toolbar, and accessibility refinements to Visual History. Additional fixes strengthen permissions for Notes reactions, improve compatibility with MP3 uploads, and address automatic update behavior in Git worktree installations.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://core.trac.wordpress.org/ticket/63927\">Trac #63927</a>, <a href=\"https://core.trac.wordpress.org/ticket/66331\">Trac #66331</a>, <a href=\"https://core.trac.wordpress.org/ticket/65122\">Trac #65122</a>, <a href=\"https://core.trac.wordpress.org/ticket/66447\">Trac #66447</a>, <a href=\"https://core.trac.wordpress.org/ticket/46544\">Trac #46544</a>, <a href=\"https://core.trac.wordpress.org/ticket/66460\">Trac #66460</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">Further Refinements to Ipsum</h3>\n\n\n\n<p class=\"wp-block-paragraph\">The new default theme, Ipsum, receives another round of improvements in WordPress 7.2 Beta 5. Accessibility enhancements include improved keyboard focus indicators and view transitions that respect reduced-motion preferences. Additional refinements to block styles and patterns provide greater design flexibility, while optimized stylesheets and other under-the-hood improvements help prepare the theme for its final release.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://core.trac.wordpress.org/ticket/66631\">Trac #66631</a>, <a href=\"https://github.com/WordPress/ipsum/pull/198\">GitHub #198</a>, <a href=\"https://github.com/WordPress/ipsum/pull/187\">GitHub #187</a>, <a href=\"https://github.com/WordPress/ipsum/pull/180\">GitHub #180</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">PHP 8.6 Compatibility Improvements</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 aims to fully support PHP 8.6, which is scheduled to be released on November 19, 2026. The WordPress project has a long history of being compatible with new versions of PHP as soon as possible, and this release is no different.</p>\n\n\n\n<p class=\"wp-block-paragraph\">As of the Beta 5 release, all known compatibility issues with PHP 8.6 have been resolved.</p>\n\n\n\n<p class=\"wp-block-paragraph\">While all of the known issues in WordPress have been addressed, you will need to verify that all of your plugins and themes are also compatible with PHP 8.6 prior to upgrading. Keep an eye on the Making WordPress Core blog in the coming days for more detailed information about what to look for.</p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress continues to encourage all users to run the latest and greatest versions of PHP.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://core.trac.wordpress.org/ticket/66648\">Trac #66648</a></p>\n\n\n\n<h2 class=\"wp-block-heading\">How important is your testing?</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Testing for issues is a critical part of developing any software, and it’s a meaningful way for anyone to contribute – whether or not you have experience. <a href=\"https://make.wordpress.org/test/2026/10/20/help-test-wordpress-7-2/\">Details on what to test in WordPress 7.2 are available here</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you encounter an issue, please share it in the <a href=\"https://wordpress.org/support/forum/alphabeta/\" rel=\"noopener\" target=\"_blank\">Alpha/Beta area</a> of the support forums. If you are comfortable submitting a reproducible bug report, you can do so <a href=\"https://core.trac.wordpress.org/newticket\" rel=\"noopener\" target=\"_blank\">via WordPress Trac</a>. You can also check your issue against this list of <a href=\"https://core.trac.wordpress.org/tickets/major\" rel=\"noopener\" target=\"_blank\">known bugs</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Curious about testing releases in general and how to get started? Follow along with the <a href=\"https://make.wordpress.org/test/\">testing initiatives in Make Core</a> and join the <a href=\"https://wordpress.slack.com/messages/core-test/\">#core-test channel</a> on <a href=\"https://wordpress.slack.com/\">Making WordPress Slack</a>.</p>\n\n\n\n<h2 class=\"wp-block-heading\">A Beta 5 haiku</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><em>One last beta blooms<br />Release candidate awaits<br />The finish draws near</em></p>\n\n\n\n<p class=\"has-text-align-right wp-block-paragraph\"><em>Props to <a class=\"mention\" href=\"https://profiles.wordpress.org/audrasjb/\"><span class=\"mentions-prefix\">@</span>audrasjb</a> and <a class=\"mention\" href=\"https://profiles.wordpress.org/desrosj/\"><span class=\"mentions-prefix\">@</span>desrosj</a> for pre-publish review.</em></p>\n\n\n\n<p class=\"wp-block-paragraph\"></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 10 Nov 2026 16:59:09 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:14:\"David Baumwald\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:27;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:104:\"Open Channels FM: Open Source Challenges Examined AI Models, Linux Exploits, and Federal Oversight Tools\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2566674\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:107:\"https://openchannels.fm/metas-llama-2-license-openai-bug-finding-in-linux-and-open-source-regulation-tools/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:148:\"AI models’ open-source promises, Linux kernel security tests by OpenAI, and new banking oversight technology at the Federal Reserve are discussed.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 10 Nov 2026 15:00:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:28;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:62:\"Open Channels FM: Defaults, and Why They Quietly Run the World\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2566511\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:68:\"https://openchannels.fm/defaults-and-why-they-quietly-run-the-world/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:111:\"A conversation about how defaults shape our online privacy and everyday habits with Bob Dunn and Nathan Wrigley\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 10 Nov 2026 11:04:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:29;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:72:\"WordPress.org blog: WordPress Credits Welcomes More Than 50 Institutions\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://wordpress.org/news/?p=21881\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:57:\"https://wordpress.org/news/2026/11/wp-credits-reaches-50/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:3386:\"<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-21882\" height=\"576\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/10/Upside-down-lightbulb-sketches-in-notebook.png?resize=1024%2C576&#038;ssl=1\" width=\"1024\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">More than 50 educational institutions have joined <a href=\"https://wordpress.org/education/credits/\">WordPress Credits</a>, giving students worldwide a way to earn academic recognition for contributing to WordPress. The program had two participating institutions in September 2025 and four the following month. By June 2026, that number had reached 27, before passing 50 this October.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The program launched with the University of Pisa and was announced at WordCamp Europe 2025. Since then, it has expanded through partnerships that connect students with experienced contributors and practical projects. The <a href=\"https://wordpress.github.io/WPCredits/\">WordPress Credits dashboard</a> recorded participating institutions across 17 countries as of October 19, including Bangladesh, Costa Rica, Spain, Bolivia, and Indonesia. Each institution can adapt the program to its academic requirements, allowing students to contribute as part of their studies.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-21883\" height=\"431\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/10/Screenshot-2026-10-23-at-1.16.32-pm.png?resize=1024%2C431&#038;ssl=1\" width=\"1024\" /></figure>\n\n\n\n<h2 class=\"wp-block-heading\">Learn through contribution</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Students work with mentors on projects that reflect their interests and areas of study. They might translate WordPress, improve documentation, create learning materials, or contribute to development and testing. Alongside that work, they practice collaborating with others and responding to feedback, then present their contributions at the end of the program. By October 19, the dashboard recorded 364 graduates and student contributions across 18 WordPress teams. That work supports the software and resources people use throughout the WordPress community.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Help the program grow</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Local contributors have helped establish these partnerships by introducing WordPress Credits to nearby schools and adapting it to local languages and educational settings. Mentors guide students through their first contributions, while sponsors provide support and resources. Educators help make that participation part of students’ academic work. Thank you to the students, educators, mentors, and supporters whose involvement has brought the program to more than 50 institutions.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Institutions can include WordPress Credits in an existing course, offer it as an internship, or incorporate it into a final project. The program is available at no cost to partner institutions, with flexible formats to suit their students and curriculum. To get started, read <a href=\"https://make.wordpress.org/community/handbook/education/credits/how-to-participate/institutions/\">how to launch a WordPress Credits program</a> and <a href=\"https://wordpress.org/education/credits/\">register your institution’s interest through the program page</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\"></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 09 Nov 2026 16:01:18 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:12:\"Isotta Peira\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:30;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:62:\"Open Channels FM: OCN on the Road at Open Source Summit Europe\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2566716\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:69:\"https://openchannels.fm/ocn-on-the-road-at-open-source-summit-europe/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:105:\"Hear how AlmaLinux OS Foundation is structured, engages users, and relies on sponsors with Benny Vasquez.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 09 Nov 2026 15:00:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:31;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:52:\"Open Channels FM: The Value of Blogging for Yourself\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2565719\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:59:\"https://openchannels.fm/the-value-of-blogging-for-yourself/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:178:\"Treat your blog as a personal space first: share thoughts, links, photos, and everyday moments without chasing engagement, building an enduring archive for reflection and growth.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 09 Nov 2026 11:06:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:32;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:61:\"Dave Smith: Using Claude to rebuild my website on…WordPress\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://aheadcreative.co.uk/?p=1325\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:84:\"https://aheadcreative.co.uk/articles/using-claude-to-rebuild-my-website-onwordpress/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:504:\"<p>This is the first post on my new website which is still proudly powered by WordPress. Yes, WordPress. I know it’s trending these days to talk about using Claude to build static sites with a markdown “database” and how that’s made your site better and faster. But guess what? This website is also built by Claude. And guess what? It’s fast. You know what else?</p>\n<p><a href=\"https://aheadcreative.co.uk/articles/using-claude-to-rebuild-my-website-onwordpress/\" rel=\"nofollow\">Source</a></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Sun, 08 Nov 2026 09:29:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:10:\"Dave Smith\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:33;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:135:\"Gutenberg Times: WordPress 7.1.4, Gutenberg 24.3, a new Studio workspace, WordPress for the Agentic Web, and more—Weekend Edition 379\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://gutenbergtimes.com/?p=47411\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:140:\"https://gutenbergtimes.com/wordpress-7-1-4-gutenberg-24-3-a-new-studio-workspace-wordpress-for-the-agentic-web-and-more-weekend-edition-379/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:32267:\"<p class=\"wp-block-paragraph\">Howdy,</p>\n\n\n\n<p class=\"wp-block-paragraph\">First things first: if you haven&#8217;t updated to <a href=\"https://wordpress.org/news/2026/10/wordpress-7-1-4/\"><strong>WordPress 7.1.4</strong></a>, do that before reading any further. The October 28 security release fixes more than a dozen issues, including a weakness in the upgrade process that could lead to remote code execution and stored XSS in several blocks and the Interactivity API. The fixes were backported all the way to the 4.7 branch, so don&#8217;t forget about those older sites you maintain.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Running a store? WooCommerce had a busy week, too. <a href=\"https://developer.woocommerce.com/2026/11/04/woocommerce-11-2-2-release-notes/\"><strong>WooCommerce 11.2.2</strong></a> is a security release with a database update, and there&#8217;s a separate <a href=\"https://developer.woocommerce.com/2026/11/03/security-update-for-woopayments/\"><strong>security update for WooPayments</strong></a> with a table of fixed versions for each release line.</p>\n\n\n\n<p class=\"wp-block-paragraph\">As for me, I&#8217;m just enjoying the autumn weather. It feels like we&#8217;ve finally shed off the days of summer heat in Alabama. And that means it&#8217;s fall festival season. I&#8217;ll see if I can find one or two to enjoy in the coming weeks.</p>\n\n\n\n<p class=\"wp-block-paragraph\">With that, let&#8217;s get down to the latest news.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Your friendly neighborhood developer advocate, <img alt=\"🍂\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f342.png\" style=\"height: 1em;\" /><br /><em>Justin Tadlock</em></p>\n\n\n<div class=\"wp-block-newsletterglue-showhide ng-block\" width=\"100%\">\n<div class=\"wp-block-group has-accent-5-background-color has-background has-global-padding is-layout-constrained wp-container-core-group-is-layout-b14348ac wp-block-group-is-layout-constrained\">\n<p class=\"wp-block-paragraph\"><strong>Table of Contents</strong></p>\n\n\n<nav class=\"wp-block-table-of-contents\"><ul><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#0-word-press-release-information\">Developing Gutenberg and WordPress</a><ul><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#getting-ready-for-wordpress-7-2\">Getting ready for WordPress 7.2</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#feature-notifications-get-a-design-and-some-pushback\">Feature Notifications get a design, and some pushback</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#prototypes-from-dave-on-wp\">Prototypes from Dave on WP</a></li></ul></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#0-p\">Plugins, Themes, and Tools for #nocode site builders and owners</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#2-word-press-6-0-1-and-6-1-scheduled\">Theme Development for Full Site Editing and Blocks</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#3-building-themes-for-fse-and-word-press\">Building Blocks and Tools for the Block editor.</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#what-s-new-in-playground\">What&#039;s new in Playground?</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#ai-in-wordpress\">AI in WordPress</a></li></ul></nav></div>\n</div>\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<h2 class=\"wp-block-heading\" id=\"0-word-press-release-information\">Developing Gutenberg and WordPress</h2>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 is one step closer. <strong>David Baumwald</strong> announced <a href=\"https://wordpress.org/news/2026/11/wordpress-7-2-beta-4/\"><strong>WordPress 7.2 Beta 4</strong></a> on November 3. Beta 3 shipped inside the 7.1.4 security release. This round continues the work on the Abilities API and DataViews extensibility, and it improves focus visibility in Windows High Contrast mode. Translation updates also show up individually on the Updates screen now, so you can choose which ones to install. <a href=\"https://wordpress.org/news/2026/10/wordpress-7-2-beta-2/\"><strong>Beta 2</strong></a> laid the groundwork for much of this, adding server-side registration for DataViews and DataForm and moving the admin to SVG icons.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The final release is still set for December 8. Spin up the <a href=\"https://playground.wordpress.net/release\">Beta 4 Playground instance to test</a>, or run <code>wp core update --version=7.2-beta4</code> on a staging site.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">Formatting no longer stops at the edge of a block. In <a href=\"https://make.wordpress.org/core/2026/11/02/whats-new-in-gutenberg-24-3-28-october/\"><strong>What&#8217;s new in Gutenberg 24.3</strong></a>, <strong>George Mamadashvili</strong> shows how you can now select text across several blocks and format all of it at once. Notes pick up emoji reactions, and the Media inserter moves onto the same DataViews component behind the Site Editor&#8217;s lists. Failed saves finally explain themselves, too, with a copy button for sharing the details. The release carries the security fixes from 7.1.4, so update the plugin if you run it. The 24.4 release candidate followed on November 3.</p>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"getting-ready-for-wordpress-7-2\"><strong>Getting ready for WordPress 7.2</strong></h3>\n\n\n\n<p class=\"wp-block-paragraph\">Dashicons are on their way out of the admin bar and menu. In WordPress 7.2, those icons are inline SVGs, and <strong>Ashar Fuadi</strong> explains <a href=\"https://make.wordpress.org/core/2026/11/05/svg-icons-in-the-admin-bar-and-menu-in-wordpress-7-2/\"><strong>what the SVG icon change means for plugins and themes</strong></a>. Most code needs nothing. But admin color schemes and anything that styles or hides icons through <code>::before</code> will need a small CSS update, and the post has before-and-after rules you can copy. There&#8217;s a new API, too: <code>add_menu_page()</code>, <code>register_post_type()</code>, and admin bar nodes now accept a registered icon name like <code>core-admin/pin</code>.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">Visit <code>/random/</code> on a 7.2 site, and you&#8217;ll land on a random published post. <strong>Aaron Jorbin</strong> details <a href=\"https://make.wordpress.org/core/2026/11/05/your-content-is-going-to-get-more-random/\"><strong>the new random content endpoint</strong></a>, which also works for categories, tags, authors, and custom post types. It&#8217;s on by default, with a new <code>randomable</code> argument for post types and a <code>wp_enable_random_content_redirect</code> filter to switch it off.</p>\n\n\n\n<p class=\"wp-block-paragraph\">It hasn&#8217;t landed quietly. Dozens of comments push back on the on-by-default choice, citing hidden content that could surface (Core still has no <code>noindex</code> option), <code>ORDER BY RAND()</code> load on large sites, and agencies now facing an must-use plugin across hundreds of sites. <strong>Matt Mullenweg</strong> has since agreed it shouldn&#8217;t use the page URL structure, so expect changes before 7.2 ships.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Anne McCarthy</strong> pulled several features still in development into one prototype for <a href=\"https://nomad.blog/2026/11/02/imagining-the-near-future-of-collaboration-in-wordpress/\"><strong>imagining the near future of collaboration in WordPress</strong></a>. It combines the 7.2 Notes features, suggestion mode, and the Presence API with a small workflow plugin that blocks publishing until every open note and suggestion is resolved. She purposely left real-time collaboration out to show how much works without it. She also shares the full prompt she used. Borrow it and build the demo yourself. Watch for an upcoming call for testing on suggestions.</p>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"feature-notifications-get-a-design-and-some-pushback\"><strong>Feature Notifications get a design, and some pushback</strong></h3>\n\n\n\n<p class=\"wp-block-paragraph\">Plugins have spent years shouting over each other with admin notices. <a href=\"https://make.wordpress.org/core/2026/10/29/exploring-a-design-for-feature-notifications/\"><strong>Exploring a design for Feature Notifications</strong></a>, from <strong>Poli Gilad</strong>, proposes a single notification bell on every admin screen, in the editor, and on the front of the site, with plugins sending data rather than layout. Existing admin notices keep working.</p>\n\n\n\n<figure class=\"wp-block-image size-full has-custom-border\"><img alt=\"Screenshot of proposed feature notifications dropdown with tabs for different types of notifications.\" class=\"has-border-color has-accent-6-border-color wp-image-47434\" height=\"1338\" src=\"https://i0.wp.com/gutenbergtimes.com/wp-content/uploads/2026/11/feature-notifications-proposal.webp?resize=1776%2C1338&#038;ssl=1\" style=\"border-width: 1px;\" width=\"1776\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">That last point drew the most criticism. <strong>Matt Mullenweg</strong> argued that the proposal does nothing about today&#8217;s notice spam and that the fix needs directory guidelines, enforcement, and incentives, not only a new interface. He backed <strong>David Perez&#8217;s</strong> suggestion that plugins declare each notice&#8217;s intent (operational, setup, or promotional) as a requirement.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">On the code side, <strong>Jonathan Bossenger&#8217;s</strong> <a href=\"https://make.wordpress.org/core/2026/11/01/wp-feature-notifications-weekly-update-2026-10-30/\"><strong>weekly update for October 30</strong></a> reports that the notification repository is now scoped per user, laying the groundwork for the REST API. Prefer to watch the work happen? His <a href=\"https://www.youtube.com/watch?v=Qt6zujtlBVk\"><strong>Friday live stream</strong></a> includes testing the plugin in Studio and the AI-assisted workflow he uses for reviewing PRs. He also holds office hours in the Feature Notifications Slack channel on Thursdays at 10:00 UTC.</p>\n\n\n<div class=\"wp-block-newsletterglue-showhide ng-block\" width=\"100%\">\n<figure class=\"wp-block-embed is-type-video is-provider-youtube wp-block-embed-youtube wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\n\n</div></figure>\n</div>\n\n\n<h3 class=\"wp-block-heading\" id=\"prototypes-from-dave-on-wp\"><strong>Prototypes from Dave on WP</strong></h3>\n\n\n\n<p class=\"wp-block-paragraph\">The block toolbar has picked up a lot of buttons over the years. <strong>Dave Smith</strong> asks <a href=\"https://www.youtube.com/watch?v=Hja-5ercQ-Q\"><strong>whether this is the end of the block toolbar</strong></a> and demos a consolidated version inside his Create Not Learn prototype editor. In about eight minutes, you&#8217;ll see how grouping those controls could make everyday formatting quicker and more consistent without giving up any of the editor&#8217;s power. The video description has a Playground link, so you can click around it yourself.</p>\n\n\n<div class=\"wp-block-newsletterglue-showhide ng-block\" width=\"100%\">\n<figure class=\"wp-block-embed is-type-video is-provider-youtube wp-block-embed-youtube wp-embed-aspect-4-3 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\n\n</div></figure>\n</div>\n\n\n<p class=\"wp-block-paragraph\">He also took a <a href=\"https://www.youtube.com/watch?v=nZNfuQSxyN0\"><strong>first look at drag-and-drop grid building</strong></a>, pulling Andrei Draganescu&#8217;s work-in-progress free-form grid into the same prototype. You can drag, resize, snap, and rotate blocks on a grid, and that demo has its own Playground link.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">Release roadmap posts have kept roughly the same shape for three years. <strong>Anne McCarthy</strong> wants to know whether they still work, and she&#8217;s asking everyone from Core committers and extenders to hosts and everyday users to <a href=\"https://make.wordpress.org/core/2026/10/26/release-roadmap-survey/\"><strong>help shape future release roadmaps</strong></a> by November 16.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"0-p\">Plugins, Themes, and Tools for #nocode site builders and owners</h2>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress Studio is now built around a conversation. <strong>Rich Tabor</strong> introduced <a href=\"https://wordpress.com/blog/2026/11/04/wordpress-studio-workspace/\"><strong>a new workspace for building with WordPress</strong></a>, where you describe the site you want and an AI agent builds a first version next to a live preview. It offers four looks, then four layouts, and saves your choices to a <code>DESIGN.md</code> file so later chats keep the same design. You can pin notes on the preview with Annotate, bring your own Anthropic API key, or connect Claude Code, Codex, or Cursor over MCP. It&#8217;s a free desktop app for macOS, Windows, and Linux.</p>\n\n\n\n<p class=\"wp-block-paragraph\">For a hands-on take, <strong>Elliott Richmond</strong> writes up <a href=\"https://elliottrichmond.co.uk/wordpress-studio-new-workspace-is-out-whats-changed-since-my-first-look/\"><strong>what&#8217;s changed since his first look</strong></a>, along with one fair caution: the agent can now edit your live site directly, so building locally first is still the safer habit. Rich also shared <a href=\"https://richtabor.com/studio/\"><strong>why he rebuilt Studio</strong></a> on his own blog, and <strong>Nick Diego</strong> recorded a <a href=\"https://x.com/nickmdiego/status/2118020671938900064\"><strong>quick video overview</strong></a> of the new design and agentic features.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">Stores running WooCommerce&#8217;s Purple theme are about to get more design control. In the <a href=\"https://developer.woocommerce.com/2026/10/26/woocommerce-11-3-pre-release/\"><strong>WooCommerce 11.3 pre-release post</strong></a>, <strong>Brian Coords</strong> highlights color, spacing, and border controls curated for each block, including Product, Featured Product, Featured Category, and Product Categories List. The On-Sale Badge block can show the discount as an amount, a percentage, or custom text, and Product Gallery swiping on mobile now follows your finger naturally. The beta is out now, with the final release scheduled for the week of November 9.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">Two new short tutorials from WordPress.com cover blocks you&#8217;ll use on nearly every site. The <a href=\"https://www.youtube.com/watch?v=Zi9r3kmfehI\"><strong>Columns block walkthrough</strong></a> builds grids, feature sections, and pricing tables, including column widths and stacking on mobile. </p>\n\n\n<div class=\"wp-block-newsletterglue-showhide ng-block\" width=\"100%\">\n<figure class=\"wp-block-embed is-type-video is-provider-youtube wp-block-embed-youtube wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\n\n</div></figure>\n</div>\n\n\n<p class=\"wp-block-paragraph\">The <a href=\"https://www.youtube.com/watch?v=p7H59fW4_U0\"><strong>Query Loop block video</strong></a> shows how to choose which posts appear, then sort and filter them, in about two minutes. Bookmark both for the next time a client asks how it&#8217;s done.</p>\n\n\n<div class=\"wp-block-newsletterglue-showhide ng-block\" width=\"100%\">\n<figure class=\"wp-block-embed is-type-video is-provider-youtube wp-block-embed-youtube wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\n\n</div></figure>\n</div>\n\n\n<h2 class=\"wp-block-heading\" id=\"2-word-press-6-0-1-and-6-1-scheduled\">Theme Development for Full Site Editing and Blocks</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Ipsum, the default theme shipping with WordPress 7.2, is easy to mistake for a simple theme. <strong>Carlo Daniele&#8217;s</strong> <a href=\"https://kinsta.com/blog/ipsum-wordpress-theme/\"><strong>dive into the Ipsum theme and how to extend it</strong></a> for Kinsta shows what&#8217;s underneath. Templates hand their layouts to hidden patterns, around 60 patterns ship with it, and the default text colors reach a WCAG AAA contrast ratio. </p>\n\n\n\n<p class=\"wp-block-paragraph\">My favorite detail is its use of the Block Bindings API: a comments call to action changes its text depending on whether the post already has comments.</p>\n\n\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"ng-block-8f088404065bde2f wp-block-newsletterglue-container ng-block\" style=\"color: #666666;\" width=\"100%\">\n<tbody>\n<tr>\n<td class=\"ng-block-vs ng-block-vs-1\" colspan=\"3\" height=\"0\" style=\"height: 0px;\"></td>\n</tr>\n<tr>\n<td class=\"ng-block-hs ng-block-hs-1\" height=\"0\" style=\"width: 0px;\"></td>\n<td align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 20px; padding-bottom: 20px; padding-left: 0px; padding-right: 0px; text-align: none; color: #666666; background-color: #fdfcea; border-radius: 12px;\">\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"wp-block-newsletterglue-text ng-block\" style=\"color: #666666;\" width=\"100%\">\n<tbody>\n<tr>\n<td align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 8px; padding-bottom: 10px; padding-left: 20px; padding-right: 20px; text-align: none; color: #666666;\">\n<p><strong> <a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/\" rel=\"noreferrer noopener\" target=\"_blank\">&#8220;Keeping up with Gutenberg &#8211; Index 2026&#8221;</a> </strong><br />A chronological list of the WordPress Make Blog posts from various teams involved in Gutenberg development: Design, Theme Review Team, Core Editor, Core JS, Core CSS, Test, and Meta team from Jan. 2024 on. Updated by yours truly. </p>\n</td>\n</tr>\n</tbody>\n</table>\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"wp-block-newsletterglue-text ng-block\" style=\"color: #666666;\" width=\"100%\">\n<tbody>\n<tr>\n<td align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 8px; padding-bottom: 10px; padding-left: 20px; padding-right: 20px; text-align: none; color: #666666;\">\n<p>The previous years are also available: <br /><strong><strong><a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/keeping-up-with-gutenberg-index-2020/\">2020</a> | <a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/keeping-up-with-gutenberg-index-2021/\">2021</a></strong> | <strong><a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/keeping-up-with-gutenberg-index-2022/\">2022</a></strong></strong> | <strong><a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/gutenberg-index-2023\">2023</a></strong> | <a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/gutenberg-index-2024/\"><strong>2024</strong></a> | <strong><a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/gutenberg-index-2025/\">2025</a></strong></p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n<td class=\"ng-block-hs ng-block-hs-2\" height=\"0\" style=\"width: 0px;\"></td>\n</tr>\n<tr>\n<td class=\"ng-block-vs ng-block-vs-2\" colspan=\"3\" height=\"0\" style=\"height: 0px;\"></td>\n</tr>\n</tbody>\n</table>\n\n\n<h2 class=\"wp-block-heading\" id=\"3-building-themes-for-fse-and-word-press\">Building Blocks and Tools for the Block editor.</h2>\n\n\n\n<p class=\"wp-block-paragraph\">PHPStan can&#8217;t check a call to a class it has never seen, so code that integrates with other WooCommerce extensions usually gets skipped or baselined. <strong>Ján Mikláš</strong> introduces <a href=\"https://developer.woocommerce.com/2026/11/03/php-stubs-for-extensions/\"><strong>automated PHP stubs for Woo extensions</strong></a>, a <code>woocommerce/php-stubs</code> package generated from extensions on the WooCommerce Marketplace and WordPress.org. The stubs are public on GitHub and Packagist. If your plugin or theme talks to other Woo extensions, you can check those calls without installing every extension in your analysis environment.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">WooCommerce 11.3 fixes a confusing count for stores that sell bundles. When an extension adds a product to the cart as part of a bundle, the Product Button says &#8220;1 in cart&#8221; even though the shopper never added it on its own. <strong>Luis Herranz</strong> explains <a href=\"https://developer.woocommerce.com/2026/10/27/cart-item-children/\"><strong>declaring parent-child cart item relationships</strong></a> through a new <code>woocommerce_store_api_cart_item_parent_item_key</code> filter and a <code>parent_item_key</code> field in the Store API. WooCommerce never marks items as children by itself, so it&#8217;s up to your extension to declare them. Today only the button count uses it, but the Cart and Mini-Cart blocks could someday nest child items under their parents.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"what-s-new-in-playground\"><strong>What&#8217;s new in Playground?</strong></h2>\n\n\n\n<p class=\"wp-block-paragraph\">You can now test changes on a copy of your real site without a local server. <strong>Fellyph Cintra</strong> details how to <a href=\"https://make.wordpress.org/playground/2026/11/04/clone-your-wordpress-site-in-playground-with-reprint/\"><strong>clone your WordPress site in Playground with Reprint</strong></a>. Install the Reprint plugin on your live site, authorize Playground with a migration key, and you&#8217;ll have an editable copy in your browser. Nothing you change there gets published to your live site. It&#8217;s handy for trying a design change, checking a plugin update, or tracking down a bug. Not ready to connect your own site? The post links to a public demo you can clone first.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">Playground&#8217;s building blocks aren&#8217;t only for WordPress anymore. In <a href=\"https://make.wordpress.org/playground/2026/10/23/joomla-playground-shared-php-tools-beyond-wordpress/\"><strong>Joomla Playground: shared PHP tools beyond WordPress</strong></a>, <strong>Fellyph Cintra</strong> looks at Herman Peeren&#8217;s community project, which runs Joomla in a browser tab on the same <code>@php-wasm</code> packages and <code>mysql-on-sqlite</code> library. The interesting part is what comes back to WordPress. A different CMS sends different queries and workloads through those shared tools, surfacing compatibility and performance issues both projects can fix.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"ai-in-wordpress\"><strong>AI in WordPress</strong></h2>\n\n\n\n<p class=\"wp-block-paragraph\">Imagine telling your AI agent, &#8220;Help me with my example.com site,&#8221; and it recognizes WordPress, asks you to authorize it, and gets to work. That&#8217;s the experience behind <a href=\"https://make.wordpress.org/ai/2026/10/28/wordpress-for-the-agentic-web/\"><strong>WordPress for the Agentic Web</strong></a>, the AI team&#8217;s plan from <strong>Jason Adams</strong>. It lays out four areas of work: a more reliable MCP Adapter that could move into Core, a baseline set of Abilities for common site tasks, OAuth so you don&#8217;t have to paste Application Passwords into an agent, and an end-to-end user experience tying them together. </p>\n\n\n\n<p class=\"wp-block-paragraph\">The 7.2 cycle lays the foundation, and 7.3 is the target. Each area still needs a lead, so now&#8217;s the time to raise your hand. Not everyone in the comments is sold on MCP-first, though. <strong>Adrian Mörchen</strong> argued that most agents already work fine over the REST API and that filling its gaps should come first, and Jason replied that Abilities serve both routes. The <a href=\"https://make.wordpress.org/ai/2026/11/02/ai-contributor-weekly-summary-28-october-2026/\"><strong>October 28 contributor summary</strong></a> covers the first discussion, with <strong>Tammie Lister</strong> volunteering to lead UX, and The Repository has <a href=\"https://www.therepository.email/wordpress-ai-team-lays-out-ambitious-four-part-plan-to-make-wordpress-agent-ready-by-7-3\"><strong>its own take on the plan</strong></a>.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">Six new experiments landed in <a href=\"https://make.wordpress.org/ai/2026/11/02/whats-new-in-ai-1-5-0/\"><strong>AI 1.5.0</strong></a>, the canonical AI plugin, and <strong>Jeffrey Paul</strong> breaks down each one. Text to Speech generates an audio version of a post, and Content Verification detects C2PA Content Credentials in uploaded images. MCP Access installs the MCP Adapter and adds a <strong>Tools → MCP Access</strong> screen where you decide which Abilities agents can see. The other three are WebMCP, Revision Change Summary, and Block Container Label Generation. If you&#8217;re following the Agentic Web work, MCP Access is the one to try first.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">Through the end of November, free WordPress.com sites can <a href=\"https://wordpress.com/blog/2026/11/03/free-chatgpt-claude/\"><strong>connect to ChatGPT or Claude at no cost</strong></a>. Full access normally comes with a paid plan. <strong>Alexa Peduzzi</strong> notes that both connections run on MCP, so after a one-time setup you can ask your AI to save a draft, clear out comments, or suggest what to fix this week. The post includes ready-made prompts that open in either tool. <em>Not interested?</em> Connecting is entirely optional, and a WordPress.com reply in the comments points to the separate <strong>Prevent third-party sharing</strong> setting for anyone worried about AI training on their content.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">AI prototypes that ignore the design system keep landing on designers&#8217; desks. In <a href=\"https://automattic.design/2026/10/27/working-towards-higher-quality-agentic-experiences/\"><strong>working towards higher-quality agentic experiences</strong></a>, <strong>@leilabyron</strong> shares the 13 best practices Automattic Design wrote for agentic interfaces, grouped under capturing intent, showing the work, and building trust. The guidance doesn&#8217;t stop at a list: an agentic-design-brief skill picks the practices that matter for a feature, and an AGENTS.md file gives coding agents explicit rules. One rule worth stealing: ask when the request is genuinely ambiguous, and don&#8217;t ask when the answer is already clear.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">What happens when an AI feature gives a wrong answer or lets a prompt injection slip through? At WordPress Day for AI Faro 2026, <strong>Ivelina Dimova</strong> shared how to use <a href=\"https://wordpress.tv/2026/10/28/ai-with-boundaries-implementing-guardrails-and-evals-in-wordpress/\"><strong>guardrails and evals for AI features in WordPress</strong></a> to test quality before anything reaches production. Anyone adding AI features to client sites should pair it with the Automattic Design post above. The slides are linked from the video page.</p>\n\n\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"ng-block-dbca74e552a6efc4 wp-block-newsletterglue-container ng-block\" style=\"color: #666666;\" width=\"100%\">\n<tbody>\n<tr>\n<td class=\"ng-block-vs ng-block-vs-1\" colspan=\"3\" height=\"0\" style=\"height: 0px;\"></td>\n</tr>\n<tr>\n<td class=\"ng-block-hs ng-block-hs-1\" height=\"0\" style=\"width: 0px;\"></td>\n<td align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 20px; padding-bottom: 20px; padding-left: 0px; padding-right: 0px; text-align: none; color: #666666; background-color: #f8f8f8; border-radius: 8px;\">\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"wp-block-newsletterglue-text ng-block\" style=\"color: #666666;\" width=\"100%\">\n<tbody>\n<tr>\n<td align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 8px; padding-bottom: 10px; padding-left: 20px; padding-right: 20px; text-align: none; color: #666666;\">\n<p><strong><a href=\"https://gutenbergtimes.com/need-a-zip-from-master/\">Need a plugin .zip from Gutenberg&#8217;s master branch?</a></strong><br />Gutenberg Times provides daily build for testing and review.</p>\n</td>\n</tr>\n</tbody>\n</table>\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"wp-block-newsletterglue-image ng-block size-full is-resized\" width=\"100%\">\n<tbody>\n<tr>\n<td align=\"center\" class=\"ng-block-td\" style=\"padding-top: 0px; padding-bottom: 0px; padding-left: 0px; padding-right: 0px;\"><a href=\"https://playground.wordpress.net/?blueprint-url=https://gutenbergtimes.com/wp-content/uploads/2020/11/playnightly.json\"><img alt=\"\" class=\"wp-image-42874 ng-image\" height=\"45\" src=\"https://i0.wp.com/gutenbergtimes.com/wp-content/uploads/2024/02/Screenshot-2025-11-15-at-12.06.44.png?resize=196%2C45&#038;ssl=1\" style=\"border-style: none; border-color: transparent;\" width=\"196\" /></a></td>\n</tr>\n</tbody>\n</table>\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"wp-block-newsletterglue-text ng-block\" style=\"color: #666666;\" width=\"100%\">\n<tbody>\n<tr>\n<td align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 8px; padding-bottom: 10px; padding-left: 20px; padding-right: 20px; text-align: none; color: #666666;\">\n<p>Now also available via <a href=\"https://playground.wordpress.net/?blueprint-url=https://gutenbergtimes.com/wp-content/uploads/2020/11/playnightly.json\">WordPress Playground</a>. There is no need for a test site locally or on a server. Have you been using it? <a href=\"mailto:pauli@gutenbergtimes.com\">Email me </a>with your experience.</p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n<td class=\"ng-block-hs ng-block-hs-2\" height=\"0\" style=\"width: 0px;\"></td>\n</tr>\n<tr>\n<td class=\"ng-block-vs ng-block-vs-2\" colspan=\"3\" height=\"0\" style=\"height: 0px;\"></td>\n</tr>\n</tbody>\n</table>\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide is-style-wide--1\" />\n\n\n\n<p class=\"has-text-align-center has-small-font-size wp-block-paragraph\"><em>Questions? Suggestions? Ideas? </em><br /><em>Don&#8217;t hesitate to send <a href=\"mailto:pauli@gutenbergtimes.com\">them via email</a> or</em><br /><em> send me a message on WordPress Slack or Twitter @bph</em>.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"has-text-align-center has-small-font-size wp-block-paragraph\">For questions to be answered on the <a href=\"http://gutenbergtimes.com/podcast\">Gutenberg Changelog</a>, <br />send them to <a href=\"mailto:changelog@gutenbergtimes.com\">changelog@gutenbergtimes.com</a></p>\n\n\n<div class=\"ng-block-784117bdf9394765 wp-block-newsletterglue-separator ng-block\" style=\"color: #666666;\" width=\"100%\"><div><div><div align=\"center\" class=\"ng-block-td\" style=\"padding-top: 20px; padding-bottom: 20px; padding-left: 20px; padding-right: 20px; color: #666666;\"><hr style=\"background-color: transparent; color: transparent; margin: 0; border: 0; border-top: 1px solid #666666; width: 560px; height: 0;\" /></div></div></div></div>\n\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide is-style-wide--2\" />\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Sat, 07 Nov 2026 17:45:24 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:14:\"Justin Tadlock\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:34;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:99:\"WordCamp Central: A Shoutout to Meahadi Hasan: From the Classroom to the Global WordPress Community\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:40:\"https://central.wordcamp.org/?p=16691960\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:123:\"https://central.wordcamp.org/news/2026/11/a-shoutout-to-meahadi-hasan-from-the-classroom-to-the-global-wordpress-community/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:12476:\"<p class=\"wp-block-paragraph\"><strong>Learning becomes more meaningful when students get the opportunity to put their knowledge into practice.</strong> For <a href=\"https://profiles.wordpress.org/meahadi/\" rel=\"noopener\" target=\"_blank\">Meahadi Hasan</a>, WordPress Credits opened the door to opportunities beyond website development. He explored photography contributions, participated in community initiatives like Campus Connect, and contributed to Bengali translations through the Polyglots and Training Teams, becoming an active part of the global WordPress community.</p>\n\n\n\n<div class=\"wp-block-columns is-layout-flex wp-container-core-columns-is-layout-8f761849 wp-block-columns-is-layout-flex\">\n<div class=\"wp-block-column is-vertically-aligned-center is-layout-flow wp-block-column-is-layout-flow\">\n<p class=\"wp-block-paragraph\">Meahadi is a final-year Computer Science and Engineering student at <a href=\"https://pundrauniversity.ac.bd/\" rel=\"noopener\" target=\"_blank\">Pundra University of Science &amp; Technology</a>, Bangladesh. He joined the WordPress Credits Program in August 2026 as part of his university&#8217;s Industrial Training (Internship) course. On 2 November 2026, he successfully completed the program, but his journey was about much more than earning a certificate.<br /></p>\n</div>\n\n\n\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\">\n<figure class=\"wp-block-image size-full\"><a href=\"https://central.wordcamp.org/files/2026/11/meahadi.png\"><img alt=\"\" class=\"wp-image-16691961\" height=\"224\" src=\"https://central.wordcamp.org/files/2026/11/meahadi.png\" width=\"224\" /></a></figure>\n</div>\n</div>\n\n\n\n<h2 class=\"wp-block-heading\"><strong>Rediscovering WordPress and Exploring New Opportunities</strong></h2>\n\n\n\n<p class=\"wp-block-paragraph\">Meahadi first encountered WordPress in 2020 through YouTube tutorials, where he learned to build a basic website. However, he didn&#8217;t continue working with it regularly.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Joining WordPress Credits gave him an opportunity to explore WordPress from a completely different perspective. He discovered that WordPress is not just a website-building platform; it is a global open-source community where people with different skills can contribute.</p>\n\n\n\n<p class=\"wp-block-paragraph\">He chose four contribution teams that matched his interests: Photos, Polyglots, Community and Training.</p>\n\n\n\n<h2 class=\"wp-block-heading\"><strong>66 Photographs and Contributions Beyond Development</strong></h2>\n\n\n\n<p class=\"wp-block-paragraph\">One of Meahadi&#8217;s most remarkable achievements was his contribution to the WordPress Photo Directory.</p>\n\n\n\n<p class=\"wp-block-paragraph\">He initially set a target of publishing 30 photographs. He went beyond that goal and successfully published <strong>66 original CC0-licensed photographs</strong>, featuring nature, plants, landscapes, and everyday scenes from Bangladesh.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>A Selection of Meahadi’s Photo Contributions</strong></p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-2 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><a href=\"https://central.wordcamp.org/files/2026/11/Fish-scaled.jpg\"><img alt=\"Fish\" class=\"wp-image-16691966\" height=\"1024\" src=\"https://central.wordcamp.org/files/2026/11/Fish-771x1024.jpg\" width=\"771\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://central.wordcamp.org/files/2026/11/flower-2-scaled.jpg\"><img alt=\"flower 2\" class=\"wp-image-16691967\" height=\"1024\" src=\"https://central.wordcamp.org/files/2026/11/flower-2-768x1024.jpg\" width=\"768\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://central.wordcamp.org/files/2026/11/flower-one-scaled.jpg\"><img alt=\"flower one\" class=\"wp-image-16691968\" height=\"1024\" src=\"https://central.wordcamp.org/files/2026/11/flower-one-768x1024.jpg\" width=\"768\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://central.wordcamp.org/files/2026/11/Nature-2-scaled.jpg\"><img alt=\"Nature 2\" class=\"wp-image-16691969\" height=\"1024\" src=\"https://central.wordcamp.org/files/2026/11/Nature-2-847x1024.jpg\" width=\"847\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://central.wordcamp.org/files/2026/11/Nature-3.jpg\"><img alt=\"Nature 3\" class=\"wp-image-16691970\" height=\"768\" src=\"https://central.wordcamp.org/files/2026/11/Nature-3-1024x768.jpg\" width=\"1024\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://central.wordcamp.org/files/2026/11/Nature-scaled.jpg\"><img alt=\"Nature\" class=\"wp-image-16691971\" height=\"1024\" src=\"https://central.wordcamp.org/files/2026/11/Nature-846x1024.jpg\" width=\"846\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://central.wordcamp.org/files/2026/11/brown-land-snail-edited-scaled.jpg\"><img alt=\"brown land snail\" class=\"wp-image-16691972\" height=\"1024\" src=\"https://central.wordcamp.org/files/2026/11/brown-land-snail-edited-927x1024.jpg\" width=\"927\" /></a></figure>\n</figure>\n\n\n\n<p class=\"has-text-align-center wp-block-paragraph\"><a href=\"https://wordpress.org/photos/author/meahadi/\" rel=\"noopener\" target=\"_blank\">Explore Meahadi&#8217;s Photo Directory contributions</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>His journey didn&#8217;t stop with photography. He also:</strong></p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Contributed Bengali translation suggestions through the Polyglots Team.</li>\n\n\n\n<li>Prepared a Bengali translation of the Learn WordPress lesson <em>The WordPress Ecosystem</em>, currently available for review.</li>\n\n\n\n<li>Built his personal website at <a href=\"https://meahadi.blog/\">meahadi.blog</a></li>\n\n\n\n<li>Participated in WordPress Slack, GitHub, and Make WordPress community discussions.</li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\">These experiences helped him understand how people with different skills collaborate to make WordPress better.</p>\n\n\n\n<h2 class=\"wp-block-heading\"><strong>Achievements</strong></h2>\n\n\n\n<div class=\"wp-block-columns has-white-color has-text-color has-link-color wp-elements-7 is-layout-flex wp-container-core-columns-is-layout-8f761849 wp-block-columns-is-layout-flex\">\n<div class=\"wp-block-column has-white-color has-text-color has-background has-link-color wp-elements-8 is-layout-flow wp-block-column-is-layout-flow\" style=\"background-color: #fff3cd;\">\n<div class=\"wp-block-group is-vertical is-content-justification-center is-layout-flex wp-container-core-group-is-layout-524f8de7 wp-block-group-is-layout-flex\">\n<div class=\"wp-block-spacer wp-container-content-c00f5982\" style=\"height: 0px;\"></div>\n\n\n\n<h3 class=\"wp-block-heading has-text-align-center has-white-color has-text-color has-link-color wp-elements-9\"><strong>60+</strong></h3>\n\n\n\n<p class=\"wp-block-paragraph\">Photos published</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>WordPress Photo Directory</strong></p>\n</div>\n</div>\n\n\n\n<div class=\"wp-block-column has-white-color has-text-color has-background has-link-color wp-elements-10 is-layout-flow wp-block-column-is-layout-flow\" style=\"background-color: #e8f5e9;\">\n<div class=\"wp-block-group is-vertical is-content-justification-center is-layout-flex wp-container-core-group-is-layout-524f8de7 wp-block-group-is-layout-flex\">\n<div class=\"wp-block-spacer wp-container-content-c00f5982\" style=\"height: 0px;\"></div>\n\n\n\n<h3 class=\"wp-block-heading has-text-align-center has-white-color has-text-color has-link-color wp-elements-11\"><strong>400+</strong></h3>\n\n\n\n<p class=\"wp-block-paragraph\">String Translated</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>WordPress Polyglots Team</strong></p>\n</div>\n</div>\n</div>\n\n\n\n<div class=\"wp-block-spacer\" style=\"height: 35px;\"></div>\n\n\n\n<div class=\"wp-block-columns has-white-color has-text-color has-link-color wp-elements-12 is-layout-flex wp-container-core-columns-is-layout-8f761849 wp-block-columns-is-layout-flex\">\n<div class=\"wp-block-column has-white-color has-text-color has-background has-link-color wp-elements-13 is-layout-flow wp-block-column-is-layout-flow\" style=\"background-color: #e3f2fd;\">\n<div class=\"wp-block-group is-vertical is-content-justification-center is-layout-flex wp-container-core-group-is-layout-524f8de7 wp-block-group-is-layout-flex\">\n<div class=\"wp-block-spacer wp-container-content-c00f5982\" style=\"height: 0px;\"></div>\n\n\n\n<h3 class=\"wp-block-heading has-text-align-center has-white-color has-text-color has-link-color wp-elements-14\"><strong>1</strong></h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress Lesson Translated</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>WordPress Training Team</strong></p>\n</div>\n</div>\n\n\n\n<div class=\"wp-block-column has-white-color has-text-color has-background has-link-color wp-elements-15 is-layout-flow wp-block-column-is-layout-flow\" style=\"background-color: #fce4ec;\">\n<div class=\"wp-block-group is-vertical is-content-justification-center is-layout-flex wp-container-core-group-is-layout-524f8de7 wp-block-group-is-layout-flex\">\n<div class=\"wp-block-spacer wp-container-content-c00f5982\" style=\"height: 0px;\"></div>\n\n\n\n<h3 class=\"wp-block-heading has-text-align-center has-white-color has-text-color has-link-color wp-elements-16\"><strong>1</strong></h3>\n\n\n\n<p class=\"wp-block-paragraph\">Portfolio Created</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>WordPress.Com</strong></p>\n</div>\n</div>\n</div>\n\n\n\n<div class=\"wp-block-spacer\" style=\"height: 35px;\"></div>\n\n\n\n<h2 class=\"wp-block-heading\"><strong>Learning Through Mentorship and Community</strong></h2>\n\n\n\n<p class=\"wp-block-paragraph\">Throughout the program, Meahadi received guidance from his assigned mentor, <strong><a href=\"https://profiles.wordpress.org/wprashed/\" rel=\"noopener\" target=\"_blank\">Rashed Hossain</a></strong>, who helped him navigate the learning process and contribution workflows.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong><a href=\"https://profiles.wordpress.org/devmuhib/\" rel=\"noopener\" target=\"_blank\">Muhibul Haque</a></strong> also shared useful resources and advice, particularly around the Training Team.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Through practical assignments, documentation, community discussions, and real contributions, Meahadi developed confidence in WordPress, translation workflows, documentation, and communicating with contributors.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Looking back on his experience, he shared that he previously viewed WordPress mainly as a platform for building websites. Now, he understands the many opportunities available within its global community, even beyond writing code.</p>\n\n\n\n<h2 class=\"wp-block-heading\"><strong>What&#8217;s Next?</strong></h2>\n\n\n\n<p class=\"wp-block-paragraph\">Completing WordPress Credits is not the end of Meahadi&#8217;s journey.</p>\n\n\n\n<p class=\"wp-block-paragraph\">He plans to continue contributing photographs, improve his Bengali translation skills, explore more Learn WordPress localization opportunities, and participate more actively in the WordPress community.</p>\n\n\n\n<p class=\"wp-block-paragraph\">His advice to future students is simple: start with a contribution team that matches your interests, read the handbooks, ask questions, and focus on small, consistent contributions.</p>\n\n\n\n<p class=\"wp-block-paragraph\">As he reminds us, the biggest value of WordPress Credits is not just completing a course; it&#8217;s becoming part of a community where your contributions can be genuinely useful.</p>\n\n\n\n<h2 class=\"wp-block-heading\"><strong>Celebrating More Than Course Completion</strong></h2>\n\n\n\n<p class=\"wp-block-paragraph\">Meahadi&#8217;s journey reflects what we hope to achieve through WordPress Credits: helping students move beyond theoretical learning, develop practical skills, discover their potential, and become active members of the global WordPress community.</p>\n\n\n\n<p class=\"wp-block-paragraph\">His story shows that you don&#8217;t have to be a developer to make a meaningful contribution. Whether through photography, translation, community, or development, there is a place for everyone in WordPress.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Congratulations, Meahadi, on completing WordPress Credits and making your mark in the WordPress community. This is just the beginning!</strong> <img alt=\"🎉\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f389.png\" style=\"height: 1em;\" /></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 06 Nov 2026 12:27:01 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:13:\"Muhibul Haque\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:35;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:46:\"Dave Smith: How AI-ready is WordPress in 2026?\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://aheadcreative.co.uk/?p=1364\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:71:\"https://aheadcreative.co.uk/articles/how-ai-ready-is-wordpress-in-2026/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:517:\"<p>It’s nearly the end of 2026 and I want to use my agent with WordPress already (like…yesterday)! To do this we need to understand exactly how “AI ready” WordPress is. This post outlines where things stand from my perspective and why I think it’s critically important for the future of the platform. Not yet, but it’s getting there quickly. This is what you can and can’t do today…</p>\n<p><a href=\"https://aheadcreative.co.uk/articles/how-ai-ready-is-wordpress-in-2026/\" rel=\"nofollow\">Source</a></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 06 Nov 2026 11:11:45 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:10:\"Dave Smith\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:36;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:81:\"Open Channels FM: The Work After the Easy Part, Open Channels News Week in Review\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2566647\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:87:\"https://openchannels.fm/the-work-after-the-easy-part-open-channels-news-week-in-review/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:281:\"This week’s Open Channels News covers actively exploited vulnerabilities, AI-driven coding and bug discovery, open-source funding pressures, workforce cuts, data-tax concerns, archival tools, and the continuing need for careful maintenance, verification, and sustainable support.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 06 Nov 2026 09:27:59 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"Open Channels FM\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:37;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:94:\"Open Channels FM: Who Should Pay When Technology Moves Faster Than the People Behind the Code?\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2566590\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:118:\"https://openchannels.fm/suse-cuts-jobs-as-ai-grows-e2e-fuels-open-source-testing-and-drupal-seeks-sustainable-support/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:134:\"SUSE navigates AI-driven job cuts, E2E gains traction in software validation, and Drupal weighs new approaches for shared maintenance.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 05 Nov 2026 14:27:40 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:38;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:51:\"Open Channels FM: The Lost Art of Exploring the Web\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2564534\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:58:\"https://openchannels.fm/the-lost-art-of-exploring-the-web/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:191:\"The internet once thrived on exploration and unique communities, but now it\'s dominated by algorithms. Reviving personal spaces and authentic connections can restore this spirit of discovery.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 05 Nov 2026 13:04:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"Open Channels FM\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:39;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:105:\"Open Channels FM: Web Summit Gender In Tech Report Reveals Gaps in Tech Leadership, Pay, and AI for Women\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2566458\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:110:\"https://openchannels.fm/web-summit-gender-in-tech-report-reveals-gaps-in-tech-leadership-pay-and-ai-for-women/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:141:\"Key takeaways from the Web Summit gender report on women’s experiences with pay, leadership, AI, and career decisions in technology fields.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 05 Nov 2026 11:04:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:40;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:86:\"Open Channels FM: Internet Reliability Tested Bugs Patching and the Value of Archiving\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2566530\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:132:\"https://openchannels.fm/postgres-faces-ai-discovered-bugs-ubuntu-critiqued-for-patching-and-ochaken-why-you-should-archive-websites/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:115:\"Postgres struggles with AI-found bugs, Ubuntu\'s patch speed is questioned, and a cherished web fan site disappears.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 04 Nov 2026 15:00:26 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:41;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:113:\"WPTavern: #240 – Martin Schmidt on Building Partnerships Between WordPress Product Makers and Hosting Companies\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:48:\"https://wptavern.com/?post_type=podcast&p=209574\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:128:\"https://wptavern.com/podcast/240-martin-schmidt-on-building-partnerships-between-wordpress-product-makers-and-hosting-companies/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:48384:\"<details>Transcript<div>\n<p class=\"wp-block-paragraph\">[00:00:19] <strong>Nathan Wrigley:</strong> Welcome to the Jukebox podcast from WP Tavern. My name is Nathan Wrigley.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Jukebox is a podcast which is dedicated to all things WordPress. The people, the events, the plugins, the blocks, the themes, and in this case, building partnerships between WordPress product makers and hosting companies.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you&#8217;d like to subscribe to the podcast, you can do that by searching for WP Tavern in your podcast player of choice, or by going to wptavern.com/feed/podcast, and you can copy that URL into most podcast players.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you have a topic that you&#8217;d like us to feature on the podcast, I&#8217;m keen to hear from you and hopefully get you, or your idea, featured on the show. Head to wptavern.com/contact/jukebox, and use the form there.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So on the podcast today we have Martin Schmidt.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Martin has been deeply involved in the WordPress and hosting industries since 2005 when he created his first WordPress travel blog while living in New Zealand. Over the years, he&#8217;s developed websites for small businesses, spent 13 years with IONOS in various management and strategy roles, and built partnerships at Wix, and a German SaaS company.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Most recently, Martin has focused on connecting WordPress plugin companies with web hosts, helping both sides unlock growth through smarter partnerships.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Today, the conversation focused on the often overlooked world of partnerships between plugin developers and hosting companies. Martin shares insights from his two decades of experience on why hosting providers are the perfect allies for WordPress product makers looking to grow, given their established relationships and marketing channels to large customer bases.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We talk about the curious fact that many plugin builders put enormous effort into their products, but stumble when it comes to sales, marketing, and building the business relationships necessary for broader success.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Martin discusses what hosting companies are actually looking for in a partnership, the technical and marketing preparations plugin makers should have ready, and why empathy and preparation make all the difference when trying to connect with busy product managers.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you&#8217;re a developer, freelancer, or agency owner interested in taking your WordPress product to the next level, or if you want a candid look at how partnerships really work in the open source ecosystem, this episode is for you.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you&#8217;re interested in finding out more, you can find all of the links in the show notes by heading to wptavern.com/podcast, where you&#8217;ll find all the other episodes as well.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And so without further delay, I bring you Martin Schmidt.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I am joined on the podcast by Martin Schmidt. Hello Martin.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:03:14] <strong>Martin Schmidt:</strong> Hi, Nathan. Great to be here.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:03:16] <strong>Nathan Wrigley:</strong> Yeah, thank you. Martin and I do not know one another, so this is our first call, but we were joined together, on maybe LinkedIn. I&#8217;m not entirely sure.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:03:23] <strong>Martin Schmidt:</strong> I was LinkedIn. Yeah. Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:03:25] <strong>Nathan Wrigley:</strong> Probably LinkedIn, by Nicole, so thank you to Nicole for doing that, really appreciate the linking together there. And we&#8217;re going to have a conversation today about, I suppose the word to describe it would be partnerships. How to partner with various different entities, possibly hosting companies are going to come up and things like that, so.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Before we begin that conversation, Martin are you able to just give us your little bio? Tell us a little bit about who you are and what you&#8217;ve done in the hosting partnership WordPress space, whatever you think fits best.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:03:55] <strong>Martin Schmidt:</strong> Yes, absolutely. I&#8217;m from Germany. I lived down south in Karlsruhe. Originally from the Cologne area. Started working with WordPress actually in I think 2005, something like that. When I was moving to New Zealand and started studying in New Zealand. That&#8217;s when I spun up my first WordPress site as a travel blog. And this was my first contact with WordPress. So I think, yeah, one of the, not one of the first users, but one of the very early.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:04:20] <strong>Nathan Wrigley:</strong> Fairly early, yeah, pretty early.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:04:22] <strong>Martin Schmidt:</strong> Very early. So that&#8217;s when you still had to like download WordPress and upload it via FTP, and there was no like auto update in the WordPress admin, and stuff like that. So one of the very early users and.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Yeah, around that time, that&#8217;s also how I got in touch with like the whole hosting industry. I was a web developer myself, started in high school developing websites for small businesses. Built them for people here in Germany and then also in New Zealand while I was studying over there.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And when I got back from New Zealand, I started applying for jobs. And one was with Google, the other one was with Ionos. And Ionos answered I think within a week, and I&#8217;m still waiting for the answer from Google till today. So, they never really got back to me, but yeah, it&#8217;s somewhere in the mail, yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But luckily the guys from Ionos got back to me and I think a week later I had a phone interview. Another four days later an interview in Karlsruhe. And then I started, I think two weeks later. Already started there like end of October with my first job as a product manager at Ionos.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And then spent 13 years at Ionos in various roles, in product management and the last five years in strategy. And from there I got the chance to move on to Wix. Worked for Wix.com in Germany. There was, during the COVID pandemic, I moved employers and started to work for Wix, and spent two years there building partnerships in, Europe.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Actually also put them in touch with a company called Sevdesk, which is a German accounting company, similar to Zero or QuickBooks Online. And couple of months later the CEO asked me if I was interested in joining their side, after they had raised some money and built partnerships from their side. I kept him waiting a little bit, but then after a while I decided, that&#8217;s interesting to join a German SaaS company. Something different than hosting, and online presence.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So yeah, I spent the next two years building the ecosystem around the SaaS software, like all the software that integrates with the accounting product basically.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Then end of 24, I got a call from my former boss from Ionos, who had just moved to hosting.com and became the CRO, and they also wanted to do partnerships. So, yeah, had a chat with him and with the CEO and started there in February 2025, and started building partnerships for hosting.com.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And, the main focus was really on building partnerships with WordPress companies. Just after Cloudfest, we launched the partnership with WP Rocket. Started to build quite a few more partnerships, or that were in the making. And by the end of the year, which was interesting to me, I had a lot of those WordPress plugin companies that I reached out to telling me, look, this is super interesting. We want to work with hosting companies.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We&#8217;re really glad to be working with you. We would also love to work with a lot of more hosting companies, but honestly we don&#8217;t really know where to start, and how to do this. And they really got me thinking. And then over New Years, and you know when you like, get some time to maybe reflect on the year and stuff that&#8217;s happening, this was like, it, really hit me. It&#8217;s like, well there&#8217;s so much interest of companies wanting to partner with web hosts.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And I&#8217;ve sat on the other side for some 20 years, like people pitching to me, like explaining me why their product is going to be the next big thing for me in the hosting company. And you start to see patterns of like things that people do good, and maybe things that people don&#8217;t do as well when like trying to pitch to you as a hosting company.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And I saw all this demand from these WordPress plugin companies and I was like, hey, maybe this is finally the idea of starting my own business. Like something I wanted to do for the last five years, but I never really had the idea of like what to do? Or not the idea that was convincing enough for myself to give up my corporate job.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And, once you got a house and family, I mean, it becomes a bit more difficult to just jump into the cold water, right? I guess a lot of people can relate to that. But this time it was different. I felt like this could really be something. So I started reaching out to more people in my network, and ask them, hey, I&#8217;m thinking about doing like this sort of consulting advisory thing. Do you think this is interesting? And I got a lot of positive feedback, way more than I had anticipated.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So I thought, okay, if I&#8217;m not doing this now, I will never do it. I will never try and do it. So yeah, I decided to go independent and officially started in May. And that&#8217;s what I&#8217;m doing now, like helping tech companies who want to partner with web hosts to find a way to do it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And I always tell people that are interested in, you can do it by yourself, right? You can find it all out yourself. It&#8217;s probably going to take you like three to four years to figure out the right model, and make all the connections. Build the trust with the hosting companies. Find out the right business model. The right support model, like the co-marketing activities, all the things you need to do. Or if you don&#8217;t want to wait for four years, you can work with me and I help you take a shortcut.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And the goal is by month six that you have someone in your organisation who can take care of partnerships, and just run this by yourself. But you don&#8217;t make all of those mistakes, and all of those extra investments that don&#8217;t turn into anything.</p>\n\n\n\n<p class=\"wp-block-paragraph\">My pitch to my customers is like, I&#8217;m helping you cut down the time to market. I&#8217;m telling you what works and what doesn&#8217;t work, and what makes a good pitch.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:09:49] <strong>Nathan Wrigley:</strong> Yeah, this is genuinely really interesting to me, and we&#8217;ll get into that a little bit later. But I have a different angle to you, but probably we&#8217;ll end up at exactly the same place.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I&#8217;ve been podcasting in the WordPress space for a decade. So 2016, something like that, I started. And, if you do podcasting often enough, your voice is heard, and people have this sort of expectation, if you send an email to me with a product that you&#8217;ve just launched, I will somehow have a silver bullet for making you successful.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And first thing to say is, I basically don&#8217;t. You know, I can put you on a podcast episode, but that really is the limits of what I can do.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But also what&#8217;s quite fascinating, and I honestly genuinely, I probably get about 30 or 40 of these emails a week. And the bit that stands out for me is how unprepared, let&#8217;s go for that word, how poorly prepared the email that I receive is.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So in many cases over the last couple of years, it&#8217;s clearly been written by an AI. There hasn&#8217;t been a lot of due diligence about who I am, so it kind of feels like this really, really cold call. I somehow got on an email list somehow. And it comes, you know, with all of the usual caveats. The first paragraph is telling me what I do, and I already know what I do. So like there was an AI in there somewhere.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But also it feels like they&#8217;ve got a product. Quite often I&#8217;ll go and look at the product and I think to myself, boy, that&#8217;s so good. Look at what they&#8217;ve done. Like they&#8217;ve built a plugin and it&#8217;s fulfilling a real need.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Unfortunately, I can&#8217;t really help them except put them on a podcast, but it occurs to me if only they could connect with all the right people, have the right language, know how to pitch themselves, know how their website should look so that it speaks to people that drop into it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">What I&#8217;m basically trying to build up a picture is of is that there&#8217;s loads of people out there who are building things, but clearly the building of it is the part that they&#8217;ve been interested in. And as soon as it&#8217;s built, they then have this moment of, oh, now what do I do with it? You know? And they don&#8217;t have that marketing expertise, and so they&#8217;re kind of looking around trying podcasters and what have you. And it feels like you are trying to step into that gap a little bit.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But instead of it being a podcast, you are trying to hook them up to what are the big players in the WordPress space? The people with deep pockets. The people who have reliable income month over month. And that&#8217;s the hosting companies. Have I summarised that correctly? Is that your experience as well? You get people that have got a thing, but don&#8217;t really know how to move on from the I&#8217;ve built the thing, to now I need to sell the thing.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:12:37] <strong>Martin Schmidt:</strong> Yes. So I think you&#8217;re spot on. And I would add there&#8217;s probably, I would say two groups. There&#8217;s the one which is maybe the builder who doesn&#8217;t know marketing, right? And we had these people before AI that were building fantastic products. But they just don&#8217;t know marketing because they&#8217;re fantastic builders. They&#8217;re tech people, but they&#8217;re missing that marketing piece.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And the one thing they don&#8217;t hire a marketing person who does it for them. I think that&#8217;s always a shame. You see this fantastic product, someone like driving a product with their passion. They&#8217;re really solving a pain point, but they just don&#8217;t understand how to sell it. Because to them it&#8217;s all clear, it&#8217;s all obvious, but you do need to translate it to people in your target audience.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So I think this is one group, and I see that also a lot with WordPress plugin companies. It feels like, coming from the hosting space, where all of the big companies are so good at marketing. Looking at WordPress companies, I feel like this is really something that they are somewhat missing.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I think the most successful WordPress plugin companies, I think that&#8217;s probably the ones that have understood that next to building fantastic product, and also needs fantastic marketing. But I think this is really the one group.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And the other one is, I would call them like lazy salespeople. They&#8217;re just sending out like sales messages. And we had them way before AI, just sending out without doing any research at all. You get messages and you look at them or you look at the product, it&#8217;s like, there&#8217;s no fit at all. I&#8217;m selling to small businesses, and you pitching me a product for enterprise customers. Like, why? You are just wasting time, right?</p>\n\n\n\n<p class=\"wp-block-paragraph\">If your goal is to work with a company to potentially sell to hundred, thousands, or millions of customers, and that&#8217;s going to be a deal worth hundred thousands or millions of dollars, you should invest maybe an hour, half an hour, of research and just see if there&#8217;s any fit at all right. And then if you take the time to go in a meeting with me and pitch your product, do a little bit of research to just make it fit. Just this tiny bit of research will make you stand out amongst the crowd like completely.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:14:41] <strong>Nathan Wrigley:</strong> It feels to me in the first case as if, timing&#8217;s not really the right word, but there&#8217;s a component of timing in here. And what I&#8217;m meaning by that is, what I&#8217;m feeling is that a lot of people have spent all of their time building the thing. So that might be time, but it might be money, whatever the thing that you&#8217;ve got going on in your business.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But at no point during the time from conception, idea to completed product have they said to themselves, okay, at some point we&#8217;re going to have to market this. We&#8217;re going to have to think about it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So maybe, and I don&#8217;t know if this is part of the sort of wisdom that you have, but it feels like maybe halfway through that process of build to complete build, you need to put the brakes on and say, okay, now we&#8217;re halfway through, let&#8217;s work in two channels now. Let&#8217;s do the, finish the build, but also at the same time, let&#8217;s do the marketing.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So I don&#8217;t know if there&#8217;s anything in there, like just put on the brakes before you finish, have some resources, have some ideas of contacts, have some marketing, have a website and all of that kind of stuff done. So that when you finish, it&#8217;s all ready to roll.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:15:43] <strong>Martin Schmidt:</strong> Yes. That&#8217;s definitely it. I don&#8217;t know if you have to put on the brakes, but I think it&#8217;s like, at least you as the CEO, you have to like work on two tracks. There&#8217;s the guys building the product, but then there&#8217;s also the marketing piece of it, right?</p>\n\n\n\n<p class=\"wp-block-paragraph\">And you can have the most fantastic product if you&#8217;re not telling the story, if you&#8217;re not letting the world know. How are people going to find you, right? I think we see, I saw a stat on LinkedIn recently that there&#8217;s like a thousand plugins published on the repository every week. It&#8217;s going to be so crowded. You need to do something to stand out and to be found.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And I think that&#8217;s also with web hosts and every tech company, you can have the most amazing product, but if you&#8217;re not found, if the target audience doesn&#8217;t know about you, nobody will use your product. And you&#8217;re going to be the only user of your own product.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I think in the end, you need to master marketing to be successful with your business. And it&#8217;s not just about the best product. And, I think that&#8217;s the important message here. You don&#8217;t need to know marketing yourself. Just hire someone. There&#8217;s so many people specialise in marketing. Just get someone on board who knows marketing and who understands a little bit of tech to get why your product is so special, and who&#8217;s able to translate that into a customer pain point, and figure out how to sell it. that&#8217;s really it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:16:58] <strong>Nathan Wrigley:</strong> So we&#8217;ve done podcast episodes on this podcast before where we&#8217;ve talked about partnerships in a different way. We&#8217;ve talked about partnerships in terms of plugin Company A joining with plugin Company B, because they&#8217;ve got similar enough products that they kind of overlap, and they can help each other out and mutually market and do marketing campaigns together and things like that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But that&#8217;s not what we&#8217;re talking about here. We&#8217;re talking specifically about going to hosting companies. So I guess the first question is, why go to hosting companies? What is it that they bring? I suppose the obvious answer is they&#8217;ve got bajillions of customers. In many cases, you know, some of the big hosts, if you can forge some sort of relationship with them, goodness knows, you know, maybe they literally have millions of customers. But why have you made hosting companies the bit of the half of this jigsaw puzzle?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:17:45] <strong>Martin Schmidt:</strong> Yes. beside me coming from hosting and knowing hosting, which was kind of like, make it a bit easy to decide for hosters. But I think they also play an important role. In the end, if a small business wants to run a website, they need to host it somewhere. They decide for hosting company. They get their WordPress site spun up. And then, that&#8217;s where usually in the next step you would go with like certain plugins. Like for SEO, performance, backup, security, translations, whatever your use case is, right?</p>\n\n\n\n<p class=\"wp-block-paragraph\">As you mentioned, the hosting company is the one that has all of the relationships with the customers. And unlike the WordPress companies, who are not allowed by the repository rules to directly market to their customers via email and things like that, they can only use popups inside the WordPress admin.</p>\n\n\n\n<p class=\"wp-block-paragraph\">One thing that the host is free to do, they can call the customers, they can send text messages, they can send them emails. They can do all of the up and cross sell marketing to their customers. And I think that&#8217;s one advantage that the hoster has that they can bring to the table, beside all of these customer relationships, right? They can really do the full blown marketing to those free users, to push a premium version of the plugin.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:18:59] <strong>Nathan Wrigley:</strong> Okay. So it&#8217;s not just visibility within the platform of, I don&#8217;t know, you&#8217;re at the point of it installing a plugin because you&#8217;ve got a brand new WordPress website. And look, here&#8217;s a bunch of partners that we&#8217;ve got, you may be interested in those.</p>\n\n\n\n<p class=\"wp-block-paragraph\">That&#8217;s one piece of it. But there&#8217;s also this sort of marketing side. Presumably just like every company on earth, web hosting companies are as keen to keep front of mind as any other company. So if they can come up with a good, and I&#8217;m doing air quotes, excuse to send out an email, they&#8217;ll do that. And why not send out an email because we&#8217;ve onboarded a new partner and, you know, have you thought about doing this with your website? It turns out we&#8217;ve got a partnership with this particular plugin company.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I&#8217;m guessing there that the ability to send out emails is something, you know, to keep front of mind is something that the web host would want to do. But what&#8217;s in it for the web host? Like if I was a plugin company coming to a web host, I would want to have in my mind, okay, these are the kind of things I know they&#8217;re looking for. What are they, what do the web hosts want in return?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:19:55] <strong>Martin Schmidt:</strong> Yeah. So a lot of web host will tell you, hey, I want new customers, and that&#8217;s what I usually tell the web hosts. This is something you can&#8217;t expect from the WordPress plugin company. Because they are like in the later stage of that decision process. So the customer decides for the plugin a lot later than they decide for the host. So it&#8217;s not fair to ask the plugin company to bring in new customers to the web host.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But what they can do and what the WordPress plugin company can help with is, A, make the product a lot more attractive. They&#8217;re web hosts that sell hosting bundled in with plugins like WP Rocket. So the product itself is more attractive from the get go.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And if you don&#8217;t bundle it in the start, you can also help solve certain customer pains that make the customer more happy, therefore more sticky, right? So you prevent churn. As a host, you reach like a hundred thousand, 200,000 customers. You really need to work hard that your new customer growth isn&#8217;t eaten up all by churn. Making your customers sticky and drive up the revenue per customer, that&#8217;s in the interest of the web host, right? And, with a certain size, increasing that revenue per customer also becomes very important and interesting for the web host.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So I think that&#8217;s where the plugin company can come in and help the web host. They won&#8217;t just partner with any plugin. The plugin needs to solve a certain pain point for the customer. So this could be performance, this could be SEO, this could be accessibility. So these are challenges that the customers of the web host are actually faced with. And the plugin is simply a solution to that pain point.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So the hoster has an answer to that question of their customer. They&#8217;re in the role of the trusted advisor to their customers. And if the customer says, look, I&#8217;m running a website on your servers. I need to now be in compliance with the accessibility requirements in my country, or I need to do certain things. Then there&#8217;s the answer. Let&#8217;s use WP Rocket for performance. Here&#8217;s a partnership that we have with them, right? And that&#8217;s where the plugin company can come in and help the host.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Beyond that, obviously joint co-marketing will also help the hoster. And obviously if you talk like Ionos, GoDaddy or Newfold, I mean they&#8217;re massive, like they have millions of customers. So probably what a plugin company can bring to help them in co-marketing is not going to make a huge impact. There&#8217;s hundreds of hosters with hundred thousands of customers. For them working with one of those plugin companies can still be very interesting in doing like joint co-marketing, and getting the word out.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:22:32] <strong>Nathan Wrigley:</strong> That&#8217;s interesting. In the back of my head, when we were talking until just now, for some reason I was thinking about all the big hosts. You know, the ones that you&#8217;ve all heard of with the millions of customers. But of course that&#8217;s not the case, is it? There are thousands of smaller hosts.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:22:47] <strong>Martin Schmidt:</strong> Yes.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:22:48] <strong>Nathan Wrigley:</strong> Who may be more amenable to this kind of thing because, well, Idon&#8217;t know, they just don&#8217;t have that sort of scale that they need to worry about. And, you know, they&#8217;re looking for opportunities because they themselves are looking to grow in different ways that perhaps the other big hosts don&#8217;t have to think about quite so much.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Okay. So that&#8217;s interesting. So, you know, if it doesn&#8217;t fit one hosting company and you get a silent wall from all the big ones, that doesn&#8217;t mean you&#8217;re out of the game. It may be that the smaller hosts with different staff, and a different approach, and different geography and things like that, they may be more amenable to that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:23:21] <strong>Martin Schmidt:</strong> Yes, absolutely. And I will always tell my clients, I know that GoDaddy, Ionos and Newfold look very interesting because their publications, that they have millions of customers, but you don&#8217;t want to start with them. It&#8217;s going to take you three or four years to get a deal done if at all. If you start with them, I mean you&#8217;re going to give up frustrated halfway through probably.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So start with the smaller guys. They&#8217;re more approachable, right? They may be less busy. You mentioned that you get like 30 emails a week. That&#8217;s what the everyday of a product manager at an Ionos or GoDaddy looks like as well. They get pitches all the time. Getting some air time with them is nearly impossible.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Start with the smaller guys and they&#8217;re going to be a lot more open to discuss with you. And start some smaller partnerships. Work through the teething problems of partnerships with bigger companies, right? Build some track record. And once you&#8217;ve established a track record, you can work your way up, right? Every hoster has a competitor that&#8217;s bigger and one that&#8217;s smaller. Once the smaller competitor starts doing something, they will notice, and they will look like, why are these guys partnering with plugin company XYZ? Should we be doing the same? So you kind of like work your way up to the bigger guys and the bigger guys, right?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:24:34] <strong>Nathan Wrigley:</strong> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:24:35] <strong>Martin Schmidt:</strong> Everyone is watching the other guys and watch what they do. So it&#8217;s, once you start working with some of them, the rest will start like, oh, this is interesting. If X, Y, Z worked with them, maybe we should too. That&#8217;s how you build the traction, but you need someone to start, right? And that&#8217;s probably not going to be the biggest guy.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:24:53] <strong>Nathan Wrigley:</strong> Yeah, and again, I hadn&#8217;t really thought about that, but yeah, the, sort of looking over your shoulder if you&#8217;re a hosting company, seeing with perhaps jealous eyes, oh look, they&#8217;re getting loads of attention out there on social media because they&#8217;ve formed this relationship. And their emails are going out, and people are making comments on their tweets and their blog posts and things like that. Oh, we should definitely get a bit of that. Okay. That&#8217;s, really interesting.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So if somebody approaches you, then let&#8217;s say they&#8217;ve got a plugin. Let&#8217;s just assume that it&#8217;s a plugin that is useful and that a hosting company would be interested in it, if they had everything wrapped up correctly. What would be some wisdom that you would drop in terms of how to wrap it up? Like, how prepared do you need to be? What are the kind of things that you expect plugin developers to have ready, so that on day one, when you do your first outreach to the first hosting company, you feel confident that, okay, I&#8217;ve got a good client here, we&#8217;ve got a good chance. What are the bits and pieces that you need to have them have done?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:25:50] <strong>Martin Schmidt:</strong> I think on the technical side, I mean they will need to have some sort of like provisioning enabled. The host would probably want to sell the plugin themselves within their billing engine, and their system. So they will need some sort of provisioning to your system to say look, someone bought a licence and this licence needs to be valid and stuff like that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So, this integration and that usually, I mean, if you don&#8217;t have that, it probably takes you a few months to implement that. So that&#8217;s something like, I would really start first and built these kind of things.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The other stuff that I think the plugin company should have ready is, what&#8217;s your proposition to the web host? And what&#8217;s the proposition of your product to the web host customers? I always tell my clients like, don&#8217;t make the other guys think. Tell them. Show them that you thought about it. Coming back to our earlier point about people being unprepared, don&#8217;t be that unprepared person. Like once you get some air time with these guys, tell them what your product is. Tell them what your product, or your company can do for the web host. But also tell them how they should be using your product and marketed to their customers.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:26:56] <strong>Nathan Wrigley:</strong> Kind of spoonfeed them basically.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:26:58] <strong>Martin Schmidt:</strong> Yes.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:26:59] <strong>Nathan Wrigley:</strong> Have everything so that they can lift it and just walk off with it and, okay, we&#8217;ll do that then.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:27:03] <strong>Martin Schmidt:</strong> Yes. It might feel like spoonfeeding and like, why do I need to do your job? But I mean, in the end, put yourself in the shoes of that product manager, and tell them, look, if I was you, I would be selling my product this and this way.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Some of the worst product pitches I had. Companies came to me. Told me look, this is our product. You&#8217;re going to make millions with it. And then I was like, okay, that&#8217;s interesting. How do I sell it to my customer? And then the answer was like, I don&#8217;t know your customers. You need to know how to sell stuff to your customer. It&#8217;s like, that&#8217;s not how you land a deal, right?</p>\n\n\n\n<p class=\"wp-block-paragraph\">And one thing I like to do when I was pitching products. I looked at the website of the company I was pitching to. I mocked up their website with my product, and I put that in my presentation, and I told them, look sorry guys, we already hacked your website. Our product is already on your website. This is what it&#8217;s going to looks like. This is what it&#8217;s sold for, right? It shows them that you put some thought into that. That&#8217;s going to make you stand out.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Understand the work life of that product manager. They get those 30 emails like you, do. They decide to go on that meeting with you. You spend 30 minute pitching your product, and then you leave them with this big question mark. Like okay, this sounds interesting, but how the heck do I sell this to my customers?</p>\n\n\n\n<p class=\"wp-block-paragraph\">After your meeting then they have lunch, then there&#8217;s like an escalation, then there&#8217;s an all hands, then there&#8217;s the weekend. On the next Monday they will have almost forgotten about you. And if they think about you it&#8217;s, oh, I still have to figure out how to sell this. This is complicated. I don&#8217;t have time for this. I&#8217;m going to postpone it. And that&#8217;s not what you want to achieve.</p>\n\n\n\n<p class=\"wp-block-paragraph\">You want them to go out of that meeting and thinking, well this is an amazing product, solves a problem for my customers. And these partners, they think about me. They think about how I should be selling it. And maybe it&#8217;s not a hundred percent right. It&#8217;s not about getting it a hundred percent right.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:28:51] <strong>Nathan Wrigley:</strong> Right. They can adapt.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:28:52] <strong>Martin Schmidt:</strong> Yes. But giving them something to adapt is like a lot more than just don&#8217;t give them anything, right. And adapting is always easier than coming up with it yourself.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:29:01] <strong>Nathan Wrigley:</strong> So, the email that I typically get is basically a description of a product. It tells me what it&#8217;s called and then what it does. And often it&#8217;s a fairly technical description of a product. And, I imagine that if you are a marketer, you&#8217;re four lines into that email and your eyes have glazed over, and it&#8217;s like, okay great.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But what you are describing is go the extra mile. Don&#8217;t just explain the product. Presumably, there&#8217;s a bit of that&#8217;s got to go on, but it&#8217;s also now explain to the person receiving that email how their company can use that. How they could market it. The way that could be marketed. The sort of mockup landing page that you described just there. Go the extra mile, sit in their seat for a minute. Try to imagine what their busy life is like, have a bit of empathy, and imagine that they&#8217;ve only got an attention span of a few moments. It&#8217;s more that, than the here&#8217;s a product description. Now that you know what it is, please come and contact us, because that&#8217;s just not going to happen.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:29:59] <strong>Martin Schmidt:</strong> No, it&#8217;s not. I think it&#8217;s the same for us in private life. If you get emails about products that. I mean you just know yourself. You&#8217;re busy with so many things in between. Your kids coming home from school, and someone calling, your parents calling and all of that. You, just look at the email and if it doesn&#8217;t click immediately, it goes to the trash bin.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And it&#8217;s the same with these guys as well. Convincing people just in email is probably going to be difficult. You need to at least get them into the meeting. And I think that&#8217;s the one step before that. But once you have them in a meeting, spend that time wisely. It&#8217;s difficult enough to get them into the meeting. But if you have them in a meeting, don&#8217;t waste it with generic presentations.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Invest this little bit of effort, and mocking up that websites or just taking a bit of a look at who they&#8217;re selling to and adapting your message to that. It doesn&#8217;t take a ton of work. And it didn&#8217;t take a tonne of work four or five years ago. And now with AI it&#8217;s even less, it&#8217;s even less work, right? But if you want me to trust you as my partner to go forward and sell to my customers, that&#8217;s going to blame me for everything. I want to see that you invest a little bit of effort too.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:31:04] <strong>Nathan Wrigley:</strong> I think that&#8217;s right. Yeah. I think that&#8217;s a very human characteristic, isn&#8217;t it? I would like to see that you made an effort, if I&#8217;m going to make an effort. That&#8217;s just how the game goes, right? That&#8217;s just how it is. You know, if I get the impression that you just want to rock up, make loads of money, and do nothing, that&#8217;s never going to work really.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:31:25] <strong>Martin Schmidt:</strong> No.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:31:26] <strong>Nathan Wrigley:</strong> I mean there&#8217;s the occasional person that manages to pull that off, but on the whole, that&#8217;s not how human relationships flourish and work.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:31:33] <strong>Martin Schmidt:</strong> In the end, it&#8217;s about you want to build a partnership, right? And that&#8217;s not, I come to you and you give me loads of money. I don&#8217;t have a lot of friends like that. And I don&#8217;t think anyone else has a lots of friends like that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Usually it&#8217;s like you give and you receive, right? And sometimes one side invests a bit more, and the other side invests a bit more. But usually if only one side is giving and the other one is only taking, that&#8217;s a toxic relationship. And usually they tend to break. So why should business relationships work any differently?</p>\n\n\n\n<p class=\"wp-block-paragraph\">But it&#8217;s a funny conception that a lot of companies have is oh, I want to do partnerships. I just go out there and then they&#8217;re going to sell my product and I&#8217;m going to make lots of money, and I don&#8217;t need to do anything. That&#8217;s honestly what a lot of companies think.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And that&#8217;s the difficulty that a lot of partner managers have, right? They&#8217;re being sent out to get those partners, and then they&#8217;re expected to bring in just all the revenue without any additional investment. And that&#8217;s just not happening. Honest truth, nobody is out there waiting for you and for your product.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:32:32] <strong>Nathan Wrigley:</strong> Yeah. That is the brutal truth isn&#8217;t it? Do you subscribe to doing things in person? You know, so WordPress has got a real panoply of events, Meetups and WordCamps and there&#8217;s obviously other things that you mentioned, you know, Cloudfest and things like that. Do you find that tends to short circuit things?</p>\n\n\n\n<p class=\"wp-block-paragraph\">I guess there&#8217;s a bit of personality that comes into this as well. You know, some people are, seem to have all the characteristics for selling. They&#8217;re incredibly good at that kind of thing. Maybe they&#8217;re practised at it. Maybe they&#8217;re just, you know, born in that wonderful manner. Do you subscribe to that? Is that a part of this jigsaw puzzle as well? You know, show up, meet the people, shake the hands, go to the restaurants, do the schmoozing and all of that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:33:12] <strong>Martin Schmidt:</strong> Absolutely. You could do all the Zoom calls that you want, but I&#8217;ve experienced it firsthand. Like during COVID, we were talking to people for six months via video conference. Like one in person meeting in Munich. It felt like this moved us further than just the six months of constant video calls.</p>\n\n\n\n<p class=\"wp-block-paragraph\">You can meet people, and you can relate to them, and there can be some sympathy and stuff like that. And you might not have to meet ever, but it usually helps a lot to build that trust. To just meet the person face to face, shake a hand, maybe have a beer and have a laugh and stuff like that just helps a great deal.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And I&#8217;ve seen partnerships without any face-to-face meeting, but usually I would definitely advise to see people in person. And some people are just difficult to get hold of. And then catching them at the Colosseum Bar at Cloudfest 10 o&#8217;clock at night really helps to suddenly be in touch with that person.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:34:07] <strong>Nathan Wrigley:</strong> There is something ever so human about that isn&#8217;t there? And I think we all on some level enjoy that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So you found yourself in this product market space. Like I said, I know that this is a thing. So I would imagine that given a fair wind, you&#8217;ll be doing this for years to come.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Where do you find yourself online? Do you have a website where you&#8217;ve packaged up these products and services, you know, these partnership liaison services that you do? Where can people find you? Where do they go online to discover more about you?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:34:37] <strong>Martin Schmidt:</strong> At the moment mostly active on LinkedIn. That&#8217;s where I meet a lot of the people. I also have a website, martinschmidt.co. And that&#8217;s where also people can reach out to me. The website has been a little bit neglected to be quite fair because I straight on, jumped into LinkedIn and started publishing on LinkedIn, because the audience is already there. And people are not searching for how do I build partnerships with web hosts? But they come to me via LinkedIn because they tend to read some of my posts, and that&#8217;s how I get to speak to people like yourself.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:35:07] <strong>Nathan Wrigley:</strong> Yeah. Well, that is exactly how it happened. It was LinkedIn and I think you&#8217;re right. I think having a website would be of great value, but at the same time, you know, given the proclivities of what you&#8217;re doing, LinkedIn seems to be very much the best place to do that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">What I&#8217;ll do is I will put your bits and pieces into the show notes. So if dear listener, you head to wptavern.com you search for the episode with Martin Schmidt, that&#8217;s S-C-H-M-I-D-T, you&#8217;ll be able to find the links there. So hopefully you&#8217;ll be able to contact Martin via LinkedIn and what have you.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Really interesting topic and Martin, thank you for chatting to me about it today.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:35:42] <strong>Martin Schmidt:</strong> Yes. Thanks for having me, Nathan. It was fantastic.</p>\n</div></details>\n\n\n\n<p class=\"wp-block-paragraph\">On the podcast today we have <a href=\"https://www.martinschmidt.co\">Martin Schmidt</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Martin has been deeply involved in the WordPress and hosting industries since 2005, when he created his first WordPress travel blog while living in New Zealand. Over the years, he’s developed websites for small businesses, spent 13 years with IONOS in various management and strategy roles, and built partnerships at Wix and a German SaaS company. Most recently, Martin has focused on connecting WordPress plugin companies with web hosts, helping both sides unlock growth through smarter partnerships.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Today the conversation focused on the often-overlooked world of partnerships between plugin developers and hosting companies. Martin shares insights from his two decades of experience on why hosting providers are the perfect allies for WordPress product makers looking to grow, given their established relationships and marketing channels to large customer bases.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We talk about the curious fact that many plugin builders put enormous effort into their products, but stumble when it comes to sales, marketing, and building the business relationships necessary for broader success.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Martin discusses what hosting companies are actually looking for in a partnership, the technical and marketing preparations plugin makers should have ready, and why empathy and preparation make all the difference when trying to connect with busy product managers.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you’re a developer, freelancer, or agency owner interested in taking your WordPress product to the next level, or if you want a candid look at how partnerships really work in the open source ecosystem, this episode is for you.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Useful links</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://www.martinschmidt.co\">Martin&#8217;s website</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://www.ionos.com\">IONOS</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://hosting.com\">Hosting.com</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://wp-rocket.me\">WP Rocket</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://www.linkedin.com/in/martinschm/\">Martin on LinkedIn</a></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 04 Nov 2026 13:00:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:14:\"Nathan Wrigley\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:42;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:61:\"Open Channels FM: The Human Hurdle in Automated Cybersecurity\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2566451\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:68:\"https://openchannels.fm/the-human-hurdle-in-automated-cybersecurity/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:371:\"As artificial intelligence takes a more prominent role in cybersecurity, organizations face a growing challenge: the speed at which AI can discover vulnerabilities far outpaces human capacity to address them. Some news here on our podcast shines a light on how automation is transforming not just how vulnerabilities are identified, but how trust, autonomy, and [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 04 Nov 2026 10:34:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"Open Channels FM\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:43;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:40:\"WordPress.org blog: WordPress 7.2 Beta 4\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://wordpress.org/news/?p=21907\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:56:\"https://wordpress.org/news/2026/11/wordpress-7-2-beta-4/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:7749:\"<p class=\"wp-block-paragraph\">WordPress 7.2 Beta 4 is ready for download and testing!</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>This beta release is intended for testing and development</strong> only. Please do not install, run, or test this version of WordPress on production or mission-critical websites. Instead, use a test environment or local site to explore the new features.</p>\n\n\n\n<h3 class=\"wp-block-heading\">Wait, what happened to 7.2 Beta 3???</h3>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://wordpress.org/news/2026/10/wordpress-7-1-4/\">WordPress 7.1.4 was released on October 28</a> which included WordPress 7.2 Beta 3.</p>\n\n\n\n<h2 class=\"wp-block-heading\">How to Test WordPress 7.2 Beta 4</h2>\n\n\n\n<p class=\"wp-block-paragraph\">You can test WordPress 7.2 Beta 4 in any of the following ways:</p>\n\n\n\n<figure class=\"wp-block-table\"><table class=\"has-fixed-layout\"><tbody><tr><td><strong>WordPress Beta Tester Plugin</strong></td><td>Install and activate the <a href=\"https://wordpress.org/plugins/wordpress-beta-tester/\" rel=\"noreferrer noopener\" target=\"_blank\">WordPress Beta Tester</a> plugin on a WordPress install. Select the “Bleeding edge” channel and “Beta/RC Only” stream.</td></tr><tr><td><strong>Direct Download</strong></td><td>Download the <a href=\"https://wordpress.org/wordpress-7.2-beta4.zip\">Beta 4 version (zip)</a> and install it on a WordPress website.</td></tr><tr><td><strong>Command Line (WP-CLI)</strong></td><td>Use this <a href=\"https://make.wordpress.org/cli/\" rel=\"noreferrer noopener\" target=\"_blank\">WP-CLI</a> command: <br /><code>wp core update --version=7.2-beta4</code></td></tr><tr><td><strong>WordPress Playground</strong></td><td>Use a <a href=\"https://playground.wordpress.net/release\" rel=\"noopener\" target=\"_blank\">7.2 Beta 4 WordPress Playground instance</a> to test the software directly in your browser. No setup required-just click and go!</td></tr></tbody></table></figure>\n\n\n\n<p class=\"wp-block-paragraph\">The scheduled final release date for WordPress 7.2 is <strong><strong>December 8, 2026</strong></strong>. The full <a href=\"https://make.wordpress.org/core/2026/10/06/wordpress-7-2-release-party-schedule/\">release schedule can be found here</a>. Your help testing Beta and RC versions is vital to making this release as stable and powerful as possible. Thank you to everyone who contributes by testing!</p>\n\n\n\n<h2 class=\"wp-block-heading\">What&#8217;s in WordPress 7.2 Beta 4?</h2>\n\n\n\n<p class=\"wp-block-paragraph\">For technical details on the issues addressed since Beta 2, see the following links:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li><a href=\"https://core.trac.wordpress.org/query?status=closed&amp;changetime=10%2F27%2F2026..11%2F03%2F2026&amp;milestone=7.2&amp;group=component&amp;col=id&amp;col=milestone&amp;col=owner&amp;col=type&amp;col=priority&amp;order=id\">Closed 7.2 WordPress Core Trac tickets</a> since October 27, 2026</li>\n\n\n\n<li><a href=\"https://github.com/WordPress/gutenberg/commits/wp/7.2?since=2026-10-27&amp;until=2026-11-03\">7.2 Gutenberg commits</a> since October 27, 2026</li>\n</ul>\n\n\n\n<h3 class=\"wp-block-heading\">Continued Improvements to WordPress 7.2</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 Beta 4 continues refining the upcoming release with improvements to accessibility, editor reliability, and developer APIs, alongside additional bug fixes and compatibility updates.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Recent work includes improved keyboard focus visibility in Windows High Contrast mode, refinements to administration interfaces, and fixes for right-to-left block alignment and custom block spacing.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Developers will also benefit from continued improvements to the Abilities API, DataViews extensibility, and REST API behavior. Additional fixes strengthen revision handling, input validation, and compatibility across supported environments.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://core.trac.wordpress.org/ticket/45910\">Trac #45910</a>, <a href=\"https://core.trac.wordpress.org/ticket/66382\">Trac #66382</a>, <a href=\"https://core.trac.wordpress.org/ticket/66427\">Trac #66427</a>, <a href=\"https://core.trac.wordpress.org/ticket/66383\">Trac #66383</a>, <a href=\"https://core.trac.wordpress.org/ticket/66343\">Trac #66343</a>, <a href=\"https://core.trac.wordpress.org/ticket/66329\">Trac #66329</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">Continued Improvements to Ipsum</h3>\n\n\n\n<p class=\"wp-block-paragraph\">The new default theme, Ipsum, continues to receive refinements ahead of WordPress 7.2&#8217;s final release. Recent updates improve accessibility with clearer keyboard focus indicators, more descriptive screen reader links, and better support for right-to-left languages. Additional improvements refine block patterns, touch target spacing, and color palette compatibility with other default themes.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://core.trac.wordpress.org/ticket/66352\">Trac #66352</a>, <a href=\"https://github.com/WordPress/wordpress-develop/pull/15113\">GitHub #15113</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">Improved Translation Update Management</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 makes managing translation updates easier by displaying individual available updates on the Updates screen. Administrators can now review and selectively install translation updates, bringing language management in line with the familiar plugin and theme update experience.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://core.trac.wordpress.org/ticket/42281\">Trac #42281</a>, <a href=\"https://github.com/WordPress/wordpress-develop/pull/11610\">GitHub #11610</a></p>\n\n\n\n<h2 class=\"wp-block-heading\">How important is your testing?</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Testing for issues is a critical part of developing any software, and it’s a meaningful way for anyone to contribute – whether or not you have experience. <a href=\"https://make.wordpress.org/test/2026/10/20/help-test-wordpress-7-2/\">Details on what to test in WordPress 7.2 are available here</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you encounter an issue, please share it in the <a href=\"https://wordpress.org/support/forum/alphabeta/\" rel=\"noopener\" target=\"_blank\">Alpha/Beta area</a> of the support forums. If you are comfortable submitting a reproducible bug report, you can do so <a href=\"https://core.trac.wordpress.org/newticket\" rel=\"noopener\" target=\"_blank\">via WordPress Trac</a>. You can also check your issue against this list of <a href=\"https://core.trac.wordpress.org/tickets/major\" rel=\"noopener\" target=\"_blank\">known bugs</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Curious about testing releases in general and how to get started? Follow along with the <a href=\"https://make.wordpress.org/test/\">testing initiatives in Make Core</a> and join the <a href=\"https://wordpress.slack.com/messages/core-test/\">#core-test channel</a> on <a href=\"https://wordpress.slack.com/\">Making WordPress Slack</a>.</p>\n\n\n\n<h2 class=\"wp-block-heading\">A Beta 4 haiku</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Where did Beta Three go?<br />A surprise along the way<br />Four arrives on cue</em>.</p>\n\n\n\n<p class=\"has-text-align-right wp-block-paragraph\"><em>Props to <a class=\"mention\" href=\"https://profiles.wordpress.org/audrasjb/\"><span class=\"mentions-prefix\">@</span>audrasjb</a>, <a class=\"mention\" href=\"https://profiles.wordpress.org/courane01/\"><span class=\"mentions-prefix\">@</span>courane01</a>, <a class=\"mention\" href=\"https://profiles.wordpress.org/huzaifaalmesbah/\"><span class=\"mentions-prefix\">@</span>huzaifaalmesbah</a> for pre-publish review</em>.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 03 Nov 2026 15:45:29 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:14:\"David Baumwald\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:44;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:105:\"Open Channels FM: Protecting the Open Internet: Active Exploits, Coding Agents, and the French Tax Debate\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2566476\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:115:\"https://openchannels.fm/drupal-commerce-exploits-synology-ransomware-deepseek-coding-tools-and-frances-tax-on-data/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:124:\"Security issues challenge Drupal and Synology users as a French tax proposal threatens the VLC nonprofit’s sustainability.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 03 Nov 2026 15:00:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:45;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:61:\"Open Channels FM: Trusting the Machines Is the New Team Skill\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2566407\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:68:\"https://openchannels.fm/trusting-the-machines-is-the-new-team-skill/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:146:\"Building trust with AI agents and automation in software teams, focusing on code reviews, verification, and balancing innovation with reliability.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 03 Nov 2026 12:11:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:46;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:65:\"Open Channels FM: The Core Principles of the Open Web, Simplified\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2563857\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:60:\"https://openchannels.fm/the-core-principles-of-the-open-web/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:214:\"The open web is defined by five principles: open standards, permissionless publishing, linking, interoperability, and decentralization, ensuring freedom, flexibility, and user control in online information sharing.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 02 Nov 2026 12:28:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"Open Channels FM\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:47;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:58:\"WordCamp Central: WordCamp Sylhet 2026: No Swag, All Heart\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:40:\"https://central.wordcamp.org/?p=16593983\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:81:\"https://central.wordcamp.org/news/2026/11/wordcamp-sylhet-2026-no-swag-all-heart/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:11167:\"<p class=\"wp-block-paragraph\">What happens when you take the swag out of a WordCamp? You get more of what WordCamps were always about: people, ideas, and real conversations.</p>\n\n\n\n<p class=\"wp-block-paragraph\">On October 2 and 3, 2026, the WordPress community gathered at the Central Auditorium of Shahjalal University of Science and Technology (SUST) for WordCamp Sylhet 2026. This year the organizers made a bold call: no swag from the organizers and no swag from the sponsors. I was there for both days as an organizer, and it turned out to be one of the best WordCamp experiences I&#8217;ve had.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://central.wordcamp.org/files/2026/11/PROX9652-scaled.jpg\"><img alt=\"\" class=\"wp-image-16648810\" height=\"683\" src=\"https://central.wordcamp.org/files/2026/11/PROX9652-1024x683.jpg\" width=\"1024\" /></a></figure>\n\n\n\n<h2 class=\"wp-block-heading\">Third Time in the Tea Capital</h2>\n\n\n\n<p class=\"wp-block-paragraph\">WordCamp Sylhet first came to the city in May 2023 and returned in 2024. The 2026 edition was its third, back at the same SUST auditorium where it all started.</p>\n\n\n\n<p class=\"wp-block-paragraph\">This time the organizing team chose a clear theme: back to basics. Their message from the very first announcement was &#8220;less show, more substance.&#8221; As WordCamps grow, the focus can drift toward production, merchandise, and presentation. Sylhet wanted to bring the spotlight back to knowledge, genuine conversations, and community connections.</p>\n\n\n\n<p class=\"wp-block-paragraph\"></p>\n\n\n\n<h2 class=\"wp-block-heading\">What a Swag-Free WordCamp Feels Like</h2>\n\n\n\n<p class=\"wp-block-paragraph\">I&#8217;ll admit I was curious. Swag is part of the WordCamp ritual: the T-shirts, stickers, notebooks, and the queue at every booth. How would an event feel without it?</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://central.wordcamp.org/files/2026/11/PROX9655-scaled.jpg\"><img alt=\"\" class=\"wp-image-16648826\" height=\"683\" src=\"https://central.wordcamp.org/files/2026/11/PROX9655-1024x683.jpg\" width=\"1024\" /></a></figure>\n\n\n\n<p class=\"wp-block-paragraph\">The answer: lighter, warmer, and more focused. Nobody was rushing from table to table collecting goodies. Instead, people stopped and talked. Hallway chats ran longer. Lunch tables turned into mini-meetups. Questions after sessions were sharper because people came for the content.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Swag bags get forgotten in a drawer. A five-minute conversation with the right person can turn into a client, a job, or a friendship. WordCamp Sylhet 2026 proved that the community itself is the best takeaway.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://central.wordcamp.org/files/2026/11/PROX0491-scaled.jpg\"><img alt=\"\" class=\"wp-image-16648812\" height=\"683\" src=\"https://central.wordcamp.org/files/2026/11/PROX0491-1024x683.jpg\" width=\"1024\" /></a></figure>\n\n\n\n<h2 class=\"wp-block-heading\">Day One: Contributor Day</h2>\n\n\n\n<p class=\"wp-block-paragraph\">October 2 was Contributor Day, and around 150 people sat down at the contributor tables to give back to WordPress. The work ranged from bug fixes in Core to new designs for the Patterns Team.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://central.wordcamp.org/files/2026/11/829633909_1020752920993815_7895854680051380933_n.jpg\"><img alt=\"\" class=\"wp-image-16648813\" height=\"768\" src=\"https://central.wordcamp.org/files/2026/11/829633909_1020752920993815_7895854680051380933_n-1024x768.jpg\" width=\"1024\" /></a></figure>\n\n\n\n<p class=\"wp-block-paragraph\">What I love about Contributor Day is that you don&#8217;t need to be a senior developer to take part. Whether you code, write, design, translate, or test, there is a table for you. For many first-timers, it was the day they made their first contribution to one of the world&#8217;s largest open-source projects, shoulder to shoulder with the people who build it.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://central.wordcamp.org/files/2026/11/WhatsApp-Image-2026-11-01-at-21.10.45.jpeg\"><img alt=\"\" class=\"wp-image-16648825\" height=\"682\" src=\"https://central.wordcamp.org/files/2026/11/WhatsApp-Image-2026-11-01-at-21.10.45-1024x682.jpeg\" width=\"1024\" /></a></figure>\n\n\n\n<h2 class=\"wp-block-heading\">Day Two: Conference Day and the Rise of AI</h2>\n\n\n\n<p class=\"wp-block-paragraph\">October 3 was Conference Day, packed with talks and panel discussions from morning to evening. With the swag gone, the sessions really were the heart of the event.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If one topic ran through the whole schedule, it was AI. A few sessions that stood out:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li><strong>Panel: How AI Is Reshaping Modern Workflows.</strong> M Asif Rahman, MD Ershadur Rahman Talukder, and Shahjahan Jewel shared practical lessons on how AI is changing the way WordPress teams plan, build, and ship.</li>\n\n\n\n<li><strong>From Plugins to Agents.</strong> Nazmul Hasan Rupok explored how WordPress architecture is shifting as AI agents arrive, including using the WordPress Abilities API so any MCP client can use a plugin&#8217;s features.</li>\n\n\n\n<li><strong>Customer Support, Reimagined.</strong> Khan Rafin Ahmed showed how AI agents and the Model Context Protocol (MCP) help support teams do more.</li>\n\n\n\n<li><strong>Find It, Fix It, Prove It.</strong> Niluthpal Purkayastha talked about using AI to find and fix security holes in WordPress plugins.</li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\">The common message: AI isn&#8217;t replacing the WordPress community. It&#8217;s giving builders new tools, and Bangladesh&#8217;s developers are already putting them to work.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://central.wordcamp.org/files/2026/11/IMG_6882-scaled.jpg\"><img alt=\"\" class=\"wp-image-16648814\" height=\"768\" src=\"https://central.wordcamp.org/files/2026/11/IMG_6882-1024x768.jpg\" width=\"1024\" /></a></figure>\n\n\n\n<h2 class=\"wp-block-heading\">Sponsors Without Swag: Real Conversations at the Booths</h2>\n\n\n\n<p class=\"wp-block-paragraph\">No swag didn&#8217;t mean no sponsors. Companies still had booths in the expo area, and they still had a great chance to show what they&#8217;re building. The difference was the quality of the conversations.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Instead of handing out freebies, sponsor teams explained their products, heard feedback from users and met new people who were genuinely interested. Some booths ran friendly challenges and contests that broke the ice and started long chats.</p>\n\n\n\n<p class=\"wp-block-paragraph\">For businesses, that&#8217;s arguably worth more than a thousand tote bags. And it matters for the community too: WordCamps are nonprofit and volunteer-run, and sponsorship keeps tickets affordable for students, freelancers and first-timers.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://central.wordcamp.org/files/2026/11/PROX1825-scaled.jpg\"><img alt=\"\" class=\"wp-image-16648815\" height=\"683\" src=\"https://central.wordcamp.org/files/2026/11/PROX1825-1024x683.jpg\" width=\"1024\" /></a></figure>\n\n\n\n<h2 class=\"wp-block-heading\">The Energy: A Community That Showed Up</h2>\n\n\n\n<p class=\"wp-block-paragraph\">The most crucial part of WordCamp Sylhet 2026 wasn&#8217;t on the schedule. It was the energy.</p>\n\n\n\n<p class=\"wp-block-paragraph\">From the first Contributor Day table to the final session, the auditorium stayed full of enthusiasm. Students, developers, designers, freelancers, agency owners, and product teams came from across Bangladesh. Everyone was eager to learn, share, and connect, and you could feel it in every room and every hallway.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://central.wordcamp.org/files/2026/11/PROX1851-scaled.jpg\"><img alt=\"\" class=\"wp-image-16648828\" height=\"683\" src=\"https://central.wordcamp.org/files/2026/11/PROX1851-1024x683.jpg\" width=\"1024\" /></a></figure>\n\n\n\n<p class=\"wp-block-paragraph\">The green SUST campus, a short ride from Sylhet&#8217;s famous tea gardens, gave the whole event a calm and welcoming feel. It&#8217;s hard to imagine a better home for a community gathering.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://central.wordcamp.org/files/2026/11/PROX9743-scaled.jpg\"><img alt=\"\" class=\"wp-image-16648817\" height=\"683\" src=\"https://central.wordcamp.org/files/2026/11/PROX9743-1024x683.jpg\" width=\"1024\" /></a></figure>\n\n\n\n<h2 class=\"wp-block-heading\">Thank you, Sylhet.</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Organizing a two-day event for a community this size is never easy, and no event runs perfectly. What stays with you is the effort and heart behind it, and there was plenty of both.</p>\n\n\n\n<p class=\"wp-block-paragraph\">A huge thank you to the organizers and volunteers who made it happen, the speakers who shared their knowledge, the sponsors who supported the event and showed up for real conversations, and every attendee who brought their energy.</p>\n\n\n\n<p class=\"wp-block-paragraph\">WordCamp Sylhet 2026 showed that you don&#8217;t need freebies to make an event memorable. You need people who care. Back to basics turned out to be exactly what we needed.<br /><br /><img alt=\"🙏\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f64f.png\" style=\"height: 1em;\" /> <strong>A big thank you to the sponsors of WordCamp Sylhet 2026!</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">WordCamp Sylhet 2026 brought together WordPress enthusiasts, developers, designers, and community members at Shahjalal University of Science and Technology. It was possible because these organizations believed in our community and supported open source in Bangladesh.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><img alt=\"💎\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f48e.png\" style=\"height: 1em;\" /> <strong>Platinum Sponsors</strong><br />Automattic • Bluehost • FluentCart • FlyWP • Hostinger • Kirki • OneSuite • WooCommerce • xCloud</p>\n\n\n\n<p class=\"wp-block-paragraph\"><img alt=\"🥈\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f948.png\" style=\"height: 1em;\" /> <strong>Silver Sponsors</strong><br />Bit CRM • bPlugins</p>\n\n\n\n<p class=\"wp-block-paragraph\"><img alt=\"🥉\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f949.png\" style=\"height: 1em;\" /> <strong>Bronze Sponsors</strong><br />PaymentForm.io • SubscriptionPro • Timetics AI • WebAppick</p>\n\n\n\n<p class=\"wp-block-paragraph\">Thanks also to our micro sponsors and to every organizer, volunteer, speaker, and attendee who helped make it happen. <img alt=\"❤\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/2764.png\" style=\"height: 1em;\" /></p>\n\n\n\n<p class=\"wp-block-paragraph\">See you at the next WordCamp!</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://central.wordcamp.org/files/2026/11/PROX2018-1-scaled.jpg\"><img alt=\"\" class=\"wp-image-16648816\" height=\"682\" src=\"https://central.wordcamp.org/files/2026/11/PROX2018-1-1024x682.jpg\" width=\"1024\" /></a></figure>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Sun, 01 Nov 2026 15:04:39 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:12:\"Nazmul Hosen\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:48;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:138:\"WordCamp Central: WordPress Campus Connect at Presidency University: Building Skills, Exploring Careers, and Inspiring the Next Generation\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:40:\"https://central.wordcamp.org/?p=16625654\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:160:\"https://central.wordcamp.org/news/2026/10/wordpress-campus-connect-at-presidency-university-building-skills-exploring-careers-and-inspiring-the-next-generation/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:10330:\"<p class=\"wp-block-paragraph\">We’re excited to share that <strong>WordPress <a href=\"https://events.wordpress.org/campusconnect/2026/presidency-university-dhaka/\" rel=\"noopener\" target=\"_blank\">Campus Connect at Presidency University</a>, Dhaka, has successfully concluded!</strong> <img alt=\"🎉\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f389.png\" style=\"height: 1em;\" /></p>\n\n\n\n<p class=\"wp-block-paragraph\">Held on <strong>25–26 October 2026</strong>, this two-day initiative brought students closer to WordPress, practical website development, career opportunities, and the growing role of open-source education.</p>\n\n\n\n<div class=\"wp-block-jetpack-tiled-gallery aligncenter is-style-rectangular\"><div class=\"\"><div class=\"tiled-gallery__gallery\"><div class=\"tiled-gallery__row\"><div class=\"tiled-gallery__col\"><figure class=\"tiled-gallery__item\"><img alt=\"\" src=\"https://i0.wp.com/central.wordcamp.org/files/2026/10/DSC09292-1024x683.jpg?ssl=1\" tabindex=\"0\" /></figure></div><div class=\"tiled-gallery__col\"><figure class=\"tiled-gallery__item\"><img alt=\"\" src=\"https://i0.wp.com/central.wordcamp.org/files/2026/10/DSC09297-1024x683.jpg?ssl=1\" tabindex=\"0\" /></figure><figure class=\"tiled-gallery__item\"><img alt=\"\" src=\"https://i0.wp.com/central.wordcamp.org/files/2026/10/DSC09322-1024x683.jpg?ssl=1\" tabindex=\"0\" /></figure></div></div><div class=\"tiled-gallery__row\"><div class=\"tiled-gallery__col\"><figure class=\"tiled-gallery__item\"><img alt=\"\" src=\"https://i0.wp.com/central.wordcamp.org/files/2026/10/DSC09352-1024x683.jpg?ssl=1\" tabindex=\"0\" /></figure></div><div class=\"tiled-gallery__col\"><figure class=\"tiled-gallery__item\"><img alt=\"\" src=\"https://i0.wp.com/central.wordcamp.org/files/2026/10/DSC09389-1024x683.jpg?ssl=1\" tabindex=\"0\" /></figure></div><div class=\"tiled-gallery__col\"><figure class=\"tiled-gallery__item\"><img alt=\"\" src=\"https://i0.wp.com/central.wordcamp.org/files/2026/10/DSC09405-1024x683.jpg?ssl=1\" tabindex=\"0\" /></figure></div></div><div class=\"tiled-gallery__row\"><div class=\"tiled-gallery__col\"><figure class=\"tiled-gallery__item\"><img alt=\"\" src=\"https://i0.wp.com/central.wordcamp.org/files/2026/10/DSC09450-1024x683.jpg?ssl=1\" tabindex=\"0\" /></figure><figure class=\"tiled-gallery__item\"><img alt=\"\" src=\"https://i0.wp.com/central.wordcamp.org/files/2026/10/DSC09459-1024x683.jpg?ssl=1\" tabindex=\"0\" /></figure></div><div class=\"tiled-gallery__col\"><figure class=\"tiled-gallery__item\"><img alt=\"\" src=\"https://i0.wp.com/central.wordcamp.org/files/2026/10/DSC09456-1024x683.jpg?ssl=1\" tabindex=\"0\" /></figure></div></div><div class=\"tiled-gallery__row\"><div class=\"tiled-gallery__col\"><figure class=\"tiled-gallery__item\"><img alt=\"\" src=\"https://i0.wp.com/central.wordcamp.org/files/2026/10/DSC09551-1024x683.jpg?ssl=1\" tabindex=\"0\" /></figure></div><div class=\"tiled-gallery__col\"><figure class=\"tiled-gallery__item\"><img alt=\"\" src=\"https://i0.wp.com/central.wordcamp.org/files/2026/10/DSC09612-1024x683.jpg?ssl=1\" tabindex=\"0\" /></figure></div></div><div class=\"tiled-gallery__row\"><div class=\"tiled-gallery__col\"><figure class=\"tiled-gallery__item\"><img alt=\"\" src=\"https://i0.wp.com/central.wordcamp.org/files/2026/10/DSC09678-1024x683.jpg?ssl=1\" tabindex=\"0\" /></figure></div><div class=\"tiled-gallery__col\"><figure class=\"tiled-gallery__item\"><img alt=\"\" src=\"https://i0.wp.com/central.wordcamp.org/files/2026/10/DSC09692-1024x683.jpg?ssl=1\" tabindex=\"0\" /></figure><figure class=\"tiled-gallery__item\"><img alt=\"\" src=\"https://i0.wp.com/central.wordcamp.org/files/2026/10/DSC09704-1024x683.jpg?ssl=1\" tabindex=\"0\" /></figure></div></div><div class=\"tiled-gallery__row\"><div class=\"tiled-gallery__col\"><figure class=\"tiled-gallery__item\"><img alt=\"\" src=\"https://i0.wp.com/central.wordcamp.org/files/2026/10/DSC09710-1024x683.jpg?ssl=1\" tabindex=\"0\" /></figure></div></div></div></div></div>\n\n\n\n<p class=\"wp-block-paragraph\">Want to see more photos from WordPress Campus Connect at Presidency University?</p>\n\n\n\n<p class=\"has-text-align-center wp-block-paragraph\"> <img alt=\"📸\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f4f8.png\" style=\"height: 1em;\" /> Explore all the event photos here: <a href=\"https://drive.google.com/drive/folders/1aUaiC4XXShI2426W-4JW_zaBx5xf8ekv?usp=sharing\" rel=\"noopener\" target=\"_blank\">Official Event Photos</a>  <img alt=\"📸\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f4f8.png\" style=\"height: 1em;\" /></p>\n\n\n\n<h3 class=\"wp-block-heading\"><strong>Day 1: From Ideas to Websites</strong></h3>\n\n\n\n<p class=\"wp-block-paragraph\">On 25 October, we hosted a hands-on workshop where students explored WordPress by building their own websites. Together, we created <strong>50 websites and WordPress.org profiles</strong>, giving students a starting point to continue learning, experimenting, and engaging with the global WordPress community.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The goal was not just to introduce a tool, but to help students take their first practical steps toward building something of their own.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Few websites created by our students:</p>\n\n\n\n<ol class=\"wp-block-list\">\n<li><a href=\"https://noyonhossain.blog/\">https://noyonhossain.blog/</a></li>\n\n\n\n<li><a href=\"https://hurayra.art/\">https://hurayra.art/</a></li>\n\n\n\n<li><a href=\"https://www.golammonayem.com/\">https://www.golammonayem.com/</a></li>\n\n\n\n<li><a href=\"https://tayenhossainshuvo.blog/\">https://tayenhossainshuvo.blog/</a></li>\n\n\n\n<li><a href=\"https://ifatkhalilfahim.blog/\">https://ifatkhalilfahim.blog/</a></li>\n\n\n\n<li><a href=\"https://r-if-a.blog/\">https://r-if-a.blog/</a></li>\n\n\n\n<li><a href=\"https://rafid.blog/\">https://rafid.blog/</a></li>\n\n\n\n<li><a href=\"https://sanjidaaktersuborna.blog/\">https://sanjidaaktersuborna.blog/</a></li>\n\n\n\n<li><a href=\"https://byapon.art/\">https://byapon.art/</a></li>\n\n\n\n<li><a href=\"https://golammonayem.blog/\">https://golammonayem.blog/</a></li>\n\n\n\n<li><a href=\"https://belalhosenbadon.blog/\">https://belalhosenbadon.blog/</a></li>\n</ol>\n\n\n\n<h3 class=\"wp-block-heading\"><strong>Day 2: Exploring Careers and WordPress Education</strong></h3>\n\n\n\n<p class=\"wp-block-paragraph\">On 26 October, we shifted our focus to career guidance and educational opportunities. We discussed how students can develop practical skills, build a portfolio, contribute to open source, and explore career pathways in the WordPress ecosystem.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Through these conversations, we encouraged students to look beyond traditional academic learning and explore how real-world projects, community participation, and continuous learning can help them prepare for their future careers.</p>\n\n\n\n<h3 class=\"wp-block-heading\"><strong>Exploring WordPress Credits: Connecting Education with Real-World Experience</strong></h3>\n\n\n\n<p class=\"wp-block-paragraph\">An important part of the discussion was the <strong>WordPress Credits program</strong>, which offers universities an opportunity to connect academic learning with practical contributions to the WordPress open-source project.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We introduced the program as a potential pathway for students to go beyond learning WordPress and start contributing to a global project used by millions of people. Through structured learning, mentorship, and practical contribution opportunities, students can develop technical and collaborative skills while gaining experience in an international open-source community.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We were delighted by the university&#8217;s interest in this opportunity. <strong>Presidency University has already applied to join the WordPress Credits program</strong>, marking an encouraging step toward bringing WordPress education and contribution-based learning into its academic environment.</p>\n\n\n\n<p class=\"wp-block-paragraph\">This is an exciting opportunity to explore how students can apply their classroom knowledge to real-world projects, collaborate with the global WordPress community, and build a stronger foundation for their professional journeys.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We hope this initial engagement will lead to further collaboration between the university and the WordPress community, creating more opportunities for students to learn, contribute, and grow.</p>\n\n\n\n<h3 class=\"wp-block-heading\"><strong>Supported by the Global WordPress Community</strong></h3>\n\n\n\n<p class=\"wp-block-paragraph\">This initiative was made possible with support from the global WordPress community and its sponsors, who continue to invest in education and the next generation of talent.</p>\n\n\n\n<p class=\"wp-block-paragraph\">A special thank you to <strong><a href=\"https://kirki.com/\" rel=\"noopener\" target=\"_blank\">Kirki</a> for joining as our Gold Sponsor</strong> and supporting this educational initiative. Your support helps create meaningful opportunities for students to learn, build, and explore their future in the digital world.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We’re also grateful to the university, our speakers, volunteers, and everyone who contributed their time and energy to make these two days meaningful.<br /></p>\n\n\n\n<h2 class=\"wp-block-heading\">Organisers and Speakers</h2>\n\n\n\n<p class=\"wp-block-paragraph\">The success of WordPress Campus Connect at Presidency University was made possible by the dedication and collaboration of our organizing team: Mostofa Kamal Sagor, Muhibul Haque, Nasim Miah, and Rashed Hossain.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Our speakers <strong>Nasim Miah, Nazmul Asif, Pranto Dev, Mostofa Kamal Sagor and Muhibul Haque</strong> shared valuable insights on WordPress, web design, career opportunities, NLP, and prompt engineering. Through practical guidance and engaging discussions, they helped students explore new skills, understand the evolving tech industry, and discover opportunities in the WordPress and AI era. A big thank you to all our speakers for sharing their knowledge and inspiring the next generation!</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>The journey continues. Let’s keep building opportunities for the next generation through WordPress education!</strong> <img alt=\"🚀\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f680.png\" style=\"height: 1em;\" /></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 30 Oct 2026 14:42:22 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:13:\"Muhibul Haque\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:49;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:78:\"Open Channels FM: Who Controls Our Software, Open Channels News Week in Review\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2565779\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:84:\"https://openchannels.fm/who-controls-our-software-open-channels-news-week-in-review/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:200:\"This week\'s Open Channels News highlights tensions over AI in open source, new tools like GridCraft, corporate shifts towards open infrastructure, and the need for sustainable, user-driven technology.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 30 Oct 2026 12:31:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"Open Channels FM\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}}}}}}}}}}}}s:4:\"type\";i:128;s:7:\"headers\";a:10:{s:6:\"server\";s:5:\"nginx\";s:4:\"date\";s:29:\"Wed, 18 Nov 2026 14:27:00 GMT\";s:12:\"content-type\";s:8:\"text/xml\";s:13:\"last-modified\";s:29:\"Wed, 18 Nov 2026 14:15:31 GMT\";s:4:\"vary\";s:15:\"Accept-Encoding\";s:15:\"x-frame-options\";s:10:\"SAMEORIGIN\";s:16:\"content-encoding\";s:4:\"gzip\";s:7:\"alt-svc\";s:5:\"clear\";s:13:\"x-remembering\";s:58:\"Eric Binnion <https://friendsofericbinnion.wordpress.com/>\";s:4:\"x-nc\";s:9:\"HIT dca 1\";}s:5:\"build\";i:1795010177;s:21:\"cache_expiration_time\";i:1795055224;s:23:\"__cache_expiration_time\";i:1795055224;}','off');
